insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('d19f8535-c941-5748-affe-dcd5d6192513', 'מורד גיליס', 'מורד-גיליס', 'החיים מתחילים אצלנו', 'מורד גילי''ס היא רשת מובילה למוצרי תינוקות בישראל מאז 1974. הרשת מציעה מגוון של מוצרים איכותיים ובטיחותיים, כולל חבילות לידה, חדרי תינוקות, עגלות ומושבי בטיחות מהמותגים המובילים בעולם. לקוחות מורד גילי''ס נהנים משירות אישי ומקצועי, שירותים ייחודיים כגון ייעוץ מקצועי והתקנת מושבי בטיחות על ידי מתקינים מוסמכים וממחירים משתלמים בכל סניפי הרשת ובאתר האונליין.', '08-9221664', 'www.moradbaby.co.il', 'שדרות המלאכות 121, מודיעין מכבים רעות, ישראל', 31.8895148, 34.9657961, 'https://www.modiin4u.co.il/wp-content/uploads/2024/08/WhatsApp-Image-2024-08-20-at-10.07.58.jpeg', 'https://www.modiin4u.co.il/wp-content/uploads/2024/08/מורד-גיליס.jpg', 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('e7eea998-4ef4-5061-843c-fc122225d50a', 'שיבולת השרון-מודיעין', 'שיבולת-השרון', 'cafe & bakery', 'מאפיית שיבולת השרון שייכת לרשת מאפיות, הפועלת בתחום מאז שנת 1989, ומציעה מבחר של מאפים טריים שקשה לעמוד בפניהם. אנחנו מציעים ללקוחותיו מוצרים כשרים, העומדים בסטנדרטים גבוהים. המאפייה שמה דגש רב מאד על איכות ושימוש בחומרי גלם שנבחרו בקפידה רבה, וכן על מראה המאפה עצמו והאופן שבו הוא מוגש ללקוח. אצלינו אפשר ליהנות משלל של מוצרי מאפה טעימים וגם ממגוון עצום והפתעות המצרפות אליו בכל עת. בסניפים שלנו תמצאו מבחר של לחמניות, לחמים טריים, חלות מצוינות לקראת השבת, באגטים, פוקצ''ות, רוגלאך, פחזניות, עוגות למיניהן ועוד. כל אחד ממוצרים אלה עשוי מחומרים טבעיים וללא תוספת של חומרים משמרים.', '08-6171782', 'https://sharon-oats-bakery.com/', 'פיקוס 2, מודיעין מכבים רעות, ישראל', 31.9019165, 35.0092628, 'https://www.modiin4u.co.il/wp-content/uploads/2024/08/צילום-מסך-2024-08-26-ב-11.50.32.png', 'https://www.modiin4u.co.il/wp-content/uploads/2024/08/צילום-מסך-2024-08-26-ב-11.55.05.png', 5.0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
