insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('a9db3bba-2991-5c46-ac81-7fce6498d84b', 'אמריליס - Amaryllis', 'אמריליס-amaryllis-מכון-יופי-וקוסמטיקה-במודיע', 'מכון יופי ואסתטיקה במודיעין', 'שמי ליז צנגאוקר, ילידת העיר התחלתי את הדרך שלי בתחום הציפורניים לפני כעשור ולפני שנתיים זכיתי לפתוח את מכון היופי ״אמריליס״, המכון הוקם מתוך התשוקה להגשמה עצמית והוא האני מאמין שלי בחיים מבחינה אישית ומקצועית 🤍🙌🏼 במכון שלי תמצאו נשות צוות מקצועיות, נעימות ושרותיות שעברו הכשרות מקצועיות וישמחו לתת לכם את השרות המקצועי, הטוב והאדיב ביותר בכל זמן נתון . אצלנו תהנו מזמן איכות ופינוק לעצמכם, תוכלו לרכז את כלל הטיפולים במקום אחד ולהנות מלייזר לנשים וגברים, ציפורניים בכל השיטות, פדיקור קוסמטי ורפואי, גבות שפם, הרמת ריסים וגבות ועוד…. השרות והמענה ללקוח הם מעל הכל בשבילי והחוויה שלכם זאת ההצלחה שלי, נשמח לתת לכם שרות 🙌🏼 שרותים : - לייזר לנשים וגברים - ציפורנים בכל השיטות - ⁠פדיקור סטנדרטי ורפואי - ⁠גבות+שפם - ⁠הרמת ריסים וגבות - ⁠שעווה בכל הגוף - ⁠אפילציה - ⁠טיפול פנים', '0543015981', null, 'דם המכבים 39, מודיעין מכבים רעות, ישראל', 31.9039428, 35.0067707, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/IMG_9761.jpg', 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/WhatsApp-Image-2024-11-17-at-11.03.02.jpeg', 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
