insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('1c45218a-ab35-5877-805a-cbeb8f4d46a3', 'פינולי - PINOLI', 'pinoli-modiin', 'גלידה איטלקית בעבודת יד', 'פינולי - גלידריה איטלקית אותנטית במע"ר מודיעין. כל כדור גלידה הוא יצירת מופת, עשוי מחומרים טריים ואיכותיים, ומכינים אותו בעבודת יד מול עיניכם. בנוסף לגלידה המפנקת, תוכלו ליהנות מבית קפה נעים עם מגוון קפה משובח ומאפים טריים. בואו להתפנק בחוויה איטלקית אמיתית במרכז מודיעין!', '054288680', 'https://www.pinoli.co.il/', 'דם המכבים 30, מודיעין מכבים רעות, ישראל', 31.9061025, 35.005832, 'https://www.modiin4u.co.il/wp-content/uploads/2025/01/WhatsApp-Image-2024-12-31-at-11.21.43.jpeg', 'https://www.modiin4u.co.il/wp-content/uploads/2025/01/WhatsApp-Image-2025-01-05-at-22.08.41.jpeg', 5.0, 'none', true, true, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
