insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('86df674e-37dd-516e-957f-a0f2c5b350b3', 'ספר נשים במודיעין - אייל לוי', 'eyal-levi-hair-designer', 'ספר נשים במודיעין', 'אייל לוי - ספר נשים במודיעין מחפשים מעצב שיער מקצועי ומנוסה במודיעין? אייל לוי, עם ניסיון של 20 שנה בתחום, מעניק לכל לקוח טיפול אישי ומקצועי. אצלנו תיהנו מחוויה ייחודית של יופי וטיפוח, תוך שימוש במוצרים איכותיים ובטכנולוגיות מתקדמות. מה אנחנו מציעים: תספורות מדויקות ומעוצבות: בין אם אתם מעדיפים תספורת קלאסית או מראה מודרני ואופנתי, אצלנו תמצאו את התספורת המושלמת עבורכם. צבעי שיער מקצועיים: מגוון רחב של צבעים וגוונים, החל מצבעים טבעיים ועד לצבעים נועזים ומיוחדים. גוונים והאירות: הוסיפו מימד נוסף לשער שלכם עם גוונים והאירות עדינים או בולטים. תוספות שיער איכותיות: חלמתם על שיער ארוך ועבות? אצלנו תמצאו מגוון רחב של תוספות שיער איכותיות. טיפולים משקמים: השיבו לשער שלכם את הברק והחיוניות עם טיפולים משקמים מקצועיים. למה לבחור בנו? ניסיון: 20 שנות ניסיון בתחום עיצוב השיער מקצוענות: שימוש במוצרים מקצועיים וטכנולוגיות מתקדמות אישיות: התאמה אישית של התסרוקת לכל לקוח אווירה נעימה: חווית סלון מפנקת עדכונים: מעקב אחר מגמות האופנה העדכניות התקשרו אלינו עוד היום וקבעו תור:', '051-2214464', null, 'יששכר 44, מודיעין מכבים רעות, ישראל', 31.8846721, 35.001664, 'https://www.modiin4u.co.il/wp-content/uploads/2025/01/WhatsApp-Image-2025-01-16-at-17.27.04.jpeg', 'https://www.modiin4u.co.il/wp-content/uploads/2025/01/WhatsApp-Image-2025-01-16-at-17.30.10-scaled.jpeg', 5.0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
