insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('a771cc22-cbdc-571c-a92a-517c601b79d5', 'לק ג׳ל במודיעין - sk nails', 'modiin-lak-gel', 'לק ג׳ל במודיעין והרמת ריסים', 'לק ג׳ל במודיעין - לק ג''ל מושלם במודיעין? הגעת למקום הנכון! אנחנו מזמינות אותך לחוות את הקסם של לק ג''ל מושלם, עמיד לאורך זמן ומלא ברק. צוות המומחות שלנו ישמח לטפל בך ולהעניק לך מראה מטופח ומרשים. למה לבחור בנו? לק ג''ל אנטומי: מותאם אישית לצורת הציפורן שלך. הרמת ריסים וגבות: השלמה מושלמת למראה המטופח. ניסיון ומומחיות: שנים של ניסיון בתחום. מיקום נוח: במרכז העיר מודיעין. התקשרי עכשיו לקביעת תור: 0548373813', '⁦+97254-837-3813⁩', null, 'עמק דותן 48, מודיעין מכבים רעות, 71700, ישראל', 31.8995188, 35.0162469, 'https://www.modiin4u.co.il/wp-content/uploads/2025/01/WhatsApp-Image-2025-01-17-at-11.49.57.jpeg', 'https://www.modiin4u.co.il/wp-content/uploads/2025/01/WhatsApp-Image-2025-01-17-at-11.52.58-1.jpeg', 5.0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
