insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('318813f1-7e1f-55a4-8c55-3f78dd685efd', 'באבאג''ים - מודיעין', 'babajum-modiin', 'שווארמה גריל', 'באבאג''ים מודיעין – הבית לשווארמה ובשרים איכותיים. מאז 2008 אנו מגישים שווארמה פרגית ושווארמה עגל אנטריקוט במתכון ייחודי, לצד מגוון בשרים על האש, פלאפל טרי, מעל 25 סוגי סלטים ופיתות הנאפות במקום. המסעדה כשרה וממוקמת בעמק דותן 66, מרכז מרל"ז, מודיעין. מציעים שירותי משלוחים וטייק-אווי. הזמינו עכשיו ותיהנו מטעמים משובחים', '08-926-6628', null, 'עמק דותן 96, מודיעין מכבים רעות, ישראל', 31.8999208, 35.0137882, null, null, 0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('16d2c492-149f-5245-acbd-3d2b98c9bc77', 'לוצ''נה מודיעין', 'luciana-modiin', 'מסעדה איטלקית כשרה למהדרין', 'לוצ''נה מודיעין - מסעדה איטלקית כשרה למהדרין בשדרות המלאכות 1, ישפרו סנטר. מציעה תפריט עשיר עם פסטות, פיצות, דגים וקינוחים בעבודת יד, באווירה בהשראת מילאנו.', '08-690-1111', 'https://lucianamodiin.co.il/', 'שדרות המלאכות 23, מודיעין מכבים רעות, ישראל', 31.8898726, 34.9624638, null, null, 0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('b51a78a8-df1b-5b28-b3ea-0655d757554c', 'רוסטרס - Roasters מודיעין', 'roasters-modiin', 'בית קפה וקלייה בבוקר, ובר שכונתי בערב', 'רוסטרס החל את דרכו בשנת 2014 כאספרסו בר הראשון בשוק מחנה יהודה והביא איתו לבירה את חוויות הקפה דור שלישי בשילוב בר אלכוהול ויין. מאז התרחבנו ל-4 סניפים נוספים, בהם Roasters מודיעין ברחוב דם המכבים 55. במקום תמצאו את הקפה הטרי שלנו שנקלה במקום, לצד קונדיטוריה, וכריכים מעולים בבוקר. בערב ה-Roasters הופך לבר יין עם מגוון מנות מיוחדות, טאפאסים וגבינות.', '08-860-6880', 'https://roastersjlm.co.il/pages/modiin-branch?gad_source=1&amp;gclid=CjwKCAiAqrG9BhAVEiwAaPu5zj02x0qgF2NUwBIfCGOQn49lKp-0kuvWGP91aLZI-vjHAzBnBD_BBhoCto4QAvD_BwE', 'דם המכבים 55, מודיעין מכבים רעות, ישראל', 31.9036444, 35.0072506, 'https://www.modiin4u.co.il/wp-content/uploads/2025/02/לוגו-מושלם.png', 'https://www.modiin4u.co.il/wp-content/uploads/2025/02/WhatsApp-Image-2025-02-12-at-12.33.02-2.jpeg', 5.0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
