insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('628fa6c6-688a-59a7-9dbc-8534de556268', 'ג''פניקה מודיעין | JAPANIKA MODIIN', 'japanika-modiin', 'סושי בר מודיעין', 'ג''פניקה מודיעין מביאה את המטבח האסייתי עד אליכם – עם תפריט מגוון של סושי, נודלס, מוקפצים וקינוחים ייחודיים. המקום כשר, מעוצב באווירה צעירה ומזמין ומתאים לארוחת צהריים קלילה, בילוי ערב או טייק אוויי מהיר. ממוקם בלב העיר, עם שירות מקצועי וטעמים ממכרים.', '03-723-6100', 'https://japanika.net/', 'דם המכבים 32, מודיעין מכבים רעות, ישראל', 31.9046688, 35.0062847, null, null, 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
