insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('9c4a183b-1872-585e-9cf3-f438a69f769a', 'בצל התאנה מודיעין', 'betzel-hateena-modiin', 'טעימה ישראלית', 'בצל התאנה: טעם מקומי, גאווה ישראלית ברוכים הבאים ל"בצל התאנה" - המקום בו האדמה פוגשת את הצלחת, והמסורת פוגשת את הטעם המודרני. אצלנו, בליבה של מודיעין, הקמנו בית חם לחומר גלם משובח ולמוצרי איכות שהם כחול לבן אמיתי. אנחנו מאמינים בפשטות, באיכות ובאהבה לתוצרת הארץ. כאן תמצאו מבחר עשיר ומוקפד של יינות ישראליים משובחים, כל אחד מספר סיפור על הכרמים והאדמה שלנו. לצדם, מתגאים בגבינות בוטיק עשירות טעם, דגים כבושים במתכון ביתי, ירקות כבושים פריכים, לחמי מחמצת ריחניים וכריכים מלאי השראה. את כל הטוב הזה אנחנו שמחים להגיש לכם כאן, באווירה נעימה ופסטורלית, המזמינה רגע של נחת מהמירוץ היומיומי. ואם חשקה נפשכם לקחת את הטעם הייחודי הזה הביתה, תוכלו לרכוש אצלנו את חומרי הגלם האיכותיים שלנו וליהנות מהם במטבח הפרטי שלכם. "בצל התאנה" הוא יותר מעוד מקום - הוא חיבור לזהות שלנו, תמיכה בעסקים מקומיים ויצירה של קהילה אוהבת טעם ואיכות. בואו לגלות את הטעם האמיתי של ישראל! 🇮🇱', '08-6415515', null, 'דם המכבים 38, מודיעין מכבים רעות, ישראל', 31.90385969999999, 35.0066062, 'https://www.modiin4u.co.il/wp-content/uploads/2025/02/צילום-מסך-2025-05-01-ב-14.11.52.png', 'https://www.modiin4u.co.il/wp-content/uploads/2025/02/493361968_10226964331125566_1181975767061576304_n-1.jpg', 5.0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
