insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('0ddd28bf-efc4-5438-bb54-7e605c2d8038', 'קנטונה CANTONA', 'modiin-cantona', 'בית קפה מסעדה', 'קנטונה: החוויה מתחילה כאן ברוכים הבאים לקנטונה - בית הקפה החדש והמרענן במתחם אילה 360 (ישפרו סנטר)! אצלנו, אנו מציעים חוויה ייחודית של הגשה עצמית המאפשרת לכם לבחור בדיוק את מה שמתחשק לכם, בקצב שלכם. הקמנו עבורכם מתחם מעוצב בקפידה, נעים ומזמין, שבו תוכלו ליהנות מרגע של הפוגה מהשגרה. אנו גאים להגיש לכם מדי יום מגוון עשיר של אוכל טרי וטעים, המורכב מחומרי גלם איכותיים ומוכנים באהבה. בתפריט שלנו תמצאו קפה משובח ועשיר שיעיר אתכם בבוקר או יפנק אתכם אחר הצהריים. לצד הקפה, תוכלו לבחור מתוך מבחר מפתה של מאפים טריים וריחניים, כריכים מושקעים עם מילויים מגוונים, סלטים בריאים וצבעוניים, ופסטות טריות וטעימות. כל מנה מוכנה כדי לספק לכם חוויה קולינרית מהנה ומשביעה. בקנטונה, אנו מאמינים בשילוב של איכות, נוחות ואווירה טובה. בואו ליהנות מהשירות הידידותי, מהעיצוב המוקפד ומהטעמים הנפלאים שמחכים לכם כאן. קנטונה הוא המקום המושלם להתחיל בו את היום, להיפגש עם חברים, לעבוד בנחת או פשוט להתפנק עם ארוחה קלה וטעימה. נשמח לראותכם בקרוב בקנטונה', '077-938-6188', 'https://www.cantona.co.il/', 'אילה 360, שדרות המלאכות 21, קומה 5A בניין, מודיעין מכבים רעות, ישראל', 31.8889018, 34.9636272, 'https://www.modiin4u.co.il/wp-content/uploads/2025/02/צילום-מסך-2025-05-01-ב-14.28.33.png', 'https://www.modiin4u.co.il/wp-content/uploads/2025/02/MOYAL-02767-scaled.jpg', 3.666665, 'none', false, true, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
