insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('590a2ef3-a39f-562f-9ef5-ad2a496d803a', 'שמבז | Shambaz', 'שמבז-shambaz', 'בר מסעדה', 'שמבז הוא בר-מסעדה כפרי בלב מכבים, המשלב בין תפריט שף מוקפד לאווירה חמימה ומוזיקה חיה. המקום מציע חוויית בילוי יוצאת דופן – עם עיצוב עץ ייחודי, קוקטיילים מעולים, הופעות חיות, מסיבות ואירועים פרטיים עד 80 אורחים. מתאים לדייט רומנטי, בילוי עם חברים או חגיגה משפחתית באווירה קסומה.', '08-920-0316', 'https://shambazbar.co.il/', '99 נוף קדומים, מודיעין מכבים רעות 7170834', 31.892181, 35.033947, null, null, 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('675dfe6e-744b-5245-9b65-2e06a8853d58', 'מיטמן - שילת', 'מיטמן-שילת', 'קצבייה', 'מיטמן שילת מודיעין היא הרבה יותר מעוד קצבייה – זו חגיגה אמיתית של בשר. תמצאו כאן נתחי בשר מובחרים, בשרים מיושנים בקפידה, עופות, תוספות, תבלינים ומעדנים איכותיים מכל הסוגים. הצוות המקצועי מעניק שירות אישי, ייעוץ קולינרי והתאמה מושלמת לכל מנה. מושלם למי שאוהב בשר – ומעריך איכות.', '08-854-4434', 'https://meatman.co.il/', 'אזור תעשייה, שילת', 31.921173, 35.014572, null, null, 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
