insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('57f654ca-2971-5a75-96fd-47812d7bd54c', 'חוות נעמי', 'havat-neomi-modiin', 'מעדניות מאז 1051', 'מעדניית חוות נעמי מעניקה לכם חוויה ארומתית של גבינות טריות ואיכותיות, מהמחלבות המובילות בעולם, ישירות אל הסל שלכם. חוות נעמי מתהדרת במעדניית גבינות ונקניקים עשירה ואיכותית, ביצי משק טריות מהלולים המובחרים והאכותיים ביותר. אנו מאמינים בטעמם של אנשים לבחור את המוצרים האיכותיים ביותר, ובצורך שלהם להעניק לעצמם מוצרים מובחרים. לכן, אנו מקפידים על איכות וטריות ללא פשרות, על טעם מעודן, ועל מבחר של מוצרים מהארץ והעולם', '0775640445', 'https://nfarm.co.il/?gad_source=1', 'דרך מנחם בגין 20, מודיעין מכבים רעות, ישראל', 31.8798648, 35.0186781, 'https://www.modiin4u.co.il/wp-content/uploads/2025/03/צילום-מסך-2025-03-23-ב-17.37.39.png', 'https://www.modiin4u.co.il/wp-content/uploads/2025/03/WhatsApp-Image-2025-03-23-at-17.56.52.jpeg', 5.0, 'none', true, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
