insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('affc96ae-b62f-5a12-93c5-aa3a5d1c59c7', 'ביקור רופא מודיעין', 'bikurofe-modiin', 'מוקד לרפואה דחופה', 'מוקד לרפואה דחופה במודיעין של ביקורופא נותן שירות לתושבי מודיעין והסביבה, הזקוקים לטיפולים רפואיים דחופים ומידיים. הצוות הרפואי המקצועי והמסור במוקד ביקורופא מודיעין מיומן ומנוסה במתן מגוון טיפולים רפואיים דחופים, ויעשה הכל כדי שאתם תקבלו את הטיפול המדויק והאיכותי ביותר במהירות וללא המתנה ארוכה. פניה לביקורופא במודיעין תחסוך לכם את ההגעה למיון ותפחית את סכנת החשיפה לזיהומים בבית החולים. במוקד קיים גם מערך לקביעת תורים, שירותי מזכירות רפואית איכותית ועוד', '08-975-0700', 'https://www.bikurofe.co.il/kfar-5-2-2/', 'רא"ל יגאל ידין 41, מודיעין מכבים רעות, ישראל', 31.90446, 35.0041736, 'https://www.modiin4u.co.il/wp-content/uploads/2025/04/צילום-מסך-2025-04-15-ב-10.40.43.png', 'https://www.modiin4u.co.il/wp-content/uploads/2025/04/M4U-2025-04-15T104332.405.png', 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
