insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('617fdb22-095d-5cfa-9142-053fac3c9c17', 'סיאסטה משקאות מודיעין', 'סיאסטה-משקאות-מודיעין', 'חנות יין ואלכהול', 'סיסאטה משקאות ברוכים הבאים לסיסאטה משקאות - המקום שלכם לגלות, להתאהב וליהנות מעולם עשיר של אלכוהול ויינות משובחים. אנחנו לא רק חנות משקאות, אלא בית לחובבי טעם, למי שמחפש את הייחודיות שבבקבוק, ולכל מי שרוצה להרים את הכוס – באיכות ובסטייל. התשוקה שלנו למשקאות איכותיים היא הלב הפועם של סיסאטה. אנחנו בוחרים בקפידה כל בקבוק, החל ממבחר יינות בוטיק מרתקים מיקבים מקומיים ובינלאומיים, דרך וויסקי סינגל מאלט בעל אופי עמוק, ועד קוקטיילים מרעננים ובירות מלאכה עם טוויסט. אצלנו תמצאו לא רק מגוון רחב, אלא גם ידע מקצועי ויחס אישי. הצוות שלנו כאן כדי להקשיב לטעם שלכם, להמליץ על המשקה המושלם לכל אירוע או סתם לערב רגוע בבית, ולחלוק איתכם את הסיפורים שמאחורי כל בקבוק. בין אם אתם אניני טעם ותיקים או רק מתחילים את המסע בעולם המשקאות, בסיסאטה תרגישו בבית. אנחנו מזמינים אתכם לבקר אותנו, לטעום, לשאול ולהצטרף לקהילה שלנו של אוהבי משקאות איכותיים. לחיים!', '08-972-0002', null, 'צאלון 19, מודיעין מכבים רעות, ישראל', 31.906576, 35.0166382, 'https://www.modiin4u.co.il/wp-content/uploads/2025/05/416063570_707804524785505_484229630707250232_n.jpg', null, 0, 'rabbanut', true, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
