insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('12d60623-0f50-581f-9d06-c3149ee2ac6b', 'בית השף מודיעין', 'בית-השף-מודיעין', 'חלל ארועי בוטיק כשר מודיעין', 'בית השף במכבים ברוכים הבאים לבית השף במכבים, חלל בוטיק ייחודי לאירועים בלתי נשכחים. כאן, באווירה אינטימית וקסומה, אנו יוצרים את התפאורה המושלמת לכל חגיגה, מפגש עסקי או אירוע פרטי שתמיד חלמתם עליו. הקונספט שלנו משלב את תשוקתנו לאירוח מושלם עם אהבה עמוקה לקולינריה עילית. החלל שלנו עוצב בקפידה כדי להעניק לכם ולאורחים שלכם חוויה בלתי מתפשרת, עם דגש על הפרטים הקטנים שהופכים כל אירוע למיוחד במינו. בין אם אתם מתכננים אירוע משפחתי חם, כנס עסקי אלגנטי או חגיגה אינטימית עם חברים קרובים, בית השף במכבים מציע גמישות עיצובית ושירות אישי ומסור, כדי להתאים את החלל בדיוק לצרכים ולחלומות שלכם. הצוות המקצועי שלנו, בעל ניסיון רב בתחום האירועים, ילווה אתכם לאורך כל הדרך - משלב התכנון ועד לביצוע המושלם ביום האירוע עצמו. אנו מאמינים שכל אירוע הוא סיפור ייחודי, ואנו כאן כדי לעזור לכם לספר את הסיפור שלכם בצורה הטובה ביותר. מזמינים אתכם ליצור איתנו קשר, להתרשם מהחלל המיוחד שלנו ולתת לנו להפוך את האירוע הבא שלכם לחוויה בלתי נשכחת בלב מכבים.', '054-360-0013', 'https://beithachef.co.il/', 'קומת קרקע, 1 Sderat HaMaccabim, Modi''in-Maccabim-Re''ut', 31.88904479999999, 35.0342201, 'https://www.modiin4u.co.il/wp-content/uploads/2025/05/צילום-מסך-2025-05-18-ב-11.52.39.png', null, 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
