insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('9c60a072-75a4-5aa1-8b16-de49f2ef69c1', 'פיצה סמיילי מודיעין', 'פיצה-סמיילי-מודיעין', 'פיצרייה', 'פיצה סמיילי מודיעין ברוכים הבאים למקום שבו הטעם פוגש חיוך! פיצה סמיילי מודיעין היא יותר מסתם פיצריה - אנחנו משפחה שאוהבת פיצה, ורוצים לחלוק את האהבה הזו עם כל תושבי מודיעין והסביבה. הסיפור שלנו התחיל מתוך תשוקה לבצק איכותי, גבינה משובחת ותוספות טריות ונדיבות. במשך השנים, למדנו, ניסינו ושיפרנו כל מתכון כדי להגיע לפיצה המושלמת - כזו שמשאירה חיוך על הפנים אחרי כל ביס. אצלנו תמצאו מגוון רחב של פיצות קלאסיות וייחודיות, עם אפשרות לבחור את התוספות האהובות עליכם וליצור את הפיצה החלומית שלכם. אנחנו משתמשים רק בחומרי גלם טריים ואיכותיים, כי אנחנו מאמינים שזה הסוד לפיצה טעימה באמת. פיצה סמיילי זה לא רק טעם - זה גם חוויה. אנחנו שמים דגש על שירות חם וידידותי, ורוצים שתרגישו אצלנו כמו בבית. בין אם אתם מזמינים משלוח, באים לאסוף או סתם עוברים בסביבה - אנחנו תמיד שמחים לראות אתכם ולראות את החיוך שלכם אחרי שטעמתם את הפיצה שלנו. אז בפעם הבאה שמתחשק לכם פיצה מפנקת עם טעם של בית וחיוך בצד - אתם יודעים לאן לפנות! פיצה סמיילי מודיעין - כי פיצה טובה מתחילה בחיוך!', '08-926-4413', null, 'חסידה‬‎ 21, מודיעין מכבים רעות, ישראל', 31.8960237, 34.9964661, null, null, 0, 'rabbanut', true, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
