insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('8f46b9c0-30eb-5623-b928-3794b486ad26', 'קורסיה בית של טעמים', 'korsia-modiin', 'חנות תבלינים', 'חנות שיש בה הכל מחפשות שם כללי - שם משפחה קורסיה אקדמיה לתבלינים עניין של טעם - על טעם ועל ריח הפיצוחיה של קורסיה קיימת עשר שנים - שמונה חודשים האחרונים ניהלה את החנות מרכז מרלד במודיעין מרכזי בעיר שכונתי, כל הזמן תוסס, תנועה', '054-420-1021', null, 'עמק דותן 96, מודיעין מכבים רעות, ישראל', 31.8999208, 35.0137882, 'https://www.modiin4u.co.il/wp-content/uploads/2025/06/צילום-מסך-2025-06-15-ב-14.07.17.png', 'https://www.modiin4u.co.il/wp-content/uploads/2025/06/WhatsApp-Image-2024-07-30-at-17.21.20.jpeg', 0, 'rabbanut', true, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
