insert into entity_categories (entity_type, entity_id, category_id) values ('business', '8f46b9c0-30eb-5623-b928-3794b486ad26', '3c1fa078-02a0-59bb-be42-544b5aa0e2e7') on conflict do nothing;
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('55cc9de3-66af-57c7-9dbf-c2030719b15a', 'הולי בייגל מודיעין', 'holybagel-modiin', 'בית קפה/קייטרינג חלבי', 'ברוכים הבאים להולי בייגל מודיעין! אנחנו הבית של הבייגל הניו-יורקי האמיתי, ישר אליכם למודיעין. אצלנו תמצאו חוויה קולינרית שהיא הרבה יותר מסתם בייגל – זו מסורת, זו איכות, וזו אהבה לטעמים. אנחנו אופים את הבייגלים שלנו במקום, טריים-טריים, כל יום מחדש. הבצק עובר תהליך מסורתי של התפחה איטית וקצרה במי קרח, ואז נאפה בתנור אבן לוהט, בדיוק כמו בניו יורק. התוצאה? בייגל פריך מבחוץ, רך ואוורירי מבפנים, עם ארומה משגעת שתגרום לכם להתמכר. אבל זה לא רק הבייגל! תוכלו ליהנות אצלנו ממגוון רחב של מילויים מטורפים – החל מסלטים עשירים, גבינות בוטיק, ירקות טריים שנקצצים במקום, ועד דגים מעושנים ואיכותיים. הכל מוגש עם הרבה אהבה, חיוך, ובתור סנדוויצ''ים שהם ארוחה שלמה. בהולי בייגל מודיעין, אנחנו מאמינים בחומרי גלם טריים ואיכותיים, ובשירות שהוא תמיד עם חיוך. בין אם אתם קופצים לקחת בייגל בדרך לעבודה, או מתיישבים לארוחת בוקר מפנקת עם חברים, אנחנו פה כדי לתת לכם חוויה שכיף לחזור אליה. בואו לבקר אותנו – מחכים לכם עם בייגל חם וטעים!', '08-970-2606', 'holybagel.cafe', 'אבני חושן 15, מודיעין מכבים רעות, ישראל', 31.9027357, 34.9969096, null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/06/WhatsApp-Image-2025-06-16-at-11.23.43.jpeg', 0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
