insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('d7557fa1-115b-50fa-963a-a978e4040d50', 'בנדיקט מודיעין', 'benedict-modiin', 'מסעדת ארוחות בוקר', 'בוקר אורבני המסעדה העשירית, בנדיקט מודיעין נפתחה ביום הראשון של העשור החדש 2020 ומביאה איתה למודיעין את מקדש ארוחות הבוקר. שעות פתיחה: אחרי תקופה קצרה של הפסקה, אנחנו חוזרים, רעננים מתמיד! מסעדת בנדיקט מודיעין פותחת את שעריה מחדש עם הנהלה חדשה, אנרגיות חדשות, וצוות שמחכה רק לכם. מזמינים אתכם להרצה חגיגית – עם המון הפתעות מאיתנו א-ש 8:00-22:00', '03-686-8657', 'benedict.co.il', 'צאלון 1, מודיעין מכבים רעות, ישראל', 31.9085009, 35.0138348, null, null, 0, 'none', false, true, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
