insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('ec794573-a5ec-5f6b-9e1b-43859595ec02', 'אליבי רום מודיעין', 'alibi-room-modiin', 'בר קוקטיילים', 'אליבי רום – בר הקוקטיילים שמביא את חווית הבילוי התוססת של מרכז תל אביב, ישר ללב מודיעין. אנחנו מאמינים שבילוי טוב מתחיל באווירה נכונה. לכן, יצרנו עבורכם חלל ייחודי ומושקע, המשלב עיצוב מודרני עם נגיעות קלאסיות, מוזיקה מעולה שמתאימה לכל מצב רוח, ותחושה חמימה ומזמינה שתגרום לכם להרגיש בבית. התפריט שלנו נבנה בקפידה, עם דגש על איכות וחדשנות. תמצאו אצלנו מבחר עשיר של קוקטיילים קלאסיים וייחודיים, הנרקחים במקצועיות על ידי הברמנים המוכשרים שלנו, לצד מגוון בירות קראפט ישראליות מובחרות ויינות איכותיים. ומה לגבי האוכל? אנחנו לא עוד סתם בר! המטבח שלנו מציע מנות שף מקוריות וטעימות, המבוססות על חומרי גלם טריים ועונתיים, והן משלימות בצורה מושלמת את חווית השתייה. באליבי רום, כל ערב הוא חגיגה. אנחנו מארחים הופעות חיות של אמנים מוכשרים, ומקפידים על אווירה שמחה וקלילה. בימים ראשון עד חמישי, אתם מוזמנים ליהנות מאפרטיבו משתלם במיוחד עם 30% הנחה על כל התפריטים! אם אתם מחפשים מקום לצאת לבלות עם חברים, לדייט רומנטי, או פשוט ליהנות מערב רגוע עם משקה טוב ואוכל משובח – הגעתם למקום הנכון.', '08-917-4598', 'https://www.alibiroom-modiin.com/', 'דם המכבים 39, מודיעין מכבים רעות, ישראל', 31.9039428, 35.0067707, 'https://www.modiin4u.co.il/wp-content/uploads/2025/06/475834112_646340357917181_8263817618209898666_n.jpg', 'https://www.modiin4u.co.il/wp-content/uploads/2025/06/473176475_18016967294653454_8426986521501855875_n.jpg', 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('f221f1ee-4652-5652-ae42-45e9e3386fcd', 'o-spa | ספא ראש מודיעין', 'o-spa', 'ספא ראש במודיעין', 'מותג טיפולי הראש היפני נחת כאן במודיעין ומביא עמו קונספט טיפולי ייחודי המתמקד בהרפיה עמוקה, איזון ורענון מנטלי. הקליניקה החדשה ממוקמת בשדרה המרכזית של מודיעין-מכבים-רעות ומשלבת בין שקט פנימי לנוף אורבני חי.', '0777299394', 'https://headspa.co.il/', 'דם המכבים 39, מודיעין מכבים רעות, ישראל', 31.9039428, 35.0067707, 'https://www.modiin4u.co.il/wp-content/uploads/2025/07/Artboard-1_3-copy.jpg', 'https://www.modiin4u.co.il/wp-content/uploads/2025/07/WhatsApp-Image-2025-07-15-at-11.50.14-scaled.jpeg', 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
