insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('1a503f26-bb7a-58aa-9937-b12203687923', 'ג׳ויה מודיעין מע״ר', 'joya-modiin-2', 'מסעדה איטלקית', 'מסעדת "ג''ויה" במודיעין מציעה חוויה איטלקית אותנטית וכשרה למהדרין, המשלבת אווירה נעימה, עיצוב מודרני ותפריט עשיר. המסעדה, השוכנת בלב העיר, מביאה אליכם את ניחוחות וטעמי המטבח האיטלקי הקלאסי עם טוויסט עדכני, תוך שימוש בחומרי גלם טריים ואיכותיים. התפריט של "ג''ויה" מגוון וכולל מנות פסטה טריות המיוצרות במקום, פיצות הנאפות בטאבון אבן, דגים, מנות ניוקי, לזניה, מגוון סלטים טריים, ומנות פתיחה אהובות כמו פוקאצ''ה וקרפצ''יו. כל המנות מוכנות במקום ומעוצבות בקפידה, מה שמעניק לסועדים חוויה ויזואלית וקולינרית כאחד. בין מנות הדגל ניתן למצוא את ה"רביולי ארטישוק וריקוטה" ברוטב חמאה ומרווה, ה"ניוקי 4 גבינות", ושלל הפיצות המיוחדות. לצד האוכל המעולה, "ג''ויה" מציעה גם בר משקאות עשיר עם יינות, בירות וקוקטיילים, וקינוחים איטלקיים מסורתיים ומשובחים. המסעדה מתאימה למגוון אירועים – מארוחות משפחתיות ובילויים עם חברים, ועד לאירועים פרטיים ועיסקיים. עם שירות אדיב ומקצועי, "ג''ויה" שמה לה למטרה להעניק לכל אורח חוויה בלתי נשכחת של טעמים, ריחות ואווירה איטלקית משובחת.', '077-938-6304', 'joya.co.il', 'מתתיהו הכהן 1, מודיעין מכבים רעות, ישראל', 31.9057259, 35.0053257, 'https://www.modiin4u.co.il/wp-content/uploads/2025/07/logo-1.png', null, 0, 'none', true, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('c0b1947b-88d9-5b2a-a39b-002ba61f5a33', 'פינוקים מודיעין', 'pinukim-modiim', 'החנות שמרכזת לכם כל מה שצריך לכל חגיגה!', 'פינוקים - החנות שמרכזת לכם כל מה שצריך לכל חגיגה!🥳 חומרי גלם לאפייה, גלידות וארטיקים, אביזרים לימי הולדת ואירועים, שתייה, ממתקים ועוד בסיטונאות וללקוחות פרטיים', '+97253-377-9987', 'Www.Pinookim.co.il', 'ישפרו סנטר, שדרות המלאכות 14, מודיעין מכבים רעות, ישראל', 31.8903123, 34.9641177, 'https://www.modiin4u.co.il/wp-content/uploads/2025/07/פינוקים-לוגו-סופי-נבחר-scaled.png', 'https://www.modiin4u.co.il/wp-content/uploads/2025/07/WhatsApp-Image-2025-07-29-at-19.04.12.jpeg', 5.0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
