insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('7d05980e-604f-5cff-8712-6791a795cd8e', 'לוצ''נה מודיעין', 'luciana-modiin-2', 'מסעדה איטלקית', 'לוצ''נה מודיעין – הטעם האיטלקי המוכר, עכשיו קרוב לבית! השם לוצ''נה מצלצל לכם מוכר? זה ממש לא במקרה! ייתכן שזכיתם לבקר בעבר אצל האחות הגדולה בירושלים, שהפכה עם השנים לאחת המסעדות האיטלקיות האהובות והמוערכות בעיר הקודש. לאור ההצלחה המסחררת והביקוש הגובר, החלטנו להתרחב – ואנחנו נרגשים להביא את הטעם, האווירה והאיכות הייחודית של לוצ''נה גם לתושבי מודיעין והסביבה. נעים להכיר: לוצ''נה מודיעין – מסעדה איטלקית, חלבית וכשרה למהדרין (בהשגחת בד"ץ בית יוסף). אצלנו תמצאו את אותם מתכונים מדויקים, חומרי גלם טריים ואיכותיים, ואת הניחוח האותנטי של איטליה, יחד עם השירות החם והמשפחתי שהפך לסימן ההיכר שלנו. אנחנו מזמינים אתכם לבוא, לטעום וליהנות מחוויה קולינרית איטלקית אמיתית, ממש כאן במודיעין.', '08-690-1111', 'https://lucianamodiin.co.il/', 'שדרות המלאכות 1, מודיעין מכבים רעות, ישראל', 31.8890791, 34.9662839, 'https://www.modiin4u.co.il/wp-content/uploads/2025/07/310976353_1067952967176740_106738543990070353_n.jpg', null, 0, 'rabbanut', true, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('795af3bd-f41b-54f7-baea-549643686681', 'אחלה פלאפל מודיעין', 'hachla-falafel-modiin', 'פלפאל אותנטי ישראלי', 'ברוכים הבאים ל"אחלה פלאפל מודיעין" – חוויה ישראלית אמיתית! אם יש משהו שאנחנו יודעים שכולם אוהבים, זה אוכל רחוב ישראלי קלאסי וטעים, ובמיוחד את השילוש הקדוש: פלאפל, סביח וחומוס. ב"אחלה פלאפל מודיעין", המסעדה הכשרה למהדרין שלנו (בהשגחת הרבנות מודיעין), אנחנו גאים להכין את שלושתם ברמה הגבוהה ביותר של איכות וטעם – בדיוק כמו שאתם אוהבים. בכל מנת פלאפל או סביח אצלנו, תוכלו להרכיב לעצמכם את השילוב המושלם מתוך מגוון עשיר של סלטים וממרחים טריים וטעימים. אנחנו מקפידים על כל הפרטים, כולל המרכיבים המסורתיים שיש בכל סביח אסלי. ולצד כל מנה משגעת, תקבלו גם את הצ''יפס המצוין שלנו – פריך וזהוב בדיוק כמו שצריך. בקיצור, אתם מוזמנים אלינו למרכז מרל"ז – לשבת וליהנות ממנות טעימות במיוחד, ומשירות אדיב, מחויך ומפנק. ומה אם אתם לא יכולים להגיע אלינו? אין בעיה! המנות הטעימות שלנו יכולות להגיע ישירות אליכם! פשוט היכנסו אל תפריט המשלוחים האינטראקטיבי שלנו ובחרו בלחיצת כפתור כל מה שתרצו להזמין – בקלות ובמהירות. אנחנו מאפשרים גם איסוף עצמי וגם משלוחים עד הבית או המשרד. צוות "אחלה פלאפל מודיעין" כבר מחכה להזמנה שלכם ולהכין לכם מנות שיהיה תענוג לזלול!', '086657222', 'https://hachlafalafel01.co.il/', 'עמק דותן 96, מודיעין מכבים רעות, ישראל', 31.8999208, 35.0137882, 'https://www.modiin4u.co.il/wp-content/uploads/2025/08/logo-14.jpg.webp', 'https://www.modiin4u.co.il/wp-content/uploads/2025/08/image-xs-16.jpg', 5.0, 'rabbanut', true, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
