insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('0e7ef78b-3288-53be-9086-3800f68fa661', 'האחוזה', 'האחוזה-מודיעין', null, 'האחוזה מודיעין מזמינה אתכם לחגוג במקום שכולו סטייל, יוקרה וקסם. גן ירוק ומעוצב, אולם חדיש עם טכנולוגיה מתקדמת, תפריט קולינרי מוקפד ושירות אישי ומקצועי – כל אלו יוצרים חוויית אירוע שלא שוכחים. מושלם לחתונות, בר/בת מצווה, כנסים ואירועים עסקיים, במיקום מרכזי עם חניה בשפע.', '08-664-0440', 'https://www.haahuzah.co.il/', 'שדרות התעשיות 14, מודיעין מכבים רעות, ישראל', 31.8852406, 34.9606193, null, null, 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
