insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('8dc67631-31b0-5a5e-a3a1-2aee8de5a2b3', 'פרלין בייקרי מודיעין', 'פרלין-בייקרי-מודיעין', 'בית קפה מאפייה', 'פרלין קייק & קו (Pearlin Cake & Co.) בייקרי ובית קפה בניחוח צרפתי, בלב מודיעין ברוכים הבאים ל"פרלין קייק & קו" – המקום בו הקסם הצרפתי פוגש את האווירה הביתית של מודיעין. אנו לא רק קונדיטוריה, אלא בית של ממש, שנפתח מתוך אהבה עמוקה לאפייה איכותית, חומרי גלם טריים ודגש על טעמים שיזכירו לכם חופשה בפריז. החוויה הקולינרית שלנו בכל בוקר, אנו פותחים את הדלתות עם ריח משכר של מאפים טריים הנאפים במקום, ומזמינים אתכם להתחיל את היום נכון. אצלנו תמצאו: מאפים טריים: קרואסונים פריכים, דנישים מפתים ומאפים מלוחים ומתוקים. קפה משובח: תערובות פולים איכותיות לקפה בדיוק כמו שאתם אוהבים. בייקרי מלא: לחמים מיוחדים, עוגות ועוגיות, קינוחים אישיים וקינוחי ראווה. מנות בית קפה: כריכים טריים וסלטים עשירים לארוחת צהריים או בוקר. הייחודיות שלנו אנו מקפידים על פרטים קטנים וגדולים כאחד: כשרות: חלבי בהשגחת רבנות מודיעין. שעות פתיחה נוחות: אנחנו פה בשבילכם במהלך כל השבוע, כולל סופי שבוע (מוצ"ש). מיקום מרכזי: ממוקמים בלב המע"ר, עם חנייה נוחה חינם בשעה הראשונה (בבניין יעקבי). בואו ליהנות מחוויה של טעם, שירות וחיוך. אנו מחכים לכם עם הקפה והמאפה המושלמים! לפרטים נוספים, הזמנות וכל שאלה, צרו קשר: 📞 [הכנסו טלפון 072-3726428] 📍 דם המכבים 28, בניין יעקבי - קומת הרחוב, מרכז העיר.', null, null, 'דם המכבים 28, מודיעין מכבים רעות, ישראל', 31.9061025, 35.005832, null, null, 0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('d46a531b-4ff0-5d12-b2f7-da93451ffb5b', 'גבריאל פטיסרי מודיעין', 'gabrielpatisseriemodiin', 'בית קפה', 'גבריאל פטיסרי היא מאפייה חדשה המציעה מגוון רחב של פינוקים ומשקאות טעימים. מלחמים ומאפים טריים ועד משקאות מרעננים וסלטים, גבריאל פטיסרי מציעה את כל מה שאתם צריכים לארוחה או סתם חטיף טעים. בין אם אתם במצב רוח לכריך או קינוח מתוק, גבריאל פטיסרי דואגת לכם. עם דגש על מרכיבים איכותיים ואהבה לאפייה, גבריאל פטיסרי מחויבת לספק ללקוחותיה טעמים ושירות יוצאי דופן. אז בואו לבקר בגבריאל פטיסרי עוד היום וגלו את המאפייה האהובה עליכם החדשה. קונדיטוריית גבריאל כחלק מההתפתחות הטבעית של המאפייה שלנו, המייצרת מגוון מוצרי לחם מדי יום ומשווקת אותם ברחבי הארץ, החלטנו לפתוח חנות קטנה בשיטת "מהיצרן לצרכן". כך אנו חוסכים בעמלות תיווך, מגישים ללקוח הפרטי לחם טרי היישר מתנור המפעל, ומבטיחים חווית קנייה נעימה ואיכות ללא פשרות - בדיוק כמו שאנחנו אוהבים לאפות.', '050-852-2294', 'https://www.gabrielpatisserie.com/', 'דם המכבים 39, מודיעין מכבים רעות, ישראל', 31.9039428, 35.0067707, 'https://www.modiin4u.co.il/wp-content/uploads/2025/11/WhatsApp-Image-2025-11-25-at-11.34.46.jpeg', 'https://www.modiin4u.co.il/wp-content/uploads/2025/11/WhatsApp-Image-2025-11-25-at-11.34.45.jpeg', 0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
