insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('19e7d400-da66-5fc0-a7b1-65cd66e3aa4c', 'פעמי פלוס מודיעין | חנות חד פעמי במודיעין', 'peami-plus', 'פתרונות חד פעמי לבית ולעסק במחירים הכי זולים שיש !', 'אירועים • חגים • מסעדות • קייטרינג • סיטונאות• ימי הולדת• ועוד מלאי גדול | מחירים משתלמים | שירות אישי 📍 חיים וייצמן 9 מודיעין שלחו הודעה ונעזור לכם לבחור 👋', '088558404', null, 'מודיעין', null, null, 'https://www.modiin4u.co.il/wp-content/uploads/2026/02/IMG_6203.png', 'https://www.modiin4u.co.il/wp-content/uploads/2026/02/WhatsApp-Image-2026-02-18-at-13.23.51-2.jpeg', 0, 'none', true, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
