insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('8dd5073b-c794-529d-a3d1-8cf0dc001285', 'טליה בלונס | Talia balloons', 'טליה-בלונס-talia-balloons', 'טליה בלונס היא חנות קונספט לאירועים במודיעין המציעה פתרון מלא תחת קורת גג אחת.', 'טליה בלונס היא חנות קונספט לאירועים במודיעין המציעה פתרון מלא תחת קורת גג אחת. בלונים מיוחדים מעוצבים, קירות צילום בהתאמה אישית, מארזים לכל חג ואירוע, מתוקים, מוצרי סובלימציה להדפסה אישית, מיתוג מלא לימי הולדת ואירועים (שקיות חטיפים, בועות סבון, באנרים, קופסאות, מטבעות שוקולד ועוד), לצד מגוון חד פעמי בצבעים וחד פעמי ממותג. הכל עם דגש על איכות, סטייל וירידה לפרטים הקטנים.', '0547904661', 'taliaballoons.co.il', 'פיקוס 8, מודיעין מכבים רעות, ישראל', 31.9012285, 35.0086568, 'https://www.modiin4u.co.il/wp-content/uploads/2026/03/WhatsApp-Image-2026-03-03-at-09.53.36.jpeg', 'https://www.modiin4u.co.il/wp-content/uploads/2026/03/WhatsApp-Image-2026-03-03-at-11.40.00.jpeg', 0, 'none', true, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('b6b2c827-3e79-55e1-8f59-ed9f4d1d3046', 'ג''אפן ג''אפן מודיעין | JAPAN-JAPAN', 'japan-japan-modiin', 'ווק וסושי | מסעדה אסיאתית', 'Japan Japan מסעדה אסייתית המשלבת חוויית אירוח מוקפדת, אווירה ייחודית ותפריט עשיר בהשראת מטבחי המזרח. אצלנו תיהנו מחלל מעוצב ונעים המתאים לבילוי זוגי, מפגש חברים, ארוחה משפחתית או ערב מיוחד. אנו מאמינים ששירות מצוין הוא חלק בלתי נפרד מחוויית האירוח, ולכן צוות המסעדה מעניק יחס אישי, מקצועי ואדיב לכל אורח, מהכניסה ועד סיום הארוחה. במרכז החוויה נמצא בר רחב ומרשים, המציע מגוון עשיר של יינות איכותיים, קוקטיילים מוקפדים ומשקאות אלכוהול מובחרים, עם דגש על חומרי גלם איכותיים, מקצועיות וסטנדרט גבוה של הגשה. התפריט שלנו כולל מבחר רחב של סושי טרי ומוקפד, לצד מנות מהמטבחים השונים של המזרח – החל ממנות ווק עשירות בטעמים, דרך מנות בהשראה תאילנדית, יפנית, סינית, ועד מנות ייחודיות המשלבות מסורת וחדשנות. אנחנו מזמינים אתכם ליהנות מחוויה קולינרית מלאה, המשלבת אוכל מצוין, משקאות איכותיים, שירות מקצועי ואווירה שעושה חשק להישאר עוד קצת. 🍣🍸', '*3304', 'https://www.japan-japan.co.il/', 'שדרות המלאכות 21, מודיעין מכבים רעות', 31.8895424, 34.9614205, 'https://www.modiin4u.co.il/wp-content/uploads/2026/05/צילום-מסך-2026-06-15-ב-18.17.32.png', 'https://www.modiin4u.co.il/wp-content/uploads/2025/01/K-A-R-E-L-A-262-scaled.jpg', 0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
