insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('1727d0cb-2203-5752-9e99-1751fe9b4e22', 'פיצה מוצ׳ה מודיעין', 'mucha-modiin', 'פיצרייה', 'מוצ’ה נולדה מתוך אהבה גדולה לאירוח ולחומרי גלם איכותיים. בהשראת המטבח האיטלקי ועם הטוויסט הישראלי שלנו, פיתחנו תפריט טעים במיוחד, המבוסס על פיצות רומאיות, פסטות בעבודת יד וסלטים טריים. במוצ׳ה יש הכל, בשפע, ובמגוון אפשרויות – וכל האפשרויות טובות', null, 'https://mucha.co.il/', 'קניון עזריאלי, מודיעין', 31.8998602, 35.0082658, 'https://www.modiin4u.co.il/wp-content/uploads/2026/03/logo-mucha.svg', null, 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
