insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('65da973a-739b-576c-bd6c-fc9ffa54cc58', 'בוהמיו בוטיק', 'בוהמיו-בוטיק', 'בוטיק אופנה לנשים', 'שמי שרית דניאל אמא לשלושה , נשואה לאורן , גרה במושב מסילת ציון ( תושבת מודיעין לשעבר). לפני כמעט 4 שנים הגשמתי חלום ושיניתי קריירה באמצע החיים. למדתי סטיילינג בשנקר והתחלתי לייבא בגדי נשים, קיבלתי בסטודיו אישי צמוד לביתי ולפני כחצי שנה פתחתי את בוהמיו בוטיק כאן במודיעין באיילה 360 בכניסה לישפרו סנטר. בבוטיק שלי תמצאו בגדי ייבוא ייחודיים לצד מותגים ישראלים בסגנון קז׳ואל שיק, שילובים של פריטי בייסיק לצד פיסים בדגש על לבוש נינוח, מסוגנן ונשי. כגננת ומדריכת הורים בהכשרתי , הקשר שלי עם הלקוחות כנה ואמיתי ולא רק מוסיפה לכן עוד פריט לארון וזו הסיבה שנשים מגיעות אלינו גם מרחוק. יש פה צוות מקצועי וסובלני שמחכה לכן. אז אם עוד לא הכרנו זה הזמן. מזמינה אתכן לבקר. שדרות המלאכות 21 א׳-ה׳ -10:00-19:30 יום ו׳ - 09:00-14:00', '0502299111', null, 'שדרות המלאכות 21, מודיעין מכבים רעות', 31.8895424, 34.9614205, 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/צילום-מסך-2026-06-10-ב-17.25.07.png', 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/WhatsApp-Image-2026-06-10-at-17.22.52.jpeg', 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('business', '65da973a-739b-576c-bd6c-fc9ffa54cc58', 'f1581e74-1b86-5edd-8d81-44ea2aabfcb5') on conflict do nothing;
insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('bf99dbdc-6b1f-5b15-87ef-1fa36e21ff75', 'סטודיו גלאור כהן - מודיעין', 'סטודיו-גלאור-כהן-מעצבת-שמלות-כלה-במודי', 'שמלות כלה ושמלות ערב למכירה /בתפירה אישית', 'היי לכולן 🤍 אני גלאור, מעצבת שמלות כלה וערב, והסטודיו שלי נמצא במודיעין חצי שנה ✨ כל הזמן הזה אני פוגשת כאן נשים מדהימות, והרגשתי שהגיע הזמן גם להציג את עצמי כמו שצריך ולהכיר קצת יותר מקרוב 🫶🏻 הסטודיו שלי הוא מקום אינטימי וחם, כזה שכל אחת יכולה להרגיש בו בנוח, להתרגש, למדוד, לחלום ולמצוא את השמלה שמרגישה הכי “היא” 🤍 אני מעצבת שמלות כלה ושמלות ערב — מקולקציה קיימת עם התאמות אישיות וגם בתפירה אישית, עם המון תשומת לב לפרטים הקטנים, לגזרה, לנוחות ולהרגשה שלכן בתוך השמלה ✨ אם יש לכן אירוע, חתונה, או אפילו רק רצון להתרשם ולהכיר — אתן לגמרי מוזמנות לשלוח לי הודעה באהבה 💌 ומקווה להכיר כאן עוד נשים מהממות מהעיר', '0536290887', 'https://galorcohen.com/', 'הקדר 12, מודיעין מכבים רעות', 31.8890329, 34.9637505, 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/צילום-מסך-2026-06-10-ב-17.32.17.png', 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/WhatsApp-Image-2026-06-10-at-17.28.11.jpeg', 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
