insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('10a9ced2-315d-5385-ace5-6cc66fb4a2d0', 'LA ELIYA - שמלות ערב ונשף במודיעין', 'la-eliya', 'שמלות ערב ונשף במודיעין', 'נשות מודיעין היקרות 💜 יש דברים שמחכים להם זמן רב מדי. שמלה שגורמת לך להרגיש את עצמך - יפה, בטוחה, מיוחדת. אנחנו LA ELIYA 👗 - וסוף סוף הגענו הביתה, למודיעין. פתחנו חנות שמלות ערב עם מגוון שפשוט לא תמצאו בכל מקום - שמלות ייחודיות, במידות שונות, בסטייל שמדבר אל הנשיות שבכן. כי כל אחת מכן ראויה להרגיש מדהימה 🌹', '053-3607333', null, 'השדרה המרכזית 15, מודיעין מכבים רעות, ישראל', 31.922265, 34.9687967, 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/צילום-מסך-2026-06-10-ב-17.42.49.png', 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/WhatsApp-Image-2026-06-10-at-17.35.11-4.jpeg', 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
