insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('ff29e267-e9ce-5617-81cd-1a239fdbe101', 'גן שורש מודיעין', 'gan-shoresh-modiin', 'גן ילדים במודיעין', 'המיוחד בגן: ברוח הגישה המונטסורית . גננת מונטסורית. מרפאה בעיסוק. רישיון משרד החינוך. מבנה גן. תפריט לפי תזונאית ילדים. אוכל ביתי טרי מבושל יומיום. ותק של 18 שנים חוג תאטרון. העשרה: יוגה, אנגלית, מוזיקה.', '054-8080033', null, 'נץ החלב 1, מודיעין מכבים רעות, ישראל', 31.9045159, 35.0129229, 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/371840148_775551591239463_1668642314243626875_n.jpg', null, 0, 'rabbanut', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();
