insert into businesses (id, name, slug, short_description, full_description, phone, website, address, latitude, longitude, logo_url, cover_url, rating, kosher_level, has_delivery, open_on_shabbat, status, is_verified) values ('f6410384-aa4a-5d4d-bf9e-afc14f6339c4', 'קיי לוק - מנעולן במודיעין', 'k-lockssmith', 'מנעולן חירום 24/7 פריצת דלתות והחלפת מנעולים', 'כשנתקעים מחוץ לבית או לרכב באמצע היום – או גרוע מכך, באמצע הלילה – אתם צריכים יותר מסתם "מנעולן". אתם צריכים מישהו שתוכלו לסמוך עליו, שיגיע מהר ויפתור את הבעיה בלי לנצל את רגעי הלחץ שלכם. ב-K-Locksmith, אנחנו מבינים שהביטחון שלכם הוא מעל הכל. עם ניסיון עשיר בתחום המנעולנות והפריצה, אנחנו מספקים שירות מקצועי, מהיר ואיכותי לתושבי מודיעין, מכבים, רעות והסביבה. אנחנו לא רק פותחים דלתות – אנחנו מקפידים על סטנדרטים גבוהים של אמינות, עבודה נקייה ושמירה על הרכוש שלכם. למה לבחור בנו? זמינות גבוהה: אנחנו כאן בשבילכם כשהתקלות קורות. מקצועיות ללא פשרות: מומחיות בפריצת דלתות, החלפת מנעולים, תיקון צילינדרים ושירותי רכב – במינימום נזק ומקסימום יעילות. שירות מקומי: כעסק שחי ונושם את מודיעין, חשוב לנו לשמור על שם טוב ועל שירות אישי לכל לקוח ולקוחה. שקיפות: אנחנו מאמינים בהוגנות. אצלנו תקבלו הצעת מחיר ברורה ושירות ללא הפתעות. הצטרפו למאות תושבים במודיעין שכבר בחרו ב-K-Locksmith כדי לישון בשקט בלילה ולדעת שכשמשהו קורה, יש לכם על מי לסמוך. צריכים עזרה דחופה או ייעוץ לפני התקנה? אנחנו במרחק שיחת טלפון.', '055-959-5950', 'https://k-lockssmith.com/', '332, מודיעין מכבים רעות, ישראל', 31.890267, 35.010397, 'https://www.modiin4u.co.il/wp-content/uploads/2026/07/k-locks-logo-ApujD_Iy.jpeg', null, 0, 'none', false, false, 'active', true) on conflict (id) do update set name = excluded.name, phone = excluded.phone, address = excluded.address, latitude = excluded.latitude, longitude = excluded.longitude, cover_url = excluded.cover_url, rating = excluded.rating, updated_at = now();

insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('3656458e-84a8-5529-a964-246b81ed1f54', 'פסטיבל צלילי הסתיו חוזר', 'פסטיבל-צלילי-הסתיו-חוזר', '<!-- wp:paragraph -->
<p>לאחר הפסקה של שנה, פסטיבל "צלילי סתיו", המהווה את אחד מהאירועים הבולטים והאהובים בעיר, חוזר, עם תכנית עשירה של מופעי מוזיקה במגוון סגנונות , שייכנסו לליבם<br>של הילדים והמבוגרים כאחד.<br>הפסטיבל שמתקיים כבר משנת 2000 ייפתח ביום חמישי 14.11, במופע מחווה חגיגי של<br>הזמרת הישראלית הנצחית אילנית, שמציינת 60 שניות פעילות על הבמה. המופע של<br>אילנית, נכס צאן ברזל במוסיקה הישראלית, ששיריה מהווים מרכיב מרכזי בפסקול חיינו,<br>יכלול שירים מכל התקופות מ"אי שם" ועד היום, ויעורר בוודאי נוסטלגיה חמימה אצל כולם.<br>למחרת, שישי 15.11, יתקיימו מספר מופעים מעניינים, ג''ימבו ג''יי יארח את נונו בהיכל<br>התרבות, עוזי נבון ישיר בקולו המיוחד שירי מחווה לאריק איינשטיין באולם עינן ובערב,<br>יופיעו הרכב "העבריות" במחווה לשיריו של נתן אלתרמן באודיטוריום מו"ר. במקביל, תופיע<br>בהיכל התרבות, הזמרת והיוצרת מרינה מקסימילאן.<br>ביום שבת 16.11, יתקיים בהיכל התרבות מופע מיוחד של להקת רוקוויל לילדים "שירים<br>מצויירים" במהלכו תבצע הלהקה שירים מתוך סרטי ילדים מוזיקליים בעברית ובאנגלית .<br>היוצר, אבי גרייניק ומשפחתו יופיעו במופע "החיים ממשיכים לנגן" עם פיוטים וזמירות<br>יהודיות לצד שירים ישראליים, באולם עינן.<br>לאורך ימי הפסטיבל, יתקיימו, כמו תמיד מופעים רבים ללא תשלום ובהם המופע של יהודה<br>קיסר, יאיר דלאל בהרכב בדואי ישראלי ,הרוקברי סיסטר ,אנסמבל גלעד אפרת בהפקת<br>מקור של מוסיקה קלאסית ידועה "ארבע העונות" בווריאציות ישראליות עם שירים על עונות<br>השנה באמפי עמק האלה אנסמבל גליל ,להקת מלוקס עם אייל תלמודי ועוד הרכבים<br>ממוזיקה קלאסית מוסיקה מדיתטיבית , ג''אז, רוק, אתני, מוסיקת עולם, חזנות<br>ועוד….המופעים יתקיימו, בפארקים ובאולמות בכל רחבי העיר החל ממרכז העיר, בכניסה<br>לרעות, פארק ענבה ופארקים רבים אחרים בעיר.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/צלילי-סתיו-צילום-חורחה-נובומינסקי4-scaled.jpg', 'published', '2024-11-08 12:53:21') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '3656458e-84a8-5529-a964-246b81ed1f54', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('588ba87c-0ddf-52ed-9cbe-8c472ccd1160', 'טורניר הסטריטבול המסורתי', 'טורניר-הסטריטבול-המסורתי', '<!-- wp:paragraph -->
<p>ביום חמישי 31.10.2024 התקיים טורניר הסטריטבול המסורתי לזכרו של סמ"ר עוז צמח<br>ז"ל שנפל במלחמת לבנון השנייה. בטורניר השתתפו כ- 300 שחקנים בכ-70 קבוצות,<br>בקשת רחבה של גילים החל מגיל קט-סל ועד לנוער ומבוגרים. השנה לראשונה המשחקים<br>שוחקו בשעות הערב ומגרשי הספורטק רחבי הידיים דבר שהעניק חווית משתתף נעימה<br>למשתתפים ולקהל המעודדים</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>חיים צמח אביו של עוז ז"ל, בירך את הנוכחים והודה לכולם על השתתפותם בטורניר<br>הממלא את המשפחה בתקווה ואור ונותן להם הרבה כוח להתמודד עם השכול המלווה<br>אותם. סגן ראש העיר ומחזיק תיק הספורט אלעד שמעונוביץ וממלא מקום ראש העיר,<br>שלמה פסי בירכו את הנוכחים והדגישו את המצוינות כערך לאורו פעל ולחם עוז. עוד נשא<br>דברים מח"ט 188 לשעבר (החטיבה בה שירת עוז צמח), אל"מ (במיל'') משה שטרית, אשר<br>דיבר על גבורתו של עוז ועל המורשת שהותיר לדורות הלוחמים ואיחל למשתתפים בעיקר<br>הצעירים, לחתור למצוינות והישגים תוך כבוד לזולת.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>סמ"ר עוז צמח ז"ל ,נולד ב 27.10.1985 ונהרג ביום 12.8.2006. עוז התגייס לצה”ל לחיל<br>השריון ב- 28 מרץ 2004 . כמפקד טנק בפלוגה ג’ בגדוד 53 חטיבה 188, זכה להערכה<br>רבה מקרב מפקדיו ופקודיו. עוז נפל בקרב גבורה בסוף מלחמת לבנון השנייה ב - י”ח אב<br>תשס”ו, 12 אוגוסט 2006<br>בבינת ג’בל בשעה שפיקד על צוות טנק, חילץ והציל טנק אחר שנפגע ושמפקדו נפצע וחדל<br>לתפקד. עוז שקיבל פקודה לסגת, החליט להישאר בשטח תחת אש תופת של טילים ולבצע<br>קרב חילוץ והצלה. הטנק הפגוע חולץ וצוותו הגיע למקום מבטחים. עוז וצוותו נהרגו.<br>על קרב זה קיבל עוז ז"ל ציון לשבח מאלוף פיקוד צפון - "על שהראה אחריות, דוגמה<br>אישית, רוח לחימה, מקצועיות, יוזמה, רעות ואומץ לב עד כדי חירוף הנפש”.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/IMG-20241103-WA0056.jpg', 'published', '2024-11-08 12:55:58') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '588ba87c-0ddf-52ed-9cbe-8c472ccd1160', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('9898b093-fd6c-5352-888c-b48b4ae09ab6', 'פרויקט בוחרים בשישי בית ספר עמית', 'פרויקט-בוחרים-בשישי-בית-ספר-עמית', '<!-- wp:paragraph -->
<p>בית הספר היסודי "עמית", השיק לאחרונה פרויקט חדש – "בוחרים בשישי". יום לימודים<br>המתקיים אחת לחודש בבית הספר, בו התלמידים יכולים לבחור מבין קורסים שונים לגוף<br>ולנפש, אשר מועברים על ידי הצוות החינוכי.<br>ביום שישי האחרון 8.11, התקיימו לראשונה קורסים במסגרת הפרויקט, עם מגוון של<br>שיעורים רב גיליים בתחומי הספורט, האמנות, הבישול, רכיבה על אופניים, קומיקס, ריקוד<br>ואפילו לימוד שפה פורטוגזית.<br>שיעורי הגוף והנפש בימי שישי מהווים חלק מיישום הזהות הבית ספרית שייחודה ביחס אישי<br>ובחירה של התלמידים. שיעורי הגוף והנפש חיוניים להתפתחותם של הילדים ותורמים מאוד<br>לחיזוקם ברמה החברתית והרגשית ולשיפור יכולות קוגנטיביות.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/IMG-20241106-WA0031.jpg', 'published', '2024-11-10 11:32:17') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '9898b093-fd6c-5352-888c-b48b4ae09ab6', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('52615923-2b4c-5d5f-83ce-0b9827acd3c7', 'מרחב חדש בבית ספר אלונים‎', 'מרחב-חדש-בבית-ספר-אלונים', '<!-- wp:paragraph -->
<p>בית הספר היסודי "אלונים" התחדש לאחרונה במרחב למידה דינמיקלאס, אשר ישמש את<br>כל שכבות הגיל בבית הספר. המרחב, המשלב את כל החושים, מיועד ללמידה<br>אינטראקטיבית חווייתית, באמצעות מקרן רצפתי, אשר מקרין תכנים מגוונים בהתאמה<br>לשכבות הגיל בכל תחומי הדעת, זאת תוך כדי שלוב של תנועה ודינאמיות. בתוך המרחב<br>החדש לומדים התלמידים שיתוף פעולה תוך כדי תחרות, חוויית הצלחה וגילוי כישורים<br>אישיים וקבוצתיים מעבר ללמידה הרגילה בכיתות.<br> המרחב נמצא בתוך מרחב כללי בבית הספר הנקרא אתנחתא, שבו מקדישים זמן<br>ללמידה אחרת וחדשנית, ובו גם מתקיימים שיעורי מוסיקה, מפגשים חברתיים,<br>מפגשי יום הולדת עם מנהלת בית הספר ומפגשי אוורור עם יועצת בית הספר.<br> מרחב זה מצטרף למרחבים חווייתיים נוספים בבית הספר. למשל, מרחב מדע<br>וטכנולוגיה המשלב למידה חדשנית עם בינה מלאכותית, למידת תכנות לרובוטיקה<br>ועוד. בנוסף, ישנו מרחב לאימוני ג''ודו ובו ציוד ומזרנים וכן מרחב לתיאטרון ודרמה.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/IMG-20241110-WA0000.jpg', 'published', '2024-11-10 11:33:14') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '52615923-2b4c-5d5f-83ce-0b9827acd3c7', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('6ae875b9-70d9-511a-bd1c-1ea27c29e1c5', 'הסתיימו עבודות ברמזורים ובגלאים לוויסות התנועה ‎', 'הסתיימו-עבודות-ברמזורים-ובגלאים-לווי', '<!-- wp:paragraph -->
<p>מחלקת החשמל באגף התשתיות בעירייה סיימה בימים אלה, עבודות לשטיפת הרמזורים<br>בכלל הצמתים ברחבי העיר. העבודות בוצעו כחלק מההיערכות לעונת החורף וכחלק<br>מהתחזוקה השנתית, להגברת הבטיחות בדרכים.<br>בנוסף, בוצעו לאחרונה עבודות לחידוש חריצת הגלאים, המשמשים לוויסות התנועה בעיקר<br>בשעות העומס, על ידי חיישנים הפועלים בהתאם למצב התנועה בכבישים. חידוש חריצת<br>הגלאים נעשה בצומת לב העיר ליד קניון עזריאלי, בשני צמתים במרכז עינב וכן, בצמתים<br>ברחובות צוקית ושלדג בשכונת הציפורים.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/IMG-20241107-WA0002.jpg', 'published', '2024-11-10 11:34:01') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '6ae875b9-70d9-511a-bd1c-1ea27c29e1c5', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('86867fa7-04ac-522e-afd2-469dd47386c1', 'הסתיים קורס להכשרת פעילי נחל ענבה‎', 'הסתיים-קורס-להכשרת-פעילי-נחל-ענבה', '<!-- wp:paragraph -->
<p>18 תושבים ותושבות נמרצים ומלאי מוטיבציה סיימו לאחרונה קורס ייחודי לפעילי "נחל<br>ענבה", בהובלת מחלקת איכות ותכנון סביבה בעירייה והרשות לניקוז ונחלים ירקון.<br>במסגרת הקורס, עברו התושבים הכשרה מעשית שמטרתה לחשוף את אתר הטבע נחל<br>ענבה וערכו הרב בקהילה ובסביבה, כך שייקחו חלק פעיל בתהליכי השמירה על הנחל,<br>ולהפוך הלכה למעשה לשומרי הנחל.<br>לאורך הקורס למדו התושבים על הנחל והקשרו לנחל הירקון, ההיסטוריה המקומית ותהליכי<br>השיקום של הנחל והמסדרון האקולוגי החשוב שהוא יוצר כריאה ירוקה. עוד עסקה ההכשרה<br>בהיכרות עם המגוון הביולוגי – החי והצומח, בשיקום נחלים בישראל וחשיבות הניטור בשטח<br>שיקבל חיזוק גם בפלטפורמה דיגיטלית לעידוד ניטור על ידי תושבי העיר. לצד כל אלו, נגעה<br>ההכשרה בחיבור המשמעותי של הקהילה לנחל תוך מתן דוגמאות והשראה לפעילויות<br>קהילתיות בנחלים בארץ ובעולם ועתה עם סיום ההכשרה, מתכוננת קבוצת הפעילים גם כן<br>לאירוע קהילתי בנחל, עליו יפורסמו פרטים בהמשך.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/IMG-20241105-WA0002.jpg', 'published', '2024-11-10 11:34:59') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '86867fa7-04ac-522e-afd2-469dd47386c1', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('22a9887f-919a-5fce-8ec0-193bca5f22c2', 'מוקירים את מאבטחי מוסדות החינוך‎', 'מוקירים-את-מאבטחי-מוסדות-החינוך', '<!-- wp:paragraph -->
<p>המסורת נמשכת. מינהל הביטחון והחירום בעירייה, בוחר מידי חודש לבחור מאבטח בית<br>ספר או מאבטח גני ילדים, למצטיין חודשי אותו מוקירים ומעריכים, דבר אשר מקבל חשיבות<br>גדולה עוד יותר, בתקופה המורכבת של המלחמה.<br>המאבטחים מקבלים תעודת הוקרה על הצטיינותם, בזכות תפקודם המקצועי, הקפדה<br>ושמירה על נהלי הביטחון, נוכחות קבועה בעבודה ויחסי אנוש מצויינים. בחלוקת תעודות<br>ההוקרה משתתף גם הצוות החינוכי בבית הספר אשר מעניק שי צנוע למאבטח.<br>בתמונה - המאבטח אליהו ניסים, אשר מאבטח מידי יום את תלמידי וצוותי בית הספר עירוני<br>ה'' ע"ש יצחק נבון במסירות רבה, וקיבל תעודת הוקרה על הצטיינותו בחודש אוקטובר.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/IMG-20241107-WA0013.jpg', 'published', '2024-11-10 11:35:49') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '22a9887f-919a-5fce-8ec0-193bca5f22c2', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('f843a47a-08e8-502f-89a3-e59515828c7d', 'כיתת הוותיקים חזרה לספסל הלימודים‎', 'כיתת-הוותיקים-חזרה-לספסל-הלימודים', '<!-- wp:paragraph -->
<p>השבוע חזרו לספסל הלימודים בבית הספר 35 אזרחים ואזרחיות ותיקות, תושבי העיר.<br>מרגש היה לראות את ההתלהבות והניצוץ בעיניים, כשפתחו את מחברות הלימוד ונהנו ביחד<br>בכיתה בבית הספר עירוני ה'' ע"ש יצחק נבון, משיעורים מרתקים של אנגלית, אזרחות,<br>ספרות ונשים בתנ"ך.<br>כיתת הוותיקים היאה פרויקט מצליח מאוד הקיים מספר שנים בעיר, בהובלת המשרד לשוויון<br>חברתי ואגף הקהילה בעירייה. במסגרת הפרויקט, לומדים האזרחים הוותיקים מבוקר עד<br>צהריים מקצועות שונים לידע והעשרה, וזוכים גם למפגשים חברתיים והרבה משמעות בגיל<br>המבוגר.<br>בעקבות הביקוש הרב, נבחנת אפשרות לפתיחת כיתות ותיקים נוספות בהמשך.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/IMG-20241103-WA0034.jpg', 'published', '2024-11-10 11:36:32') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
