insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('7b39ee6c-d206-5ced-805a-2b85317a82cf', 'חנות פרחים חדשה בפורום הציפורים מודיעין', 'flower-store', '<!-- wp:paragraph -->
<p>הכירו את <a href="https://www.modiin4u.co.il/business/%d7%90%d7%9c%d7%95%d7%a1%d7%98%d7%a8%d7%9e%d7%a8%d7%99%d7%94-%d7%97%d7%a0%d7%95%d7%aa-%d7%a4%d7%a8%d7%97%d7%99%d7%9d-%d7%91%d7%9e%d7%95%d7%93%d7%99%d7%a2%d7%99%d7%9f/">אלוסטרמריה</a> חנות פרחים חדשה במרכז פורום הציפורים, החנות מציעה מגוון רחב של זרים ופרחים ובנוסף שירות של עיצוב אירועים על ידי פרחים. בראיון קצר מול בעל החנות נודע למודיעין בשבילך שהוא מתכוון לשנות את ההסתכלות על זרי פרחים תוך הבנה של השוק המקומי ומתן שירות בלבל אחר!</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>החנות מעוצבת ברמה גבוהה, ממש בקומה השניה של המרכז, בחוץ מסודרים מגוון זרים ועציצים, בקרוב גם אתר משלוחים יעלה לאוויר שדרכו תושבי העיר יוכלו להזמין וכמובן החנות פועלת גם בוולט לשירות משלוחים.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>אז בקיצור אם אתם מעוניינים בזר פרחים מרהיב זה המקום שלכם!</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p><a href="https://www.modiin4u.co.il/business/%d7%90%d7%9c%d7%95%d7%a1%d7%98%d7%a8%d7%9e%d7%a8%d7%99%d7%94-%d7%97%d7%a0%d7%95%d7%aa-%d7%a4%d7%a8%d7%97%d7%99%d7%9d-%d7%91%d7%9e%d7%95%d7%93%d7%99%d7%a2%d7%99%d7%9f/">אלוסטרמריה</a> , פורום הציפורים.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/10/אלוסטרמיה-2.jpg', 'published', '2024-11-11 10:30:15') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
