insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('61203c0c-d77a-565a-9612-966f31fda323', '25 שנה על הרצפה: סיפור ההצלחה של אומן הפרקטים והקרמיקה במודיעין', 'oman-haparketim-modiin', '<!-- wp:paragraph -->
<p>אין תושב בעיר שלא מכיר את יגאל מלכה ״<a href="https://www.modiin4u.co.il/business/%d7%90%d7%95%d7%9e%d7%9f-%d7%94%d7%a4%d7%a8%d7%a7%d7%98%d7%99%d7%9d/">אומן הפרקטים והקרמיקה</a>״, שנים שהחנות הייתה במודיעין סנטר ולאחרונה עברה למקום חדש באילה 360 בישפרו סנטר, מקום גדול ומושקע מעין אולם תצוגה.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>בשיחתנו עם יגאל הוא שיתף שהמקום החדש נולד מתוך רצון לתת ללקוחות חווית רכישה אחרת תוך ייעוץ אמיתי והבנת הצרכים.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>בחנות החדשה תוכלו לראות מבחר ענק של פרקטים, קרמיקות ומקלחונים, ביחד עם הצוות המנצח שיתן לכם את השירות המושלם עד שתצאו מרוצים!</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>יגאל זוכר בדיוק את הפעם הראשונה שבה הניח אריח קרמיקה. זה היה בבית של חברים, וההתרגשות הייתה גדולה. מאז, הוא לא הפסיק להתאהב בעולם הריצוף. היום, אחרי 25 שנה בענף, יגאל הפך לאחד האמנים המובילים בתחום במודיעין. בחנות שלו, ''אומן הפרקטים והקרמיקה'', תוכלו למצוא מגוון עצום של פרקטים, קרמיקה, וכלים סניטריים, וכל זאת בליווי ייעוץ מקצועי ואישי.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>הייחודיות של המקום באה לידי ביטוי בהרבה מובנים, כמובן איכות החומרים והסחורה החדשנית, אבל מעבר לכך האהבה של יגאל וצוותו (המשפחה שלו) לעבודה שלהם, הם קמים כל בוקר עם חיוך ומוטיבציה לתת את המוצר הכי טוב ללקוח עם שירות שהאמת? אין לו מתחרים...</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>אז אם אתם לפני שיפוץ, או סתם רוצים לחדש ״<a href="https://www.modiin4u.co.il/business/%d7%90%d7%95%d7%9e%d7%9f-%d7%94%d7%a4%d7%a8%d7%a7%d7%98%d7%99%d7%9d/">אומן הפרקטים והקרמיקה</a>״ זה המקום המדויק עבורכם.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/WhatsApp-Image-2024-11-20-at-16.26.34.jpeg', 'published', '2024-11-23 17:05:40') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
