insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('c0aff40e-4b66-5abf-9832-59c577ccd61e', 'שלוחה של מכללת אורנים תפעל בעיר', 'muni-update-3', '<!-- wp:paragraph -->
<p>שיתוף פעולה חדש נולד, במסגרת מודל "עיר לומדת" לפיתוח למידה והשכלה בקרב תושבי<br>העיר, במסגרתו מכללת אורנים תפעל בעיר ותציע לימודי תעודה מבוקשים, באמצעות<br>שלוחה של מרכז ק.מ.ה השייך למכללה.<br>מרכז ק.מ.ה – קהילה, מנהיגות, השראה, פועל לפיתוח הכשרות מקצועיות, הנחייה של<br>תהליכים קהילתיים, ליווי לבעלי תפקידים בארגונים, במערכות חינוך וברשויות מקומיות. צוות<br>מרצים מנוסה של המכללה, המוכרת כמובילה בתחומה, ילווה וינחה את הקורסים, ויאפשר<br>למידה איכותית ומעשית קרוב לבית.<br>התכניות שיוצעו יהיו מגוונות ויכללו: הכשרת יועצים ארגוניים – תכנית מעשית המספקת<br>כלים לליווי ארגונים ומנהלים. הוראה מותאמת בעברית ובחשבון – לימודי תעודה להקניית<br>ידע ומיומנויות לתלמידים עם קשיי למידה. פוטותרפיה – כלי טיפולי ייחודי המשלב צילום עם<br>חקירה רגשית. הדרכת הורים והכשרה לאבחון דידקטי בעברית, להבנת צרכי תלמידים עם<br>ליקויי למידה ודרכי עבודה מותאמות.<br>ההרשמה נפתחה בימים אלה. לפרטים: https://bit.ly/4e0G2i9</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/המרכז-הרב-תחומי-2.jpg', 'published', '2024-11-24 12:11:36') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
