insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('7c88f332-8446-59b1-86cc-dfa3fd4e3a3a', 'יריד עסקים לעולים חדשים‎', 'muni-update-4', '<!-- wp:paragraph -->
<p>ביום שלישי 19.11 התקיים יריד עסקים של העולים החדשים, בהובלת מחלקת הקליטה<br>בעירייה.<br>היריד נערך בקניון עזריאלי ובו הציגו כ-18 עסקים של עולים חדשים, אשר עלו לארץ בשנים<br>האחרונות. בכך, ניתנה לראשונה הזדמנות לעולים להציג ולשווק לתושבי העיר את העסקים<br>הקטנים בהם הם פועלים, ולחבק את העולים בפרגון ואווירה קהילתית.<br>בין מגוון העסקים שהציגו ביריד ניתן היה למצוא דוכן של שזיקת פרחים, קונדיטוריה, שיעורי<br>פסנתר, שירות שליחים, תכשיטים, טיפולי NLP ועוד.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/IMG-20241120-WA0013.jpg', 'published', '2024-11-24 12:13:30') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
