insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('05db5099-6923-5909-84a9-b0bfdb740948', 'סגירת אתר בנייה שהעסיק והלין שב”חים במודיעין', 'modiin-news', '<!-- wp:paragraph -->
<p>סגירת אתר בנייה שהעסיק והלין שב”חים במודיעין</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>בפעילות מבצעית משולבת של שוטרי תחנת מודיעין ולוחמי יס”מ שפלה, אותרו לפנות בוקר באתר בנייה באזור הפארק הטכנולוגי במודיעין 14 תושבי איו”ש ללא אישורי שהייה, אשר לנו והועסקו במקום באופן בלתי חוקי.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>בסיום חקירתם נעצרו 9 חשודים בעלי עבר פלילי או ביטחוני, ונגד כולם הוגשו כתבי אישום בליווי בקשה למעצר עד תום ההליכים.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>בהמשך לפעילות, חתם היום מפקד מחוז מרכז, ניצב יאיר חצרוני, על צו סגירה מנהלי ל-30 יום לאתר הבנייה, בעקבות העסקתם והלנתם של שב”חים תוך פגיעה בביטחון הציבור ובתחושת הביטחון האישית של תושבי האזור.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>משטרת מודיעין תמשיך לפעול בנחישות ובאפס סובלנות לאיתור וטיפול במקרים מסוג זה, במטרה לשמור על הסדר הציבורי ולחזק את תחושת הביטחון של התושבים.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/11/WhatsApp-Image-2024-11-27-at-20.18.18.jpeg', 'published', '2024-11-28 10:14:29') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '05db5099-6923-5909-84a9-b0bfdb740948', 'e9ccc079-df4e-519b-9885-8b4eba35de06') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('b65d2687-f6b6-5237-abf7-73a63950eb4f', 'טקס הנצחה מרגש לזכרו של סמר צור אברהם‎', 'modiin-muni-update-8', '<!-- wp:paragraph -->
<p><strong>ביום רביעי 4.12.24 יתקיים טקס הנצחה לזכרו של סמ"ר אריאל צים</strong></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>ביום שישי 29.12.24, התקיים טקס הנצחה מרגש לקריאת מעלה על שמו של סמ"ר צור אברהם, בהשתתפות בני משפחתו, חברים ותושבים, שבאו לחלוק כבוד לזכרו.&nbsp;</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>המעלה ממוקם ברחוב נחל זוהר 49, ליד בית ילדותו של צור ז"ל, אשר גדל והתחנך בעיר, בבית הספר משואת נריה ובהמשך בישיבה התיכונית לפיד. צור ז"ל, נחלם בגבורה בשבעה באוקטובר, כשהבין את גודל השעה ויצא לקרב בכרם שלום ובמוצב סופה בעוטף עזה. במשך חודשים שירת צור, שהיה הקשר של מפקד הצוות בסיירת הנח"ל, בתוך רצועת עזה. בתחילת חודש יוני 2024, נפצע פציעה קלה בפניו ושחרר הביתה להחלמה. כשחזר לפעילות ב-16.6.24, נפל במהלך פעילות של כוח סיירת הנח"ל שיצא לאתר פירי מנהרות של חמאס. יהי זכרו ברוך.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>ביום רביעי 4.12.24, יתקיים טקס הנצחה לקריאת משעול לזכרו של סמ"ר אריאל צים ז"ל, בן העיר, לוחם בגדוד 931 בחטיבת הנח"ל, אשר נפל בקרב על הגנת המולדת, ברצועת עזה בחודש מאי האחרון.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>הטקס יתקיים ברחוב נחל עיון 13 בשעה 14:00, בהשתתפות בני המשפחה וחברים, ותושבי העיר מוזמנים לבוא ולחלוק כבוד לזכרו. במקרה של גשם, יש להתעדכן מול מוקד 106.&nbsp;</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>טקסי ההנצחה במשעולים מתקיימים במסגרת מיזם הנצחה עירוני ייחודי ומרגש, לזכר בנותיה ובניה של העיר מודיעין מכבים רעות. מיקומיהם של המשעולים נקבעים בהתאם לדרישות המשפחות השכולות, לרוב ליד הבית בו גרו הנופלות והנופלים.&nbsp;</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>בכל משעול, אבן זיכרון בה משולבים משפטי הנצחה על כל נופל ונופלת וגם קוד QR אותו ניתן לסרוק, המוביל לאתר הזיכרון המספר את סיפור המורשת של הנופל והנופלת.&nbsp;</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/12/IMG_20241129_115057_469.jpg', 'published', '2024-12-01 12:07:13') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', 'b65d2687-f6b6-5237-abf7-73a63950eb4f', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('16b05c4d-ce4a-505b-9842-15c6c10c48d4', 'ביקור מרתק של מפקד הכוח שחיסל את סינוואר בעירוני ד‎', 'modiin-muni-update-9', '<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>לאחרונה זכו תלמידי בית הספר אורט עירוני ד'' להיפגש עם מפקד הכוח שחיסל את רב<br>המרצחים, יחיא סינוואר.<br>תלמידי שכבות ט'' ו-י"א נפגשו עם המפקד והלוחם, סא"ל רן כנען, מג"ד 450, הגדוד מבית<br>הספר למפקדי חי"ר של צה"ל. סא"ל רן, שהוא אח של מורה בבית הספר, בן כנען, סיפר<br>לתלמידים על דרכו הפיקודית, על אירועי השבעה באוקטובר ועל חיסולו של סינוואר. בשבעה<br>באוקטובר, לחם עם חייליו בגבורה נגד המחבלים שהגיעו לקיבוץ כיסופים, הציל אנשים רבים<br>ונפצע קשה כשניסה לעזור לחייל שלו שנפצע. כבר בבית החולים הבטיח, שיחלים במהרה<br>ויחזור להילחם ולהכריע את חמאס. ואכן, שנה לאחר מכן, הוא פיקד על הכוח שחיסל את<br>ראש החמאס, יחיא סינוואר.<br>סא"ל רן הוסיף וסיפר: "זוהי סגירת מעגל עבורי כמפקד ולמסגרת שלי שסגרה שבת בשבעה<br>באוקטובר. הוקפצנו לעוטף עזה, נלחמנו בכיסופים ובכרם שלום, איבדנו שבעה לוחמים<br>במהלך הקרבות. אני אישית נפצעתי באותם קרבות והיום, שנה אחרי, הצלחנו לסגור מעגל<br>ולחסל את יחיא סינוואר רב המרצחים, בתל סולטאן."<br>סא"ל רן ריתק את התלמידים וצוות בית הספר בסרטונים ותיאור האירועים ממקור ראשון,<br>ובמיוחד בתיאור המרגש של גבורת הלוחמים. אישיותו אמיצת הלב ואופן קבלת ההחלטות<br>תחת אש, עוררו השראה וגאווה גדולה.<br>צופית חדד, מנהלת בית הספר: "אין ספק שהתלמידים זכו להכיר מפקד ואדם שמהווה<br>דוגמה אישית לערכים, רעות, דבקות במטרה ומסירות למען העם והמדינה. נשאר רק לשאת<br>תפילה, שהוא וכל חיילי וחיילות צה"ל וכוחות הביטחון, יחזרו לשלום למשפחותיהם וכל<br>החטופים והחטופות יחזרו לבתיהם".</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/12/IMG-20241127-WA0002.jpg', 'published', '2024-12-01 12:09:54') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
