insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('ebed9741-eec9-524c-9614-42a0d08e7082', 'אמית בנים אירח את תלמידי צפת בצל המלחמה‎', 'modiin-muni-update-10', '<!-- wp:paragraph -->
<p>לאחרונה אירח בית הספר אמי"ת בנים את תלמידי כיתות ח'' מישיבת אמי"ת צפת, ליום<br>הפוגה של חיבור וגיבוש והרבה רוגע ושמחה, מהימים המורכבים של המלחמה.<br>תלמידי אמי"ת קיבלו את פניהם של התלמידים מצפת, וליוו אותם בשירים ובריקודים<br>בכניסתם לבית הספר. ועד הורי השכבה, פתחו לכבודם שולחן עם כיבוד מפנק, ורב העיר,<br>הרב יעקב צ''יקוטאי ומנהלת אגף העל יסודי במינהל החינוך, ד"ר יעל אראלי, בירכו את<br>התלמידים.<br>לאחר מכן, התקיים מפגש היכרות, והתלמידים יצאו למשחק ניווט עירוני חווייתי, תוך שיתוף<br>פעולה ביחד והיכרות עם העיר.<br>בסיום האירוע, עמדו התלמידים והצוות ביחד במעגל גדול ונשאו תפילה לשחרור החטופות<br>והחטופים וניצחון במלחמה.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/12/IMG-20241201-WA0002.jpg', 'published', '2024-12-01 12:11:37') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', 'ebed9741-eec9-524c-9614-42a0d08e7082', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('2b1f3703-bee3-5dad-8592-2fb40eca02d4', 'מפקד מחוז מרכז -ניצב יאיר חצרוני חתם היום על צו סגירה למשך 15 ימים למסעדה במודיעין', 'modiin-news-2', '<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>מפקד מחוז מרכז -ניצב יאיר חצרוני חתם היום על צו סגירה למשך 15 ימים למסעדה במודיעין שהעסיקה 2 שוהים בלתי חוקיים מאיו"ש</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>במסגרת האכיפה המשטרתית הממוקדת כנגד עבירות העסקה, הסעה והלנת שוהים בלתי חוקיים, העלולים להוות פלטפורמה לפח"ע, מבצעים השוטרים בקרות קפדניות בבתי עסק בגזרת המחוז ובצירים.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>בתוך כך, שוטרי תחנת מודיעין חשפו במסעדה בעיר 2 שוהים בלתי חוקיים שעבדו במקום, ללא אישורי שהיה בארץ, זאת לצד כתב אישום שהגישה נגדם היום יחידת התביעות של מחוז מרכז ופתיחת הליך פלילי נגד המעסיק.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>כאמור, מפקד מחוז מרכז-ניצב יאיר חצרוני חתם היום על צו סגירה למקום למשך 15 ימים</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>משטרת ישראל תגלה אפס סובלנות כנגד מי שמפר את החוק ועלול לפגוע בביטחון האזרחים, בפרט בעתות מלחמה, ונמשיך לפעול בנחישות כנגד כלל המעורבים בדגש על עבירות הסעה, הלנה והעסקת שוהים בלתי חוקיים.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>מצ״ב תמונת הדבקת הצו, קרדיט דוברות המשטרה.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/12/WhatsApp-Image-2024-12-01-at-20.10.37.jpeg', 'published', '2024-12-01 18:29:30') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '2b1f3703-bee3-5dad-8592-2fb40eca02d4', 'e9ccc079-df4e-519b-9885-8b4eba35de06') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('61a6c673-833d-5bc1-8af3-749b9af4837a', 'עירוני מודיעין עושה היסטוריה! ניצחון דרמטי על הפועל ראשל"צ והעפלה לסיבוב ח׳ בגביע המדינה', 'sport-modiin', '<!-- wp:heading -->
<h2 class="wp-block-heading"><strong>עירוני מודיעין עושה היסטוריה! בהובלת המאמן ארז בנודיס ניצחון דרמטי על הפועל ראשל"צ והעפלה לסיבוב השמיני בגביע המדינה</strong></h2>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>במשחק דרמטי שנערך אתמול, גברה עירוני מודיעין על הפועל ראשון לציון מהליגה הלאומית והעפילה לסיבוב השמיני בגביע המדינה בכדורגל. השער היחיד במשחק נכבש בדקה ה-30 מבעיטה חופשית מדויקת של אלי אלבז.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>"הגענו למשחק מול קבוצה מהליגה הלאומית וידענו מראש שאנחנו באים לעשות את המקסימום בכדי לעבור לשלב הבא", אמר מאמן הקבוצה, ארז. "השחקנים הציגו משחק נפלא והוכיחו שהם מסוגלים להתמודד עם כל קבוצה".</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>הניצחון ההיסטורי מעלה את עירוני מודיעין לסיבוב השמיני, שם תתמודד מול בני סכנין מליגת העל. "העפלנו לסיבוב ח׳ נגד בני סכנין בליגת העל. זהו הישג אדיר עבור המועדון והעיר כולה", אמר מאמן הקבוצה בהתרגשות. "נבוא ונעשה את המקסימום שלנו על מנת להעפיל לשלב הבא".</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>הניצחון על ראשון לציון הוא הישג משמעותי עבור עירוני מודיעין, ומעניק לקבוצה רוח גבית לקראת המשך העונה. הקבוצה והעיר כולה חוגגות את ההישג ההיסטורי ומצפות בהתרגשות למשחק הקרוב מול בני סכנין.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>בתמונה ארז בנודיס המאמן וביתו.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/12/WhatsApp-Image-2024-12-02-at-19.12.53.jpeg', 'published', '2024-12-02 17:03:57') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
