insert into entity_categories (entity_type, entity_id, category_id) values ('article', '61a6c673-833d-5bc1-8af3-749b9af4837a', 'e9ccc079-df4e-519b-9885-8b4eba35de06') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('255cc43b-dda7-58dd-9900-7a04861796a2', 'חודש המודעות להתמודדות עם סמים ואלכוהול בקרב בני נוער‎', 'modiin-muni-update-11', '<!-- wp:paragraph -->
<p>במהלך חודש דצמבר יתקיימו פעילויות, הרצאות והצגות לבני הנוער, במסגרת חודש המודעות להתמודדות עם הסמים והאלכוהול.<br>החודש הינו פרי שיתוף פעולה של המחלקה לביטחון קהילתי במינהל חינוך ומשרד החינוך,<br>אשר מובילים, במיוחד בתקופת המלחמה, מערך שלם של הסברה והדרכה בגובה העיניים,<br>על התנהגויות בסיכון.<br>בתקופות מאתגרות כמו המלחמה, ידוע כי גובר הצורך בשימוש בחומרים מסוכנים, על מנת<br>לטשטש את הקושי, החרדה, הבדידות וחוסר האונים, בקרב בני הנוער, ועל כן ישנו זרקור<br>מיוחד בנושא, במיוחד בשנה זאת. כאשר כל שכבת גיל מכיתה ז'' עד י"ב, מקבלת תכנים<br>שונים מותאמים, החל מבריונות ברשת, שתיית אלכוהול וסיפורי העצמה.<br>בנוסף, יתקיים גם לאורך חודש דצמבר שיתוף פעולה עם משטרת מודיעין, ביחד עם מדריכי<br>מוגנות. השוטרים והמדריכים יצרו שיח בכיתות על בריונות ברשת, הכרת החוק הפלילי ועוד.</p>
<!-- /wp:paragraph -->', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/12/IMG-20241202-WA0000.jpg', 'published', '2024-12-03 10:15:19') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
