insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('2e5e161a-5342-5db0-a53f-0ff880ecefda', 'העולים החדשים סיירו בנאות קדומים‎', 'modiin-muni-update-16', 'כ-50 עולים חדשים יצאו לאחרונה, לטיול בשמורה הלאומית, נאות קדומים. העולים,
הלומדים באולפן, יצאו לטיול במסגרת סיורים והדרכות שעורכת מחלקת הקליטה בעירייה,
להיכרות עם הארץ וחיזוק תחושת השייכות והחיבור לישראל.
במהלך הטיול קיבלו העולים הדרכות בשפות השונות, למדו על צמחים קדומים מתקופת
התנ״ך, בעלי חיים וראו שחזור של מתקנים חקלאיים קדומים ונופים מרהיבים. מסע קדום
חווייתי ומעשיר, באווירה ארצישראלית שלבטח לא ישכחו.', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/12/תמונה-קבוצתיתי-נאות-קדומים.jpg', 'published', '2024-12-08 10:07:19') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
