insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('601a6626-0d50-5648-b35f-bc7266975b31', 'שבוע הקוד בבית הספר אבני החושן', 'modiin-muni-update-27', 'בבית הספר אבני החושן ציינו לאחרונה את שבוע "שעת הקוד העולמי". יוזמה בינלאומית,
המאפשרת לילדים ולילדות להתנסות בכתיבת קוד, ללמוד על עולם ההייטק והחדשנות
בדרך חווייתית ומהנה.
במסגרת השבוע המיוחד, הגיעו לבית הספר הורים מתנדבים להעביר שיעורים בכיתות
ובמהלכם חשפו ההורים בפני התלמידים את עיסוקיהם בתחום התכנות וההייטק. בנוסף,
התנסו התלמידים בפעילויות המשלבות בינה מלאכותית.
שבוע זה הוא חלק מלמידה קבועה בבית הספר שמטרה למידה טכנולוגית ושפת מחשב
ופיתוח מיומנויות מודרניות של חשיבה יצירתית ועצמאית. הפרויקט נעשה בהובלת המורה
ורכזת המחשוב אביטל חוברה בשיתוף עם הנהגת ההורים הבית ספרית.', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/12/IMG-20241222-WA0020.jpg', 'published', '2024-12-23 14:41:05') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
