insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('c63b7c41-2b85-50de-9dd4-92e7d09eb5cd', 'הפחתת עומסי תנועה בכניסה למרכז עינב', 'modiin-muni-update-31', 'ביום רביעי 18.12.24, הסתיימו עבודות העירייה להפחתת עומסי תנועת כלי הרכב
