insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('f5e0bfa2-0304-5bec-9b4d-d4d4365c5693', 'תושבים רבים בילו במתחם הפודטקראס ‎', 'modiin-muni-update-33', 'ביום חמישי האחרון, נהנו מאות תושבי העיר ומבקרים, מהמיזם העירוני החדש – "המתחם",
אשר מרכז במתחם אחד, פודטראקס הפועלים בעיר, יחד עם מופע מוזיקה ואורות
מקושטים.
המתחם נפתח ברחבת הירידים ליד קניון עזריאלי ובו התפרשו ארבעה פודטראקס אהובים,
שהציעו קולינריה איכותית ומגוונת. קופסת אוכל שמתמחה בהכנת מנות בשר מיוחדות, ET
חוויה מכוכב אחר המוכרת יין וגבינות איכותיים, ללה בירקפה המוכרת בזכות בירות בוטיק
מצוינות ובורקס בולגרי, ו-דה קאסה שהציעה לעוברים ולשבים צ''ורוס מיוחדים, פיצות
ומאפים.
את כל אלו ליוו הרכב המוזיקה הג''זלן, אורות מקושטים ופינות ישיבה נעימות.
המיזם יצא לדרך בהובלת חברת אופק ואגף התרבות בעירייה, כשהוא שואב השראתו
ממתחמי אוכל פופולריים ברחבי העולם. בימים אלה בוחנת חברת אופק את האפשרות
להרחיב את קיומם של אירועים נוספים מסוג זה. פרטים בקרוב.', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/12/IMG-20241226-WA0067.jpg', 'published', '2024-12-29 12:17:12') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
