insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('57371c85-243b-5bde-bb72-e6b8a80a9147', 'מירוץ הלפיד', 'modiin-muni-update-36', 'לקראת חג החנוכה, קיים בית הספר מו"ר את "מירוץ הלפיד". זו השנה השנייה שבה
מתקיים המירוץ, אשר מהווה אירוע ספורטיבי – ערכי שמחבר בין עבר להווה ומוקדש
להעצמת הערכים של גבורה וחוסן קהילתי.
האירוע נפתח בטקס מרגש בקברות המכבים, שם הודלק הלפיד המסמל את רוח החג.
בטקס ניתן דגש על חיבור למסורת ולשחקי המכבייה הצפויים להיפתח בקיץ הקרוב. עם
סיום הטקס, הוזנק מירוץ הלפיד בהשתתפות 160 תלמידים ותלמידות משכבות ז''; עד י"ב,
בליווי מורים ונציגי קהילת בית הספר. מסלול המירוץ עבר ברחבי העיר, חצה את המיצג
המרגש למען החטופים ברחוב יאיר פרג והסתיים ברחבת בית הספר, שם התקבלו
התלמידים בתשואות על ידי כלל תלמידי בית הספר.
בסיום המירוץ, נערך טקס "אור במו"ר", שבו הדליק בית הספר נרות להוקרתם של גיבורי
התקופה - משפחות משרתי המילואים, משפחות החטופים, אנשי הרפואה והחינוך,
החקלאים והאמנים, המהווים השראה לכולם. הטקס לווה בהופעה של ההרכב המוזיקלי של
בית הספר.', null, 'https://www.modiin4u.co.il/wp-content/uploads/2024/12/IMG-20241226-WA0042.jpg', 'published', '2024-12-29 12:33:19') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
