insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('3e1bbcdf-1440-55c5-a0a1-aa46746a6cf1', 'מודיעין משקיעה בעסקים המקומיים: השקת מרכז חדש', 'modiin-news-5', '<p data-sourcepos="20:1-20:157">באירוע חגיגי שנערך במודיעין, השיק המרכז הרב-תחומי את המרכז החדש לצמיחה עסקית. האירוע, שהתקיים  היום ב(09/01/25), משך אליו עשרות בעלי עסקים מקומיים, יזמים ואנשי עסקים.</p>
<p data-sourcepos="22:1-22:205">את המרכז החדש מובילה כרמית תא שמע, מחזיקת תיק העסקים בעירייה, בשיתוף מנהלת האגף להשכלה, למידה ויזמות. האירוע התקיים בחסות ראש העיר, חיים ביבס, אשר הדגיש את חשיבות התמיכה בעסקים המקומיים וקידום היזמות בעיר.</p>
<p data-sourcepos="24:1-24:180">המרכז החדש נועד לספק לעסקים המקומיים מגוון שירותים, כגון: ייעוץ עסקי, סדנאות הכשרה, אירועי נטוורקינג ועוד. המטרה היא לסייע לעסקים לגדול ולהצליח, ולהפוך את מודיעין למרכז עסקי משגשג.</p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/01/Modiin.png', 'published', '2025-01-09 13:25:44') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
