insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('6ee603c3-42d2-5e71-97c0-70e45d748f74', 'אולפנת אורות מודיעין זכתה במקום השלישי בגמר טורניר בין תחומי‎', 'm', 'אולפנת אורות מודיעין זכתה במקום השלישי
בטורניר בין תחומי של רשת האולפנות בארץ
נבחרת הלמידה של אולפנת בני עקיבא אורות מודיעין, זכתה בשבוע האחרון במקום
