insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('444d4cb8-f2b8-5f96-a599-f280e031522e', 'מאות חיילים בכנס משתחררים 2025‎', 'modiin-muni-4', 'מאות חיילים וחיילות בכנס משתחררים

ביום ראשון, 9.2.25, התקיים זו הפעם השנייה, כנס משתחררים בהובלת מחלקת הצעירים
בעירייה ומנהלת שער לעתיד. בכנס השתתפו כ-600 חיילים וחיילות תושבי העיר, אשר
עתידים להשתחרר משירות סדיר בין החודשים ינואר ליוני 2025.
במהלך הכנס, עברו החיילים מספר סדנאות והרצאות בנושאי זכויות חיילים משוחררים
והתנדבות והסברה תוך כדי הטיול הגדול. בנוסף, התקיים יריד תעסוקה מכוון לתעסוקת
חיילים משוחררים בהשתתפות מיטב החברות במשק עם דגש על מקומות עבודה בסביבת
העיר. בין המציגים אשר הציעו משרות רלוונטיות: משטרה, שב&amp;quot;ס, שב&amp;quot;כ, משמר הכנסת,
אלביט, אסם, אלקטרה, משרד רה&amp;quot;מ, משרד החוץ, לשכת התעסוקה, אגד, נמל התעופה בן
גוריון ועוד.
בעקבות המצב הביטחוני, בשנה שעברה בוטלו כנסי המשתחררים הארציים ומרכז הצעירים
&amp;quot;יודה&amp;quot; הרים את הכפפה וקיים כנס משתחררים עירוני. האירוע הוכתר בהצלחה והועתק
לרשויות רבות ברחבי הארץ. כשהמטרה היא לחבר את המשוחררים הטריים לעיר, למרכז
הצעירים, וכמובן לתת להם מענה אישי והכנה מעשית לקראת השחרור.', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/02/IMG-20250216-WA0114.jpg', 'published', '2025-02-16 13:09:21') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
