insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('9c20967b-d10d-5116-b1b6-c1b45d6b357f', 'דיסקונט מודיעין: אנחנו לא רק בנק, אנחנו חלק מהקהילה', 'modiin-news-37', '<p class="s6"><span class="s4"><span class="bumpedFont15">"</span></span><span class="s4"><span class="bumpedFont15">אחד היתרונות הבולטים של סניף דיסקונט מודיעין הוא </span></span><span class="s4"><span class="bumpedFont15">שחלק גדול</span></span><span class="s4"><span class="bumpedFont15"> מעובדי הסניף הם תושבי העיר. </span></span><span class="s4"><span class="bumpedFont15">הם חיים ונושמים את מודיעין, מבינים את הצרכים </span></span><span class="s4"><span class="bumpedFont15">הייחודיים </span></span><span class="s4"><span class="bumpedFont15">של התושבים ומכירים את האתגרים של הקהילה" מעידה ענבל אדרי, מנהלת סניף דיסקונט מודיעין. "אנחנו לא רק בנק, אנחנו חלק מהקהילה. אנחנו גרים כאן, הילדים שלנו לומדים כאן, ואנחנו רוצים לתרום להצלחת העיר", מוסיף שמעון גז, סגן מנהלת סניף דיסקונט מודיעין.</span></span> <span class="s4"><span class="bumpedFont15">"</span></span><span class="s4"><span class="bumpedFont15">אנו מזמינים את כל מי שמעונין להגיע להתרשם ולהיות חלק מאלפי הלקוחות המרוצים של סניף דיסקונט. בסניף מחלקת בנקאות פרטית, </span></span><span class="s4"><span class="bumpedFont15">מחלקה עסקית, מחלקת משכנתאות, ייעוץ השקעות, ייעוץ פנסיוני ועוד</span></span><span class="s4"><span class="bumpedFont15">"</span></span><span class="s4"><span class="bumpedFont15">. </span></span></p>
<p class="s7"><span class="s4"><span class="bumpedFont15">בשנה החולפת סניף דיסקונט מודיעין לקח חלק בפרויקטים חברתיים שונים בעיר ובמרכזם, חיבור עם תושבי עוטף עזה שנפגעו במלחמה. "העיר שלנו ספגה אבדות קשות במהלך המלחמה </span></span><span class="s4"><span class="bumpedFont15">וביניהם גם </span></span><span class="s4"><span class="bumpedFont15">לקוחות הסניף", אומרת ענבל אדרי, מנהלת הסניף. "רצינו לעשות ככל יכולתנו לעזור למשפחות השכול ולתמוך בהן. </span></span><span class="s4"><span class="bumpedFont15">הפעילויות בשיתוף הקהילה</span></span> <span class="s4"><span class="bumpedFont15">הן </span></span><span class="s4"><span class="bumpedFont15">חלק מהערכים שלנו</span></span><span class="s4"><span class="bumpedFont15">ועובדי הסניף התנדבו בקטיף תאנים בחווה חקלאית בעמק איילון</span></span><span class="s4"><span class="bumpedFont15">", אומר שמעון גז, סגן מנהלת הסניף</span></span><span class="s4"><span class="bumpedFont15">.</span></span><span class="s4"><span class="bumpedFont15"> "אנחנו מאמינים שחשוב לתרום לקהילה ולעזור למי שצריך</span></span><span class="s4"><span class="bumpedFont15">. אנחנו מזמינים את תושבי מודיעין להצטרף למשפחה שלנו וליהנות משירות מקצועי, אישי עם הפנים לקהילה" אומרים ענבל ושמעון.</span></span></p>
<p class="s7"><span class="s4"><span class="bumpedFont15">תושבי מודיעין, אנחנו מזמינים אתכם להצטרף לבנק דיסקונט וליהנות מחבילת הטבות שווה: </span></span><span class="s4"><span class="bumpedFont15">ללקוחות הפרטיים פטור מעמלות עו"ש עיקריות</span></span><span class="s4"><span class="bumpedFont15">ומדמי כרטיס אשראי</span></span><span class="s4"><span class="bumpedFont15"> למשך 10 שנים ולעצמאים במשך 3 שנים, מענק הצטרפות של עד 1,200 ש"ח למעבירי משכורת</span></span> <span class="s4"><span class="bumpedFont15">ותנאים אטרקטיביים נוספים. </span></span></p>
<p class="s8"><span class="s4"><span class="bumpedFont15">לכל שאלה אנו זמינים בניידים האישיים שלנו </span></span></p>
<p class="s9"><span class="s4"><span class="bumpedFont15">ענבל: 050-9877791</span></span></p>
<p class="s9"><span class="s4"><span class="bumpedFont15">שמעון: 054-2533422</span></span></p>
<p class="s10"><span class="s4"><span class="bumpedFont15">
</span></span><span class="s4"><span class="bumpedFont15">*</span></span><span class="s4"><span class="bumpedFont15">המבצע ללקוחות חדשים בלבד, המצטרפים </span></span><span class="s4"><span class="bumpedFont15">עד סוף </span></span><span class="s4"><span class="bumpedFont15">חודש </span></span><span class="s4"><span class="bumpedFont15">אפריל</span></span></p>
<p class="s10"><span class="s4"><span class="bumpedFont15">*</span></span><span class="s4"><span class="bumpedFont15">אי עמידה בפירעון ההלוואה או האשראי עלול לגרור חיוב בריבית פיגורים והליכי הוצאה לפועל .</span></span></p>
<p class="s10"><span class="s4"><span class="bumpedFont15">*האמור אינו מהווה הצעה ו /או התחייבות למתן אשראי וכפוף לשיקול דעת הבנק.</span></span> <span class="s4"><span class="bumpedFont15">                         </span></span><span class="s4"><span class="bumpedFont15">+</span></span><span class="s4"><span class="bumpedFont15">לפרטים מלאים המפורטים באתר הבנק , לחץ כאן: </span></span><a href="https://www.discountbank.co.il/lp/ourstory-digital_account_opening_grant/?utm_source=maindiscountwebsite&amp;utm_medium=cpc&amp;utm_campaign=alo_niud"><span class="s11"><span class="bumpedFont15">https://www.discountbank.co.il/lp/ourstory-digital_account_opening_grant/?utm_source=maindiscountwebsite&amp;utm_medium=cpc&amp;utm_campaign=alo_niud</span></span></a></p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/02/WhatsApp-Image-2025-02-12-at-16.16.22.jpeg', 'published', '2025-03-04 08:55:13') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
