insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('7630239d-55e3-518d-b4b5-e5cb6e3519a0', 'קמפיין עירוני:משפחות עם צרכים מיוחדים קיבלו צמידי פטור מתור ‎', 'modiin-muni-22', 'אגף השירותים החברתיים בעירייה, ציין את יום המשפחה למשפחות עם צרכים מיוחדים,
באירוע קהילתי מהנה. מאות משפחות לילדים עם צרכים מיוחדים הגיעו להקרנה פרטית
בקולנוע הוט סינמה במרכז עינב, ונהנו מסרט ופינוקים של פופקורן ושתייה לזמן איכות
משותף.
במסגרת האירוע, הושק גם הקמפיין העירוני "פטור מתור", במסגרתו חולקו לילדי המשפחות
המיוחדות צמידים סגולים שעליהם הכיתוב – &amp;״ מתור״, במטרה להעלות למודעות את
הנושא החשוב. כך, שמשפחות אשר זכאיות לפטור מתורים בבתי עסק, יוכלו לענוד את
הצמיד, ולהראות לבעל העסק, ללא צורף בהצגת תעודת נכה.
עוד בימים אלה ימשיך הקמפיין להעלאת המודעות בעסקים המקומיים השונים, כאשר בני
נוער מתנדבים יעברו בחנויות ובמרכזים המסחריים ויחלקו מדבקות עליהן הכיתוב – ״עסק
זה מכבד פטור מתור. כולנו תושווים ותושוות״
עמיעד טאוב, סגן רה״ע ומחזיק תיק שירותים חברתיים: ״כולנו תו=שווים מהווה מציאות
עירונית במודיעין במסגרתה אנו מפתחים מענים ומעלים למודעות את הצורך בשוויון 365
ימים בשנה. הפעילות להעלאת המודעות הינה חלק מפעילות שוטפת למגוון התחומים
המייצרים שוויון ובהם פתרונות דיור, הכשרה, תעסוקה, פנאי ונגישות פיזית ומהותית לאלפי
המשפחות עם הצרכים המיוחדים בעיר״.', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/03/IMG-20250303-WA0002.jpg', 'published', '2025-03-06 10:51:35') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
