insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('c59ee735-57ea-567a-8202-e56dc0dd9bda', '"בשבילם זה שדה קרב": העירייה במבצע מיוחד נגד נפצים בפורים!', 'modiin-muni-24', '<p class="query-text-line ng-star-inserted">מחלקת ביטחון קהילתי בעירייה, יוצאת בימים אלה בתכנית עירונית להעלאת המודעות</p>
<p class="query-text-line ng-star-inserted">לסכנות שבשימוש בנפצים, כמו גם פעילות אכיפה נרחבת לקראת חג פורים.</p>
<p class="query-text-line ng-star-inserted">מדריכי המוגנות עורכים עם בני ובנות הנוער שיח על ההשפעה של הנפצים על הלומי קרב</p>
<p class="query-text-line ng-star-inserted">ותושבים בכלל, בעקבות המלחמה. דיון בגובה העיניים, שמטרתו לעורר אמפתיה והזדהות</p>
<p class="query-text-line ng-star-inserted">בקרב בני הנוער.</p>
<p class="query-text-line ng-star-inserted">בנוסף, יוצא השיטור העירוני בפעילות מניעה ומסייר בעסקים המקומיים, על מנת לוודא שאין</p>
<p class="query-text-line ng-star-inserted">מכירה של נפצים מסוכנים. פעילות זו תמשיך באכיפה מוגברת במהלך חג פורים, ותהיה</p>
<p class="query-text-line ng-star-inserted">ממוקדת באזורי הבילוי של בני הנוער, שייקנסו במידה וישתמשו בנפצים.</p>
<p class="query-text-line ng-star-inserted">ברשתות החברתיות, יוצאת העירייה בקמפיין העלאת מודעות לשימוש בנפצים, כשהשנה</p>
