insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('b61785ff-c720-5e99-9b36-bc536fee01ef', 'קמפיין 5 שקלים בעזריאלי מודיעין: בורגראנץ'', TOPTEN ועוד', 'modiin-news-43', '<div id="chat-history" class="chat-history-scroll-container">
<div id="7077fa73fbb214dd" class="conversation-container message-actions-hover-boundary response-optimization tts-removed ng-star-inserted">
<div class="response-container ng-tns-c1216355670-285 response-optimization response-container-with-gpi tts-removed ng-star-inserted response-container-has-multiple-responses">
