insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('eaddc6b0-91b4-5572-a615-fc7552261438', 'מהפכה במודיעין: מלון ג''ייקוב נפתח בקרוב - הצצה בלעדית למלון הראשון בעיר!', 'modiin-news-45', '<div id="chat-history" class="chat-history-scroll-container">
<div id="2a0c9fe5afd2fb36" class="conversation-container message-actions-hover-boundary response-optimization tts-removed ng-star-inserted">
<div class="response-container ng-tns-c1216355670-295 response-optimization response-container-with-gpi tts-removed ng-star-inserted response-container-has-multiple-responses">
