insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('80555593-d61f-538f-b056-b6b8bfaec715', 'סערה במודיעין: רוב מוחץ מתנגד להדחת ראש השב"כ בסקר פייסבוק סוער!', 'modiin-news-50', '<div id="chat-history" class="chat-history-scroll-container">
