insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('d3a41151-2ac9-522a-b71d-a91d6dd3c8d8', '"משעול איתן": מחווה מרגשת לזכרו של סמ"ר איתן קרלסברון ז"ל', 'modiin-news-54', '<div id="chat-history" class="chat-history-scroll-container">
<div id="81bcba5832bbc681" class="conversation-container message-actions-hover-boundary response-optimization tts-removed ng-star-inserted">
<div>
<div class="response-container ng-tns-c3659861101-31 response-optimization response-container-with-gpi tts-removed ng-star-inserted response-container-has-multiple-responses">
