insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('d39c998e-835d-5fe8-8fca-82dd7ac30d46', '"שבוע צה"ל עירוני" סחף אלפי מלש"בים: חוויה מעוררת השראה ומועילה לקראת הגיוס', 'modiin-news-55', '<div id="chat-history" class="chat-history-scroll-container">
<div id="31b5d08c3e5bf23f" class="conversation-container message-actions-hover-boundary response-optimization tts-removed ng-star-inserted">
<div>
<div class="response-container ng-tns-c3659861101-36 response-optimization response-container-with-gpi tts-removed ng-star-inserted response-container-has-multiple-responses">
