insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('7d88b062-82d8-50e1-832f-70e16060b457', 'אמנות בין הברושים: חוויה חדשה ומרתקת מחכה לכם בגבעת הברושים', 'modiin-news-68', '<p data-sourcepos="5:1-5:92">עשרות מיצגים ייחודיים הפזורים במסלול הטיול משלבים אמנות, טבע וכיף לכל המשפחה</p>
<p data-sourcepos="9:1-9:230">גבעת הברושים, אחד מאתרי הטבע היפים והאהובים במודיעין, קיבלה לאחרונה טוויסט אמנותי מרענן. ביום חמישי האחרון (3.4), נחנך בטקס חגיגי וייחודי המיזם העירוני החדש "אמנות בין הברושים", שהפך את מסלול הטיול הקסום לחוויה אמנותית יוצאת דופן.</p>
<p data-sourcepos="11:1-11:332">במסגרת המיזם, פוזרו ברחבי הגבעה לא פחות מ-55 מיצגים ועבודות אמנות מקוריות, פרי יצירתם של אמנים מקומיים, מוסדות תרבות וחינוך בעיר ואמנים מרחבי הארץ. המבקרים בגבעה יוכלו ליהנות ממגוון עשיר של סגנונות וטכניקות אמנותיות, החל מפסלים סביבתיים העשויים מחומרים ממוחזרים, דרך צילומים עוצרי נשימה וציורים ססגוניים, ועד מיצבים פיסוליים מרתקים.</p>
<p data-sourcepos="13:1-13:284">השילוב הייחודי בין האמנות לטבע המקומי מעניק למסלול הטיול נופך חדש ומרתק. המבקרים מוזמנים לצאת למסע גילוי בין העצים והצמחייה, להתקל ביצירות אמנות מפתיעות בכל פינה, ולהתבונן בטבע דרך עיניים אמנותיות. זוהי הזדמנות נהדרת ליהנות מטיול רגלי קליל ומהנה, תוך חשיפה לעולם האמנות העשיר והמגוון.</p>
<p data-sourcepos="15:1-15:314">הבשורה הטובה היא שהמיצגים לא הולכים לשום מקום בקרוב! הם יישארו בגבעה למשך החודשים הקרובים, מה שאומר שבמהלך חופשת הפסח המתקרבת ובחודשי האביב והקיץ, תושבי מודיעין והסביבה יוכלו לנצל את ההזדמנות ולצאת לטיול אמנותי קרוב לבית. אל תשכחו להביא את המצלמות – המיצגים הייחודיים מהווים תפאורה מושלמת לתמונות משפחתיות ואישיות.</p>
<p data-sourcepos="17:1-17:204">כדי להשלים את החוויה, בעירייה דאגו גם לפינוק קולינרי. בסופי השבוע, פועלים בסמוך לגבעה שני פודטראקים מגוונים, המציעים מגוון טעמים וכיבוד קל, כך שתוכלו ליהנות מארוחה קלילה או סתם לנשנש משהו טעים אחרי הטיול.</p>
<p data-sourcepos="19:1-19:315">מאחורי הפרויקט המיוחד עומדת האוצרת המוכשרת עדי אדר, שבחרה בקפידה את המיצגים השונים, תוך שימת דגש על מגוון חומרי גלם והבעות ויזואליות. כדי להעשיר את חוויית הצפייה, ליד כל מיצג הוצב שלט המציין את שם היצירה ואת שם האמן, ובנוסף, מצורף ברקוד לסריקה באמצעות הטלפון החכם, המעניק הסבר מפורט על הרעיון וההשראה מאחורי העבודה.</p>
<p data-sourcepos="21:1-21:243">המיזם "אמנות בין הברושים" הוא חלק מתכנית רחבה יותר לפיתוח התיירות בעיר מודיעין, אשר מקודמת על ידי המרכז הרב תחומי ומוזיאון מורשת החשמונאים. מטרת התכנית היא להנגיש את אתרי הטבע והתרבות בעיר לתושבים ולמבקרים, וליצור חוויות ייחודיות ובלתי נשכחות.</p>
<p data-sourcepos="23:1-23:176">אז אם אתם מחפשים פעילות מהנה, מעוררת השראה וקרובה לבית, אל תפספסו את ההזדמנות לבקר בגבעת הברושים ולהינות מהשילוב המרתק של אמנות וטבע. זוהי חוויה מומלצת לכל הגילאים ולכל המשפחה!</p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/04/IMG-20250401-WA0000.jpg', 'published', '2025-04-07 13:06:16') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '7d88b062-82d8-50e1-832f-70e16060b457', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('c0204f1c-1266-5d35-b214-c5e05613d0d6', '"יותר משחשוב לנו שתלמידים יחוו את העולם, חשוב לנו שהקהילה תחווה אותנו": יום מרגש בבית חינוך צלילים הדגיש את הקשר עם הקהילה והכוח המרפא של האמנות', 'modiin-news-69', '<div id="model-response-message-contentr_2996f1c1b42abf8f" class="markdown markdown-main-panel stronger" dir="rtl">
<p data-sourcepos="5:1-5:324">בית חינוך צלילים, המוסד החינוכי הייחודי במודיעין המיועד לתלמידים על הרצף האוטיסטי, ציין ביום רביעי האחרון (2.4) את יום המודעות העולמי לאוטיזם באירוע מרגש ומשמעותי. בניגוד לציון סטנדרטי, בחר בית הספר להדגיש את תפיסת העולם החינוכית שלו – חיבור הדוק עם הקהילה ככלי מרכזי להעצמת התלמידים ולרכישת מיומנויות חיוניות לחיים עצמאיים.</p>
<p data-sourcepos="7:1-7:306">"יותר משחשוב לנו שתלמידים יחוו את העולם, חשוב לנו שהקהילה תחווה אותנו," הסבירה יעל אבוקסיס, מנהלת בית הספר הנרגשת. "זוהי המשמעות האמיתית של להיות חלק בלתי נפרד מהקהילה המקומית. אנו מאמינים כי דווקא דרך אינטראקציה עם הקהילה ובתוך התנסויות אמיתיות, תלמידינו מצליחים לרכוש את המיומנויות החיוניות כל כך עבורם."</p>
<p data-sourcepos="9:1-9:388">במהלך היום המיוחד, קיימו צוות בית הספר והתלמידים מפגש הוקרה מרגש לשותפים מרכזיים המלווים אותם לאורך השנה. בין השותפים הוזכרו "סופר קייזר", המכולת השכונתית בה מקיימים התלמידים שיעורי חשבון מעשיים, צרכנות נבונה, התמודדות עם עמידה בתור וחיזוק הקשרים עם השכנים. כמו כן, הודו בבית הספר לנציגי ויצ"ו, השותפים בתכנית טרום תעסוקה חשובה שמטרתה להכין את התלמידים לקראת חיים עצמאיים ומשולבים בקהילה.</p>
<p data-sourcepos="11:1-11:299">גולת הכותרת של האירוע הייתה הרצאה מעוררת השראה של מיכל כ"ץ, פיזיותרפיסטית ואם לילד על הרצף האוטיסטי, בנושא "הבעה על הגוף ומה שביניהם". ההרצאה, בה השתתפו הורים, צוות חינוכי ושותפים לעשייה (ביניהם נציג ארגון רוטרי המסור שמלווה את בית הספר), עסקה בחשיבות הקשר בין הגוף לנפש ובדרכים שונות להבעה ותקשורת.</p>
<p data-sourcepos="13:1-13:259">לאורך הערב כולו, הוצגה בבית הספר תערוכת אמנות צבעונית ומרגשת שיצרו תלמידי בית חינוך צלילים. התערוכה, שקיבלה השראה מיצירותיהם של האמנים הנודעים וסילי קנדינסקי וחואן מירו, חשפה את עולמם הפנימי העשיר של התלמידים ואת יכולתם המופלאה לבטא את עצמם באמצעות צבע וצורה.</p>
<p data-sourcepos="15:1-15:339">האירוע המרגש בבית חינוך צלילים המחיש בצורה עוצמתית את האמונה העמוקה של הצוות החינוכי בכוחה של השותפות הקהילתית כגורם מפתח בהצלחת התלמידים ובהכנתם לחיים מלאים ומשמעותיים. מעבר לכך, האירוע הדגיש את חשיבות האמנות ככלי רב ערך להעצמה אישית, לביטוי עצמי ולחיזוק הקשר עם העולם הסובב, ובסופו של דבר, לבניית חברה סובלנית, מכילה וחזקה יותר במודיעין.</p>

</div>
