insert into entity_categories (entity_type, entity_id, category_id) values ('article', '2727a088-a920-5283-ad00-0bffbc15973d', 'e9ccc079-df4e-519b-9885-8b4eba35de06') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('3940bf3c-48eb-57da-a9b9-d153ac3e4c71', 'הלב של מודיעין פועם: ילדי "ענבלים" מחבקים את המשפחות השכולות', 'modiin-news-129', '<div id="model-response-message-contentr_d9b78ca2b8f6e3a1" class="markdown markdown-main-panel enable-updated-hr-color" dir="rtl">
<p data-sourcepos="3:1-3:203"><strong>לא תאמינו כמה עוצמה יש במפגש התמים הזה: תלמידי כיתה ה''2 מבית הספר "ענבלים" יצאו למשעולי ההנצחה בעיר, והניחו מכתבים וציורים מלאי אהבה לזכר הנופלים. רגעים מרגשים עם המשפחות השכולות שלא ישאירו עין יבשה!</strong></p>
<p data-sourcepos="5:1-5:233">בבוקר יום שישי האחרון, ה-16.5, נרשם רגע נוגע ללב במיוחד במרחב הזיכרון של מודיעין. תלמידי כיתה ה''2 מבית הספר היסודי "ענבלים" יצאו לפעילות חינוכית-ערכית מרגשת במיוחד: ביקור במשעולי ההנצחה המוקדשים לבני ובנות העיר שנפלו בהגנה על המדינה.</p>
<p data-sourcepos="7:1-7:220">הילדים הגיעו למשעולים כשהם אוחזים בידיהם ציורים צבעוניים ומילים חמות שכתבו, כל אחד לזכרו של נופל או נופלת תושבי העיר. המעשה הספונטני והטהור הזה, של ילדים צעירים המבקשים לחבק ולזכור את גיבורי עירם, ריגש עמוקות את הנוכחים.</p>
<p data-sourcepos="9:1-9:355">שיא הפעילות היה המפגש המרגש בין התלמידים לבני המשפחות השכולות, שאיבדו את יקיריהם בטבח הנורא של 7 באוקטובר ובמלחמת "חרבות ברזל". מיכאל נימרי, אביה של סרן עדן נימרי ז"ל, ויקי עבודי, אימו של רס"ן אדיר עבודי ז"ל, ליטל שוחט, אימה של סמלת שירה שוחט ז"ל, ושירלי, יותם עומר ולביא מחלוף, רעייתו ובניו של סא"ל סהר ציון מחלוף ז"ל, קיבלו את פני הילדים בהתרגשות גדולה.</p>
<p data-sourcepos="11:1-11:226">הילדים העניקו למשפחות את הציורים והמכתבים שיצרו, מנסים במילים פשוטות ובציורים מלאי כוונה טובה, להביע את תחושות הכאב, הגאווה והזיכרון. המפגש הזה, בין דור העתיד של העיר לבין אלו ששילמו את המחיר היקר מכל, היה עוצמתי ומרגש במיוחד.</p>
<p data-sourcepos="13:1-13:373">מיזם ההנצחה העירוני "מעלות ומשעולי הנופלים במודיעין מכבים רעות" הוא פרויקט ייחודי שמנציח את בני ובנות העיר שנפלו בהגנה על המדינה. במסגרת המיזם, נקראים משעולים ומעלות ברחבי העיר על שמם של הנופלים, בתהליך משותף עם המשפחות השכולות שבחרו את מיקומי ההנצחה לזכר יקיריהן. בכל אתר מוצבת אבן זיכרון עם משפטי הנצחה וקוד QR המוביל לאתר אינטרנט המספר את סיפור חייהם ומורשתם של הנופלים.</p>
<p data-sourcepos="15:1-15:234">המפגש המרגש הזה הוא עדות חיה לחוסנה של הקהילה במודיעין, לערבות ההדדית ולחשיבות העברת זכר הנופלים מדור לדור. לראות את ילדי "ענבלים" מחבקים את המשפחות השכולות בצורה כל כך טהורה ומרגשת, מחזק את האמונה שלנו בעתיד ובכוחו של הזיכרון המשותף.</p>
<p data-sourcepos="17:1-17:108"><strong>מודיעין, אתם קהילה מדהימה! תודה לתלמידי "ענבלים" ולמשפחות השכולות על רגעים מעוררי השראה של אהבה וזיכרון!</strong></p>

</div>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/05/IMG-20250516-WA0004.jpg', 'published', '2025-05-18 09:15:39') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
