insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('32bf4bc2-1dd6-5b84-8962-70efa93345f0', '"נקי בזכותי": הפתעה מתוקה לבעלי כלבים טובים במודיעין - אבל זה לא הכל!', 'modiin-news-130', '<div id="chat-history" class="chat-history-scroll-container">
<div id="6533ef1c540e0e1f" class="conversation-container message-actions-hover-boundary tts-removed ng-star-inserted">
<div>
<div class="response-container ng-tns-c1619469954-181 response-container-with-gpi tts-removed ng-star-inserted response-container-has-multiple-responses">
