insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('0ab95d3a-ac1e-5b48-83e5-00924c69bdd2', 'ערב סרט בחינם ליד הבית? מודיעין הופכת לקולנוע ענק תחת כיפת השמיים!', 'modiin-news-132', '<div id="chat-history" class="chat-history-scroll-container">
<div id="19a26d9f5621223f" class="conversation-container message-actions-hover-boundary tts-removed ng-star-inserted">
<div>
<div class="response-container ng-tns-c1619469954-191 response-container-with-gpi tts-removed ng-star-inserted response-container-has-multiple-responses">
<div class="presented-response-container ng-tns-c1619469954-191">
