insert into entity_categories (entity_type, entity_id, category_id) values ('article', '9cd467f9-704d-5e7c-af07-3a4e14a15c9f', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('47e3d3b1-9df6-5d10-91aa-043ab1bdac45', 'חדר הכושר החדש בעירוני ב'' ייקרא על שמו של שגב שושן ז"ל, שנרצח בנובה', 'modiin-news-144', '<p data-sourcepos="7:1-7:170"><strong>רגעים קורעי לב של גאווה וכאב: בטקס מרגש במיוחד, בית הספר עירוני ב'' הנציח את בוגרו האהוב, שגב שושן ז"ל, שנרצח ב-7 באוקטובר. הפרטים המלאים על המחווה המרגשת שיזמו הוריו.</strong></p>
<p data-sourcepos="9:1-9:218">מודיעין התייחדה ביום שישי האחרון (23.5.25) בטקס מרגש במיוחד שנערך בתיכון עירוני ב'' ע"ש יצחק רבין. באירוע מרגש ונוגע ללב, הוסר הלוט מעל השלט שיקבע באופן רשמי את שמו של חדר הכושר בבית הספר – "חדר הכושר ע"ש שגב שושן ז"ל".</p>
<p data-sourcepos="11:1-11:236">שגב ז"ל, בוגר מחזור ט'' של בית הספר, נרצח באכזריות בטבח הנורא שאירע במסיבת הנובה בעוטף עזה ב-7 באוקטובר. שגב, שהיה בחור מלא חיים, למד במגמת חינוך גופני – מגמה שהייתה בעלת משמעות עמוקה עבורו וסייעה לו לבצע שינוי חיובי ומשמעותי באורח חייו.</p>
<p data-sourcepos="13:1-13:252">הטקס, שנוהל באווירה של כאב וזיכרון לצד הכרה בתרומתו של שגב, נערך במעמד בני משפחתו היקרים, ראש העיר חיים ביבס, צוות בית הספר ורכז מגמת החינוך הגופני. רגע מרגש נוסף בטקס היה חלוקת תעודות הסיום של קורס מדריכי כושר לבוגרי המגמה, תלמידיו של שגב במובן מסוים.</p>
<p data-sourcepos="15:1-15:241">במחווה מרגשת במיוחד, <strong>הוריו של שגב, שאיבדו את יקירם, החליטו לאמץ את תלמידי המגמה של בנם.</strong> מדי שנה, יחד עם תעודות הסיום, יחלקו הוריו של שגב <strong>שי צנוע למסיימים</strong>, ובכך ימשיכו להנציח את זכרו של שגב ואת רוחו המיוחדת בדרך שהייתה כל כך חשובה לו.</p>
<p data-sourcepos="17:1-17:168">הנצחתו של שגב ז"ל בבית הספר בו למד ובו מצא את תשוקתו לחינוך גופני, היא דרך מרגשת לשמר את מורשתו ולהזכיר לכולנו את המחיר הכבד של הטרור, לצד החשיבות של חיים, אהבה וקהילה.</p>
<p data-sourcepos="19:1-19:25"><strong>יהי זכרו של שגב ברוך.</strong></p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/05/IMG-20250523-WA0004.jpg', 'published', '2025-05-27 07:21:11') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
