insert into entity_categories (entity_type, entity_id, category_id) values ('article', 'cdadb37b-83a8-5b9d-95aa-76a85224e0a4', 'e9ccc079-df4e-519b-9885-8b4eba35de06') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('27ead6c6-a6c6-5011-a0ea-7830e558d66f', 'שוטרי משטרת מודיעין פענחו שוד מזויין של אופנוע חשמלי ביער בן שמן', 'modiin-news-157', 'דוברות המשטרה:

שוטרי משטרת מודיעין פענחו שוד מזויין של אופנוע חשמלי ביער בן שמן ובהתאם לממצאי החקירה עצרו תושב לוד והגישו נגדו הצהרת תובע לצד השבת האופנוע לבעליו

שוטרי תחנת מודיעין פתחו בחקירה לפני כחודש, עם קבלת דיווח מתושב פתח תקוה כבן 20, בדבר שוד באיומי סכין של האופנוע שלו ביער בן שמן.

בתום פעילות מודיעינית מואצת, הצליחו חוקרי התחנה לחשוף את זהות החשוד- תושב לוד כבן 20 ולעוצרו, לצד חיפוש ותפיסת האופנוע הגנוב של הקורבן, שהושב לבעליו.

בהתאם לממצאי החקירה, מעצרו של החשוד הוארך בבימ"ש ובסיומה הגישה נגדו המשטרה היום הצהרת תובע ובימים הקרובים יוגש נגדו ע"י הפרקליטות כתב אישום חמור בבימ"ש המחוזי בלוד.', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/06/WhatsApp-Image-2025-06-04-at-17.38.31.jpeg', 'published', '2025-06-04 14:42:27') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
