insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('f87ae33a-6d85-5ddb-8da4-6be2a120d172', 'מרגש במודיעין: העיר מחבקת 85 קשישים מפונים מתל אביב', 'modiin-news-174', '<p data-sourcepos="4:1-4:172"><strong>קבלת פנים חמה ומרגשת התקיימה אתמול במודיעין ל-85 קשישים מפונים מדיור מוגן בתל אביב, שנפגע אתמול מנפילת טיל. תושבי העיר, במעשה מרגש של ערבות הדדית, התגייסו לסייע בקליטתם.</strong></p>
<p data-sourcepos="4:1-4:172"><img class="alignnone size-medium wp-image-5640" src="https://www.modiin4u.co.il/wp-content/uploads/2025/06/498159195_1494962445166617_698028619743516355_n-300x225.jpg" alt="מלון ג׳ייקוב מודיעין" width="300" height="225" /></p>
<p data-sourcepos="4:1-4:172">קרדיט תמונה: אינסטגרם עיריית מודיעין</p>
<p data-sourcepos="6:1-6:248">האירוע המרגש התאפשר בזכות ההתגייסות המהירה של תושבי מודיעין, המתנדבים במערך הביטחון והחירום העירוני. המתנדבים, שגויסו על ידי <strong>חמ"ל הביטחון העירוני</strong> שהוקם מתחילת המלחמה, פעלו יחד עם אנשי <strong>פיקוד העורף</strong> כדי לקלוט את המפונים ב<a href="https://www.modiin4u.co.il/business/jacob-hotel-azrieli/">מלון ג''ייקוב במודיעין</a>.</p>
<p data-sourcepos="6:1-6:248"><img class="alignnone size-medium wp-image-5641" src="https://www.modiin4u.co.il/wp-content/uploads/2025/06/510495746_1494962271833301_6824907406060095824_n-139x300.jpg" alt="" width="139" height="300" /></p>
<p data-sourcepos="6:1-6:248">קרדיט תמונה: אינסטגרם עיריית מודיעין</p>
<p data-sourcepos="8:1-8:292">מדובר באוכלוסייה מבוגרת מאוד, שהגיעה למלון לאחר אירוע מטלטל. הם התקבלו בחיבוק ענק ובחיוך רחב על ידי המתנדבים וצוות המלון המסור. הסיוע שהוגש למפונים כלל עזרה פיזית במשימות שונות: סחיבת מזוודות, סיוע עם כיסאות גלגלים, ליווי לחדרים ועוד. כל זאת, מתוך דאגה עמוקה ורצון להקל עליהם ברגעים קשים אלו.</p>
<p data-sourcepos="8:1-8:292"><img class="alignnone size-medium wp-image-5642" src="https://www.modiin4u.co.il/wp-content/uploads/2025/06/506531557_1494962231833305_5158098997918040430_n-300x139.jpg" alt="" width="300" height="139" /></p>
<p data-sourcepos="8:1-8:292">קרדיט תמונה: אינסטגרם עיריית מודיעין</p>
<p data-sourcepos="10:1-10:183">"אין תחושה טובה מזו," ציינו בעירייה, והודו לתושבים שמוכיחים שוב ושוב את עוצמתה של הערבות ההדדית במודיעין. אנו מצטרפים לאיחולי <strong>התאקלמות קלה ומהירה למפונים</strong>, ומאחלים להם שקט ובריאות.</p>
<p data-sourcepos="12:1-12:62"><strong>תושבי מודיעין ממשיכים להוות דוגמה ומופת לנתינה ולקהילתיות!</strong></p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/06/WhatsApp-Image-2025-06-24-at-13.00.12.jpeg', 'published', '2025-06-24 10:36:27') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', 'f87ae33a-6d85-5ddb-8da4-6be2a120d172', 'e9ccc079-df4e-519b-9885-8b4eba35de06') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('7403e12b-f048-51c5-88ae-dd936a2f34c2', 'מורשת מול אבני חן – השוואת שכונות מערב מודיעין', 'moreshet-vs-avneuhen', '<p class="p1" dir="rtl"><span class="s1">מודיעין ממשיכה להתפתח מערבה, ושתי שכונות בולטות במערב העיר – </span><span class="s2">שכונת מורשת</span><span class="s1"> ו</span><span class="s2">שכונת אבני חן (קייזר)</span><span class="s1"> – מעוררות עניין רב בקרב תושבי העיר, זוגות צעירים, משפרי דיור ומשקיעי נדל״ן. בעוד אבני חן היא שכונה ותיקה ומבוססת שאוכלסה החל מ-2003, מורשת היא שכונה חדשה שהחלה באכלוס רק בשנת 2022 </span> <span class="s1">. בכתבה זו נבצע השוואה מקיפה בין שתי השכונות לפי מספר מדדים מרכזיים – מחירי דירות ושכירות, אופי הבנייה (חדשה מול ותיקה), איכות החיים והקהילה, תחבורה ונגישות, תכנון עתידי והתפתחות – ונבחן את היתרונות והחסרונות העיקריים של כל אחת. בסיום, נציג מסקנות והמלצות מעשיות המתאימות לקהלי יעד שונים בעיר.</span></p>

<h2><span class="s1">מחירי דירות ודמי שכירות בשכונות</span></h2>
<p class="p1" dir="rtl"><span class="s2">מחירי מכירה:</span><span class="s1"> מחירי הדיור בשתי השכונות משקפים את המיקום המבוקש במודיעין. ממוצע מחירי הדירות כיום דומה יחסית – סביב </span><span class="s2">3 מיליון ש”ח</span><span class="s1"> לדירה סטנדרטית. עם זאת, יש הבדלים לפי סוג הנכס: באבני חן, שכונה ותיקה ומבוקשת, דווח על עסקאות ממוצעות בכ-2.95 מיליון ש”ח </span><span class="s1">, ודירות 4 חדרים מיד שנייה נמכרו סביב 3.3–3.4 מיליון ש”ח בממוצע </span><span class="s1">. גם במורשת, על אף היותה שכונה חדשה, מחירי דירות 4 חדרים חדשות התייצבו סביב </span><span class="s2">3.2–3.3 מיליון ש”ח</span><span class="s1"> לדירה ממוצעת </span><span class="s1">. דירות 3 חדרים במורשת נמכרות באזור </span><span class="s2">2.7–2.8 מיליון ש”ח</span><span class="s1"> בממוצע, לעומת כ-</span><span class="s2">2.9 מיליון ש”ח</span><span class="s1"> באבני חן </span><span class="s1">, ואילו דירות 5 חדרים גדולות יותר נמכרות בשני המקרים סביב </span><span class="s2">3.8–4.0 מיליון ש”ח</span><span class="s1"> (תלוי בגודל ובסוג הנכס). חשוב לציין שבאבני חן קיימים גם </span><span class="s2">קוטג’ים ובתים צמודי-קרקע</span><span class="s1"> יקרים בהרבה – למשל, לאחרונה נמכר דו-משפחתי בשכונה (5 חד’ + מרתף, כ-130 מ”ר בנוי) במחיר של </span><span class="s2">5.5 מיליון ש”ח</span> <span class="s1">, מה שמדגיש את טווח המחירים הרחב בשכונה הוותיקה.</span></p>
<p class="p1" dir="rtl"><span class="s2">דמי שכירות:</span><span class="s1"> גם בגזרת השכירות הנתונים דומים, עם ביקוש גבוה להשכרה בשתי השכונות. בממוצע, שכר הדירה המבוקש בעיר מודיעין לדירת 4 חדרים הוא כ-</span><span class="s2">6,800 ש”ח לחודש</span> <span class="s1">. בשכונת מורשת דמי השכירות מעט נמוכים ממוצע זה בשל ההיצע הרב: דירת 4 חדרים חדשה במורשת מושכרת סביב </span><span class="s2">6,500 ש”ח</span><span class="s1"> בממוצע, ודירת 3 חדרים בכ-</span><span class="s2">6,000 ש”ח</span> <span class="s1">. באבני חן, דמי השכירות של דירות 4 חדרים נוטים להיות קרובים יותר לממוצע העירוני (כ-</span><span class="s2">6,800–7,000 ש”ח</span><span class="s1">), ודירות 5 חדרים גדולות אף מגיעות לכ-</span><span class="s2">7,500–8,000 ש”ח</span><span class="s1"> בחודש, בהתאם לגודל ולמצב הנכס. יש לזכור כי באבני חן חלק ניכר מהנכסים הם בבעלות תושבים ותיקים וערך השכירות נגזר גם ממיעוט היצע בשוק, בעוד שבמורשת חלק מהדירות נרכשו במקור במסגרת תוכנית מחיר למשתכן ולכן מוצעות כעת לשכירות רבות יותר – </span><span class="s2">מורשת היא השכונה המובילה בעיר בהיצע דירות להשכרה</span></p>
<p class="p1" dir="rtl"><span class="s1">בסיכומו של דבר, </span><span class="s2">מחירי הדירות בשתי השכונות גבוהים למדי</span><span class="s1"> ומשקפים את הביקוש בעיר. אבני חן נהנית ממוניטין של שכונה יציבה ואטרקטיבית – מתווכים מעידים שנכסים מיוחדים בה נמכרים במהירות וללא ירידת מחיר </span><span class="s1">. לעומת זאת, במורשת ניכר כי ריבוי הדירות החדשות (הן דירות קבלן והן דירות “מחיר למשתכן” שזוכים מנסים למכור ברווח) יוצר תחרות מסוימת בין מוכרים, מה שמביא </span><span class="s2">להתמתנות ואפילו לירידה קלה ברמת המחירים המבוקשים</span><span class="s1"> בשכונה החדשה </span><span class="s1">. למרות זאת, מי שרכש שם דירה מוזלת במסגרת תוכנית למשתכן עדיין צפוי לרשום רווח נאה בעת המכירה, אך ייתכן שהתהליך יהיה איטי יותר בשל התחרות הרבה בשוק </span><span class="s1">.</span></p>

<h2><span class="s1">זמינות בנייה חדשה לעומת בנייה ותיקה</span></h2>
<p class="p1" dir="rtl"><span class="s1">אחד ההבדלים המהותיים בין השכונות הוא </span><span class="s2">גיל הבתים ואופי הבנייה</span><span class="s1">. שכונת </span><span class="s2">אבני חן</span><span class="s1"> ותיקה יותר – אוכלסה לראשונה בשנת 2003, וכיום (2024) מתגוררים בה כ-10,952 תושבים בכ-1,891 משקי בית </span><span class="s1">. מרבית הבנייה בשכונה זו היא </span><span class="s2">בנייה ותיקה</span><span class="s1"> (כ-20 שנה), וכוללת מגוון רחב מאוד של סוגי נכסים: </span><span class="s2">בניינים נמוכים</span><span class="s1"> עד 4 קומות לצד </span><span class="s2">בנייני דירות גבוהים</span><span class="s1"> ומגדלים, וכן </span><span class="s2">בתים צמודי קרקע, קוטג’ים ודופלקסים</span><span class="s1"> ברחובות מסוימים </span> <span class="s1">. למעשה, אבני חן (המכונה גם “קייזר” ע”ש המתכנן דני קייזר) ידועה בשילוב המגוון של סוגי הדיור – מדירות גן וגג, דרך דירות בבנייני קומות ועד וילות עירוניות – המאפשר למשפחות למצוא דיור המתאים לצרכיהן ולתקציבן. בבנייה הוותיקה ייתכן כי חלק מהדירות זקוקות לרענון או שיפוץ, אך המרחב הציבורי בשכונה כבר מבוסס ומטופח לאורך שנים.</span></p>
<p class="p1" dir="rtl"><span class="s2">שכונת מורשת</span><span class="s1">, לעומת זאת, היא </span><span class="s2">שכונת בנייה חדשה</span><span class="s1"> בהתהוות. השכונה נבנית על שטח של כ-1,600 דונם למרגלות גבעת ברפיליה, וגובלת מדרום בשכונת נופים ומצפון בשטח עתודת פיתוח עתידי (שלב ב’ של העיר) </span> <span class="s1">. התכנון המקורי של מורשת כולל </span><span class="s2">4,204 יחידות דיור</span><span class="s1"> – מהן כ-70% (כ-2,900 דירות) ששווקו במסגרת תוכנית “מחיר למשתכן” לצעירים </span><span class="s1">. הבנייה החלה בסוף העשור הקודם, ואכלוס ראשוני החל בפברואר 2022 </span><span class="s1">. נכון ל-2024, גרים במורשת כ-5,224 תושבים בכ-2,360 משקי בית </span><span class="s1">, כלומר השכונה כבר הגיעה ללמעלה ממחצית מגודלה הצפוי, עם המשך אכלוס פרויקטים חדשים. כל הבתים במורשת הם </span><span class="s2">מבנים חדשים</span><span class="s1"> בני פחות מ-5 שנים, ונבנו לפי סטנדרטים מודרניים (מרפסות, ממ”דים, חניה תת-קרקעית וכו’). הבנייה כוללת בעיקר </span><span class="s2">בנייני דירות מודרניים</span><span class="s1"> בגבהים שונים (רובם 6–10 קומות, חלקם אפילו מגדלים מעט גבוהים יותר לאורך השדרה המרכזית), וכן מספר מצומצם של בנייני בוטיק נמוכים. אין כמעט צמודי-קרקע במורשת, מה שמשקף תכנון עירוני אורבני יותר בצפיפות גבוהה. עבור מי שמחפש </span><span class="s2">דירה חדשה “מהניילונים”</span><span class="s1"> – מורשת היא האפשרות הברורה, שכן באבני חן כמעט שאין פרויקטים חדשים למגורים (פרט אולי ליוזמות התחדשות עירונית בעתיד הרחוק). מנגד, </span><span class="s2">למשפרי דיור המחפשים בית גדול עם גינה</span><span class="s1"> – אבני חן מציעה אפשרויות של בתים דו-משפחתיים וקוטג’ים שקשה למצוא במורשת החדשה.</span></p>
<p class="p1" dir="rtl"><span class="s1">חשוב גם לציין את השפעת </span><span class="s2">תוכנית מחיר למשתכן</span><span class="s1">: במורשת חלק משמעותי מהדירות הוגרלו לזכאים במחירים מוזלים, ואלפי זוגות צעירים נכנסו כך לשכונה. רבים מהם מתגוררים בדירות אלו, אך חלק גם מנסים למכור או להשכיר אותן. הדבר יוצר היצע גדול של דירות “יד ראשונה” בשוק, כפי שהוזכר, וכך מורשת מתאפיינת בשוק נדל”ן דינמי מאוד בשנים הראשונות לקיומה. בשכונת אבני חן, לעומת זאת, רוב העסקאות הן </span><span class="s2">יד שנייה</span><span class="s1"> בין תושבים, והשוק יציב יותר עם היצע דירות יד שנייה מצומצם ביחס לביקוש.</span></p>

<h2><span class="s1">איכות החיים: קהילה, חינוך ופנאי בשכונות</span></h2>
<p class="p4" dir="rtl"><span class="s2">מבני ציבור, חינוך וקהילה:</span><span class="s1"> שכונת אבני חן היא שכונה מבוססת עם תשתית קהילתית וחינוכית ענפה. בשכונה פועלים כמה </span><span class="s2">בתי ספר</span><span class="s1"> וותיקים: בית ספר יסודי ממלכתי “אבני חן”, בית ספר ממלכתי-דתי “דרכי יהודה”, בית ספר יסודי “חוט השני” וכן חטיבת ביניים/תיכון עירוני ה’ </span><span class="s1">. מעבר לכך, ישנן מעונות יום וגני ילדים רבים הפזורים בשכונה (בעקבות גלי האכלוס בשנות ה-2000). לצד מוסדות החינוך, אבני חן מציעה </span><span class="s2">מוסדות ציבור ודת</span><span class="s1"> כגון בתי כנסת בשכונה, וכן סניפי תנועות נוער. בשכונה נמצא גם </span><span class="s2">מקווה לנשים</span><span class="s1"> ברחוב אבני החושן </span><span class="s1">. המרקם הקהילתי באבני חן מגוון – מתגוררת בה אוכלוסייה מעורבת של חילונים ודתיים לאומיים, כולל קהילה אנגלו-סקסית דתית מורגשת </span><span class="s1">. התמהיל הבוגר יותר של האוכלוסייה (גיל ממוצע מעט גבוה ביחס לשכונות החדשות) אומר שחלק מהילדים שגדלו בשכונה כבר בגרו, אך עדיין משפחות צעירות ממשיכות לעבור אליה בזכות איכות החיים. לפי גורמי נדל”ן מקומיים, הקהילתיות והאופי המבוסס של אבני חן מהווים גורם משיכה רב – “שכונה מאוד מבוקשת בעיר… יש בה קהילה חזקה… אנחנו באמת לא רואים ירידות מחירים בנכסים כאלה בשכונה” מעידה מתווכת ותיקה </span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s2">במורשת</span><span class="s1">, כמקובל בשכונות חדשות, המערכת הקהילתית עדיין בבנייה אך מתפתחת במהירות. כבר בתכנון השכונה הוקצו שטחים למוסדות חינוך וציבור: מוקמים </span><span class="s2">3 בתי ספר יסודיים</span><span class="s1"> (חלקם כבר פועלים נכון ל-2023/24), </span><span class="s2">בית ספר על-יסודי</span><span class="s1"> אחד, וכמובן שפע </span><span class="s2">גני ילדים</span><span class="s1"> לכלל האוכלוסייה שנכנסה לשכונה </span><span class="s1">. בשנת הלימודים תשפ”ד (2023) נפתחו בתי ספר ראשונים בשכונה, לאחר שבתחילה חלק מילדי מורשת התחנכו בשכונות סמוכות (כגון אבני חן ונופים) עד להשלמת מבני החינוך החדשים </span><span class="s1">. הקהילה במורשת מורכבת ברובה מזוגות צעירים ומשפחות בראשית דרכן – רבים כאמור זוכי מחיר למשתכן או רוכשי דירות חדשות. כתוצאה, הגיל הממוצע בשכונה צעיר, והאווירה “טרייה” ותוססת. העירייה ומוסדותיה משקיעים במפגשים ובפעילויות לתושבים החדשים: עוד טרם פתיחת מוסדות החינוך, התקיימו מפגשי הסברה להורי השכונה החדשה כדי לשלבם במערכת החינוך העירונית </span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">מבחינת </span><span class="s2">מרכזים קהילתיים ופעילויות פנאי</span><span class="s1">, באבני חן פועל </span><span class="s2">מרכז ספורט ובריכה עירונית</span><span class="s1"> גדול על גבול השכונה (בעמק זבולון) המשמש את תושבי האזור </span><span class="s1">. כמו כן פזורים מספר </span><span class="s2">מרכזים מסחריים שכונתיים קטנים</span><span class="s1"> ברחובות לשם, אבני החושן, אודם ובדולח, בהם מרוכזים חנויות קטנות, מכולות ומקומות שירות שכונתיים </span><span class="s1">. מרכז מסחרי גדול יותר עם סופרמרקט וקניון קטן מצוי ברחוב עמק זבולון, בקצה המזרחי של השכונה </span><span class="s1">. בנוסף, בצמוד לאבני חן (בגבולה הדרומי) נמצא </span><span class="s2">קניון עזריאלי מודיעין</span><span class="s1"> במרחק נסיעה קצר, מה שמקנה לתושבי אבני חן נגישות נוחה למרכזי קניות גדולים. גם </span><span class="s2">המרכז העירוני</span><span class="s1"> של מודיעין וכיכר העירייה אינם רחוקים במיוחד. מהבחינה החברתית, תושבי אבני חן נהנים </span><span class="s2">ממרקם חיים שקט ובשל</span><span class="s1"> – זוהי שכונה שכבר “התבגרה”: העצים ברחובות צמחו, הגינות הציבוריות ותיקות ומצילות, והתושבים הוותיקים מכירים זה את זה. מיקום השכונה גם נחשב מרכזי יחסית – בין היתר קרבה לתחנת הרכבת “מודיעין מרכז” ולקניון, במרחק נסיעה של דקות ספורות </span><span class="s1">.</span></p>
<p class="p4" dir="rtl"><span class="s1">עבור תושבי מורשת, חלק מהיתרונות הקהילתיים עדיין </span><span class="s2">בתהליך הקמה</span><span class="s1">, אך יש מספר פרויקטים מבטיחים בתחום הפנאי והתרבות. בלב שכונת מורשת, על גבעת אשון, מוקם </span><span class="s2">פארק ארכיאולוגי ייחודי</span><span class="s1"> המשמר עתיקות שהתגלו באתר, וסביבו מבני המגורים של השכונה </span><span class="s1">. הפארק ישמש כשטח ירוק מרכזי ויהווה אטרקציה לימודית ופנאי לתושבים. בנוסף, אושרה הקמתו של </span><span class="s2">קונסרבטוריון עירוני חדש</span><span class="s1"> בשכונה – מבנה תרבות גדול בן שתי קומות שיכלול אולם קונצרטים לכ-300 איש, חדרי מוזיקה ממוגנים אקוסטית, חניון תת-קרקעי וגג ירוק לאירועים </span><span class="s1">. הקונסרבטוריון, שיוקם בצפון השכונה, ישמש כמרכז חוגים והופעות ויתרום לחיי התרבות במורשת. זהו חלק ממגמה של העירייה להפוך את מורשת למוקד חדש של מוסדות ציבור ותרבות במערב העיר.</span></p>
<p class="p1" dir="rtl"><span class="s2">גינות ופארקים:</span><span class="s1"> אבני חן ידועה בשפע השטחים הירוקים שסביבה – </span><span class="s2">פארק ענבה</span><span class="s1"> הגדול של מודיעין גובל בצדה הדרומי של השכונה, ובתוכה מספר פארקים וגינות ציבוריות מטופחים. בין הפארקים המרכזיים בשכונה ניתן למנות את </span><span class="s2">פארק המשפחה</span><span class="s1">, </span><span class="s2">פארק הפסלים</span><span class="s1"> (עם מתקני משחק ופסלי חוצות), ו</span><span class="s2">פארק הנגישות</span> <span class="s1">. לאורך עמק זבולון שעובר בקצה השכונה יש טיילת להולכי רגל (טיילת “חוט השני”) המחברת את אבני חן לאזורים אחרים. בנוסף, בשכונה אף הוקמה </span><span class="s2">גינת כלבים</span><span class="s1"> ייעודית ברחוב עמק זבולון לטובת בעלי הכלבים </span><span class="s1">. מוקדי טבע עירוני סמוכים כוללים את </span><span class="s2">גבעת ברפיליה</span><span class="s1"> – גבעה עם שבילי טיול ונוף פתוח הנמצאת ממש מערבית לאבני חן </span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">מורשת, בהיותה חדשה, עדיין משלבת תשתיות נוף צעירות, אך התכנון האורבני שלה שם דגש על </span><span class="s2">שטחים ציבוריים איכותיים</span><span class="s1">. לאורכה של השכונה נסללה </span><span class="s2">שדרה מרכזית באורך של כחצי ק”מ</span><span class="s1"> – ציר ציבורי ומסחרי ראשי, הכולל מדרכות רחבות, פרגולות הצללה, שבילי אופניים, גינות נוי ועצים, ותאורה מודרנית </span><span class="s1">. השדרה הזו מהווה את “עמק חפר” – הרחוב המרכזי העתידי שיחבר את מורשת עם המשך פיתוח העיר בעתיד. לאורך השדרה וביתר רחובות השכונה פזורים </span><span class="s2">גני שעשועים וגינות קטנות</span><span class="s1"> עבור התושבים (חלקם עדיין בשלבי הקמה אחרונים). כמובן שעם הזמן, כשהעצים יגדלו והגינות יתבססו, תהנה השכונה מסביבה ירוקה ונעימה כמו בשכונות הוותיקות. בצפון-מערב מורשת מתוכנן גם </span><span class="s2">פארק גדול (“פארק הבוסתנים”)</span><span class="s1"> לצד המתחמים הצפוניים, שיהווה רצועה ירוקה מול הנוף הפתוח לכיוון יער בן-שמן </span><span class="s1">. לסיכום, בעוד שבאבני חן היתרון הוא בגינות הוותיקות ובסמיכות המיידית לפארק ענבה, מורשת מציעה כבר כעת מרחבים ציבוריים חדשים ומעוצבים, ועתידה ליהנות מפארקים ייחודיים בתוך השכונה ומטיילות מחברות.</span></p>
<p class="p1" dir="rtl"><span class="s2">מסחר ושירותים קרובים:</span><span class="s1"> יתרון חשוב לאיכות החיים הוא נושא המסחר והשירות. כאמור, באבני חן יש מספר מרכזים שכונתיים קטנים ומרכז מסחרי אחד גדול בשוליה. אולם, ייתכן שהמענה המסחרי לא תמיד הספיק לכל צורכי השכונה, במיוחד בשעות הערב. כאן נכנסת לתמונה </span><span class="s2">שכונת מורשת</span><span class="s1">, שמתוכננת מלכתחילה ככזו שמשלבת עירוב שימושים: השדרה המרכזית של מורשת נבנתה עם קומות קרקע מסחריות, וכבר כיום נפתחו לאורכה חנויות, בתי קפה ושירותים לתושבים. בנוסף, בלב מורשת (בנקודת המפגש שלה עם אבני חן) מוקם בימים אלו </span><span class="s2">מרכז קניות ותעסוקה חדש בשם “פורום מורשת”</span><span class="s1"> – מבנה מתקדם בעל שתי קומות מסחר סביב חצר פתוחה, מעליהן שש קומות משרדים </span><span class="s1">. פורום מורשת עתיד להיות </span><span class="s2">המרכז המסחרי העיקרי של השכונה</span><span class="s1"> ולספק את כל צרכי הקמעונאות, הבריאות והפנאי של כ-16,000 תושבי מורשת והסביבה </span><span class="s1">. המרכז יכלול סופרמרקט, סניף פארם, בתי קפה ומסעדות, חנויות מגוונות וכן </span><span class="s2">חדר כושר גדול</span><span class="s1"> מרשת ארצית </span> <span class="s1">. יתרה מזאת, הוא צפוי ליצור מוקד תעסוקה מקומי לתושבים. מבחינת מיקום, הפורום יושב על גבול מורשת–אבני חן, כך שגם תושבי אבני חן יוכלו ליהנות משירותיו במרחק הליכה קצר. הפרויקט מתוכנן עם </span><span class="s2">חניה תת-קרקעית</span><span class="s1"> נוחה למבקרים </span><span class="s1">. למעשה, פתיחת המרכז החדש תעניק למערב מודיעין </span><span class="s2">מוקד מסחר שכונתי מודרני</span><span class="s1"> שלא היה כדוגמתו עד כה באבני חן, ותגשר בין האזור הוותיק לחדש.</span></p>
<p class="p1" dir="rtl"><span class="s1">ראוי להזכיר שקיימים גם אתגרי איכות חיים שנובעים מהמעבר בין ותיק לחדש: אחת הדוגמאות היא </span><span class="s2">קישוריות הולכי רגל בין השכונות</span><span class="s1">. תושבי מורשת ביקשו בעבר גשר להולכי רגל שיחבר את מורשת ישירות אל אבני חן (מעל כביש יהודה המכבי המפריד ביניהן), אולם תוכנית הגשר בוטלה בשלב זה בשל סוגיות הנדסיות ונגישות </span> <span class="s1">. במקום זאת נשקלות חלופות לשיפור המעבר הרגלי בין השכונות. נכון לעכשיו, המעבר מתבצע באמצעות צמתים מרומזרים לאורך יהודה המכבי. זהו פרט נקודתי, אך כזה שמשקף את הפער הזמני בתכנון – תושבי אבני חן נהנים מתשתיות מבוססות, ואילו במורשת יש לעתים צורך בהתאמות תשתית נוספות לאוכלוסייה הגדלה. עם זאת, העירייה קשובה לנושאים אלו, ובשנים הקרובות סביר שיושקעו משאבים נוספים בחיבוריות ונגישות הולכי הרגל והרוכבים בין חלקי העיר.</span></p>
<p class="p1" dir="rtl"><span class="s2">חנייה ועומסים פנימיים:</span><span class="s1"> בשתי השכונות, מרבית הבניינים מציעים חניה לדיירים – באבני חן בד”כ מדובר בחניות עיליות בסמוך לבניין (או קרקעיות בבניינים החדשים יותר), ובמורשת התקן המחמיר יותר הביא לריבוי חניות תת-קרקעיות בבניינים החדשים. בחיי היומיום, עומסי חנייה ברחובות לרוב manageable, אם כי כמו בכל שכונה, ליד מוסדות חינוך בשעות ההסעה יתכנו בעיות זמניות. היתרון במורשת הוא בתכנון העדכני: רחובות רחבים יותר, עם יותר מקומות חניה מוסדרים, וכן </span><span class="s2">שבילי אופניים ורגל</span><span class="s1"> המעודדים הגעה רגלית/רכובה במקום רכב. אבני חן נבנתה בעידן שפחות חשב על אופניים, אך יש בה לפחות את טיילת “חוט השני” להולכי רגל ורוכבים המחברת חלקים ממנה.</span></p>
<p class="p1" dir="rtl"><span class="s2">סיכום ביניים:</span><span class="s1"> מבחינת איכות חיים, </span><span class="s2">אבני חן</span><span class="s1"> מצטיינת בסביבה בשלה – גינות ותיקות, מוסדות חינוך וקהילה הפועלים מזמן, קהילה מבוססת ומגובשת ושירותים חיוניים קרובים (כולל פארק ענבה וקניון העיר). </span><span class="s2">מורשת</span><span class="s1"> מציעה מתקנים חדשים ומתוכננים היטב – בתי ספר חדשים, פארקים בתכנון עדכני, שטחי מסחר ופנאי חדישים – אך חלק מהדברים עדיין בהרצה וצריך מעט סבלנות עד שיושלמו. למשפחות עם ילדים צעירים, מורשת אטרקטיבית כי הכול חדש ובהתאמה לגידול האוכלוסייה (למשל גני משחקים מודרניים בכל פינה), בעוד שבאבני חן תשתלבו בקהילה ותיקה ותקבלו סביבת חיים “מוכנה” ומנוסה.</span></p>

<h2><span class="s1">תחבורה, נגישות וצירי תנועה מרכזיים</span></h2>
<p class="p1" dir="rtl"><span class="s1">אחד ההיבטים החשובים בבחירת מקום מגורים במודיעין הוא </span><span class="s2">נגישות תחבורתית</span><span class="s1"> – לשאר חלקי העיר, למרכזי תעסוקה, ולערים הגדולות (תל אביב וירושלים). כאן, מיקומן של מורשת ואבני חן במערב מודיעין מעניק להן יתרונות דומים, עם כמה הבדלים מעניינים.</span></p>
<p class="p1" dir="rtl"><span class="s2">גישה לרכב פרטי וכבישים מרכזיים:</span><span class="s1"> שתי השכונות נהנות מגישה קרובה לכביש 431, שמשמש עורק חיבור מהיר למטרופולין תל אביב (דרך כביש 1/נתיבי איילון) ולכיוון ראשל”צ ורמלה. עד לפני מספר שנים, הנסיעה מכיוון אבני חן אל כביש 431 הייתה עוברת דרך מחלף ענבה (בכניסה הראשית למודיעין) ולעיתים יצרה עומסי תנועה. אולם בשנת 2022 נחנך </span><span class="s2">מחלף עינב החדש</span><span class="s1"> בדרום-מערב העיר </span><span class="s1">, שפתח חיבור ישיר ונוח </span><span class="s2">לשכונות נופים ומורשת</span><span class="s1"> מכביש 431 (יצחק רבין) </span><span class="s1">. מחלף זה כולל גם ירידה למרכז עינב (אזור המסחר והעסקים ליד ישפרו סנטר), וכמובן מאפשר לתושבי מורשת ונופים לעלות על 431 לכיוון תל אביב/ראשל”צ בקלות רבה. בנוסף, בוצעו עבודות להרחבת </span><span class="s2">שדרות ענבה</span><span class="s1"> (הכביש המוביל ממחלף ענבה הישן לכיוון השכונות המערביות) ל-2 נתיבים לכל כיוון </span><span class="s1">, ובוטלו צווארי בקבוק ביציאה משכונת נופים לכיוון אבני חן – כך שכיום ניתן לנסוע מצומת שכונת נופים ישר לכיוון רחוב יהודה המכבי (גבול אבני חן) משני נתיבים, מה שהקל משמעותית את העומס בבוקר </span><span class="s1">. למעשה, תושב שגר במורשת או בנופים יכול בתוך דקות להגיע לכביש 431 במחלף עינב, </span><span class="s2">ללא צורך לעבור כלל דרך מרכז העיר</span><span class="s1">. תושבי אבני חן יכולים גם הם להשתמש במחלף עינב החדש: ניתן לנסוע דרומה דרך שדרות חשמונאים ונופים אל המחלף, או לחלופין לעלות על 431 דרך מחלף ענבה הוותיק (במזרח השכונה, בקצה עמק זבולון). כך או כך, </span><span class="s2">הנסיעה ברכב פרטי מתושבי שתי השכונות לבן-שמן, לנתב”ג, לת”א או לי-ם היא נוחה ומהירה יותר מבעבר</span><span class="s1">.</span></p>
<p class="p4" dir="rtl"><span class="s2">תחבורה ציבורית:</span><span class="s1"> מודיעין כולה נהנית מתשתית רכבות מצוינת, ושכונות מערב העיר נמצאות במרחק סביר משתי תחנות רכבת. </span><span class="s2">תחנת “פאתי מודיעין”</span><span class="s1"> (בצמוד לכביש 431 ומרכז עינב) היא הקרובה ביותר פיזית – מבחינת מרחק אווירי, מורשת קרובה מאוד לתחנה זו (כמה דקות נסיעה), ואבני חן במרחק קצת יותר גדול אך עדיין קצר. בפועל קיימים קווי אוטובוס עירוניים המחברים את אבני חן לתחנת פאתי מודיעין. </span><span class="s2">תחנת “מודיעין מרכז”</span><span class="s1"> (בקניון עזריאלי) נגישה גם היא: מאבני חן הנסיעה לרכבת מרכז אורכת כ-5 דקות ברכב או באוטובוס, וממורשת ייתכן 7–10 דקות נסיעה (כולל יציאה מהשכונה החדשה). חשוב לציין שבתחילה, עם אכלוס מורשת, נדרשו התאמות של מערך האוטובוסים – הוכנסו קווים חדשים או שינויים במסלולים כדי לכלול את רחובות מורשת. כיום (2025) השכונה כבר מחוברת בקווי אוטובוס אל מרכז העיר ותחנות הרכבת, אך תדירות הקווים עוד עשויה לגדול עם המשך אכלוס השכונה. אבני חן מצידה נהנית ממספר קווים ותיקים שעוברים בעמק זבולון וברחוב לשם ומוליכים למרכז ולתחנה.</span></p>
<p class="p1" dir="rtl"><span class="s2">נגישות פנימית בעיר:</span><span class="s1"> מיקום אבני חן יחסית מרכזי בתוך מודיעין – היא סמוכה לצירי רוחב כמו עמק זבולון וחשמונאים שמובילים למרכז העיר (עירייה, קניון, היכל התרבות) תוך דקות. מורשת ממוקמת מעט מערבית יותר – למעשה </span><span class="s2">מעבר לנחל ענבה</span><span class="s1"> – אך חיבור הכבישים החדש דרך שדרות ענבה וצומת נופים-יהודה המכבי יצר </span><span class="s2">רצף תחבורתי חלק</span><span class="s1"> יחסית בין מורשת/נופים לבין אבני חן ושאר חלקי העיר </span><span class="s1">. כלומר, תושבי מורשת יכולים לנסוע דרך יהודה המכבי לתוך אבני חן ומשם להמשיך לכל יעד בעיר (או לכיוון כביש 443 בצפון).</span></p>
<p class="p1" dir="rtl"><span class="s1">בשורה התחתונה, עבור בעלי רכב אין הבדל מהותי: </span><span class="s2">שתי השכונות מחוברות היטב לכבישים מהירים</span><span class="s1"> (בעיקר 431) ומאפשרות יציאה חלקה מהעיר. עבור המשתמשים בתחבורה ציבורית – שתיהן מציעות נגישות טובה לרכבת ולאוטובוסים, כאשר ייתכן שבאבני חן הוותיקה הפריסה מעט יותר נוחה כרגע, ובמורשת יש </span><span class="s2">פוטנציאל לשיפור נוסף</span><span class="s1"> ככל שיגדל הביקוש. יתרון קל למורשת הוא הקירבה למחלף ולרכבת פאתי מודיעין – נסיעה ישירה קצרה ללא מעבר בתוך שכונות אחרות. מנגד, יתרון לאבני חן הוא הקרבה למרכז העיר – ביקור בקניון, בבנק, בקופ”ח מרכזית או בבילוי ערב, כנראה שיהיה קצר וקל יותר לתושב אבני חן מאשר לתושב מורשת, שיצטרך לגמוע מרחק רב יותר (אם כי עדיין קצר במונחים ארציים).</span></p>

<h2><span class="s1">תכנון עתידי ופיתוח עירוני</span></h2>
<p class="p1" dir="rtl"><span class="s1">מודיעין כעיר מתוכננת ממשיכה לגדול, ושתי השכונות קשורות לתוכניות העתיד של העיר.</span></p>
<p class="p1" dir="rtl"><span class="s2">התפתחות עתידית במורשת:</span><span class="s1"> שכונת מורשת </span><span class="s5">עצמה</span><span class="s1"> עדיין בתנופת בנייה: בשנים 2025–2026 צפויים להתאכלס הפרויקטים האחרונים בשכונה (שבחלקם נמצאים כעת בבנייה פעילה). בכך יושלם מלאי כל 4,200 יחידות הדיור, ומורשת תהפוך לשכונה הגדולה בעיר. יחד עם הבנייה למגורים, יושלמו גם מוסדות הציבור שתוכננו – בתי ספר הנוספים, גני הילדים, מרכזי המסחר (כמו פורום מורשת שהוזכר), הקונסרבטוריון העירוני, וקופות החולים ומרכזי השירות המקומיים </span> <span class="s1">. למעשה, חזון מורשת הוא להוות </span><span class="s2">“מרכז משנה”</span><span class="s1"> במערב מודיעין, עם מערך שירותים עצמאי לתושביה, כדי להפחית את הצורך להגיע למרכז העיר הישן. לאחר שיסתיים אכלוס השכונה, היא צפויה לאכלס כ-15–16 אלף תושבים (בדומה בגודל לשכונת משואה/כרמים למשל). בנוסף, צפויה להתחיל במהלך השנים הקרובות התוכנית לשכונה הבאה של מודיעין מערב – לעת עתה מכונה </span><span class="s5">שלב ב’</span><span class="s1"> (לעיתים מוזכר כמתחם “משואה מערב” או שם אחר). רחוב עמק חפר, העובר בקצה הצפוני של מורשת, עתיד להתחבר בעתיד לשכונה נוספת שייבנו מצפון-מערב למורשת </span><span class="s1">. המשמעות: מורשת, שבה עובר כבר כעת הרחוב המרכזי (השדרה) וציר עמק חפר, תהפוך לחוליה מקשרת בין חלקי העיר המערביים הישנים (אבני חן, נופים) לבין השכונות החדשות העתידיות. יתכן ובעתיד יקום גם אזור תעסוקה חדש או רובע עסקים מערבי (תוכנית המתאר החדשה של מודיעין מדברת על רובע עסקים נוסף בעיר עד 2040) </span><span class="s1">, מה שעשוי להיות ממוקם בקרבת השכונות המערביות. כל אלה מציבים את מורשת בעמדה מעניינת לקראת העתיד – שדרה מרכזית, חיבור לשכונות עתיד, ומוקדי מסחר ותרבות שבתכנון.</span></p>
<p class="p1" dir="rtl"><span class="s2">התפתחות באבני חן:</span><span class="s1"> בהיותה שכונה ותיקה שכבר בנויה במלואה, לא צפויים שינויים דרמטיים במרקם הבנוי של אבני חן בטווח הקרוב. רוב המגרשים הפרטיים כבר מאוכלסים, ואין כרגע פרויקטי פינוי-בינוי יזומים בשכונה (מה שעשוי לקרות אולי בעוד עשור או שניים, כאשר הבניינים יזדקנו משמעותית, אך טרם בשל כעת). יחד עם זאת, אבני חן תיהנה </span><span class="s5">בעקיפין</span><span class="s1"> מהרבה פיתוח סביבתי: פתיחת מרכזי המסחר והתרבות במורשת הסמוכה תוסיף שירותים במרחק הליכה; שיפור תשתיות התחבורה (כגון כבישים ורמפות חדשות) כבר מקל על העומסים כפי שהוסבר; ואם אכן יוקם רובע עסקים חדש במערב העיר, סביר שגם תושבי אבני חן ייהנו מקרבה למקומות תעסוקה חדשים. עיריית מודיעין גם משקיעה בהמשך תחזוקת וחידוש המרחבים הציבוריים בשכונות הוותיקות – גינות ציבוריות משודרגות, שבילי אופניים חדשים (למשל, תכנון שבילי אופניים לאורך עמק זבולון וחשמונאים שיחברו את מערב העיר למרכזה </span><span class="s1">), ויוזמות קהילתיות לרווחת התושבים. בשנים הקרובות מודיעין כולה צפויה לגדול משמעותית – אושרה תכנית מתאר להוספת כ-39,000 יח”ד בעיר בעשורים הבאים </span><span class="s1">. חלק הארי של גידול זה יקרה בשכונות חדשות (דוגמת מורשת, קייזר דרום, שלב ב’ וכו’), אבל השכונות הוותיקות כמו אבני חן ישמשו כמרכזי עירוניות חשובים בלב העיר המורחבת.</span></p>
<p class="p1" dir="rtl"><span class="s1">מבחינת </span><span class="s2">השקעה ציבורית</span><span class="s1">, יתכן שעיריית מודיעין תפנה תקציבים בשנים הבאות לחידוש מבני ציבור ישנים באבני חן, או לבניית מתקנים נוספים במידה והאוכלוסייה בה תגדל שוב (למשל, אם זוגות צעירים יקנו דירות ממצמצמי דיור ויכניסו שוב ילדים קטנים לשכונה – יעלה צורך בחידוש גני ילדים וכו’). כבר עכשיו, אבני חן משמשת כעוגן עבור השכונות החדשות: </span><span class="s2">בתי הספר הוותיקים שלה קליטו תלמידים משכונת נופים ומורשת</span><span class="s1"> באופן זמני עד לפתיחת בתי ספר חדשים, ולכן שודרגו תשתיות התנועה בין השכונות (לדוגמה, הרחבת הכביש ליהודה המכבי כאמור, כדי לאפשר זרימת רכבים טובה בבוקר לבתי הספר באבני חן) </span><span class="s1">. שיתוף הפעולה האורבני הזה בין חדש לוותיק צפוי להימשך, ובשאיפה ימשיך לחזק גם את אבני חן וגם את מורשת כחטיבה קהילתית-עירונית אחת.</span></p>
<p class="p1" dir="rtl"><span class="s1">במבט כולל, </span><span class="s2">מורשת היא שכונה העתירה בפיתוח עתידי</span><span class="s1"> – עוד מוסדות, עוד תושבים, עוד חיבורים – מה שמבטיח שהתחדשותה לא תיעצר בקרוב. </span><span class="s2">אבני חן נהנית מיציבות</span><span class="s1"> – בלי הפתעות גדולות באופק, מלבד אימוץ השדרוגים שמגיעים מסביב.</span></p>

<h2><span class="s1">יתרונות וחסרונות עיקריים – ראש בראש</span></h2>
<p class="p1" dir="rtl"><span class="s1">לכל אחת מהשכונות יש נקודות חוזקה ונקודות חלשות יחסית, בהתאם לאופיה. ננסה לתמצת את </span><span class="s2">היתרונות והחסרונות המרכזיים</span><span class="s1"> של מורשת מול אבני חן:</span></p>
<p class="p1" dir="rtl"><span class="s2">שכונת מורשת – יתרונות:</span></p>

<ul>
 	<li>
<p class="p1" dir="rtl"><span class="s1">דיור חדש ומודרני:</span><span class="s2"> דירות חדשות עם מפרט עדכני, בניינים חדישים, יותר מעליות, חניות תת-קרקעיות ומרפסות גדולות. מתאים למי שאוהב חדש ולא רוצה שיפוצים.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">מחירים אטרקטיביים (יחסית):</span><span class="s2"> בעקבות ריבוי ההיצע, ניתן למצוא במורשת דירות במחיר מעט נמוך יותר מדירות דומות בשכונות הוותיקות, במיוחד דירות 3–4 חדרים יד שנייה ממחיר למשתכן </span><span class="s2">. יש יותר אפשרות למיקוח ותחרות בין מוכרים.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">תכנון אורבני מתקדם:</span><span class="s2"> רחובות עם שבילי אופניים, שטחים ירוקים משולבים, שדרה מרכזית נעימה עם מסחר ופנאי </span><span class="s2">. השכונה תוכננה לחיי קהילה מודרניים עם עירוב שימושים – חנויות, קופות חולים, גני ילדים ובתי ספר במרחק הליכה </span><span class="s2">.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">נגישות מעולה לכבישים:</span><span class="s2"> קרבה ישירה למחלף עינב (431) ותחנת רכבת פאתי מודיעין – מקצרה את הנסיעה יומיום למי שעובד בגוש דן. יוצאים מהשכונה ותוך 2-3 דקות על האוטוסטרדה.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">קהילה צעירה ודינמית:</span><span class="s2"> הרבה זוגות צעירים, ילדים קטנים, פארקים חדשים – אווירה “של התחלה” ואנרגטית. עבור משפחות בתחילת הדרך זו הזדמנות לגדול יחד עם השכונה וליצור קהילה חדשה.</span></p>
</li>
</ul>
<p class="p1" dir="rtl"><span class="s2">שכונת מורשת – חסרונות:</span></p>

<ul>
 	<li>
<p class="p1" dir="rtl"><span class="s1">אתרי בנייה פעילים:</span><span class="s2"> השכונה עדיין בבנייה בחלקים ממנה – זה אומר רעש, אבק, משאיות עובדות, ולעיתים מפגעי דרך זמניים. המצב ישתפר עם סיום העבודות, אך כיום זה פקטור שיש להביא בחשבון.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">מחסור זמני בחלק מהשירותים:</span><span class="s2"> למרות התקדמות גדולה, עדיין לא כל המוסדות פתוחים – למשל, לא כל בתי הספר מוכנים, לא כל החנויות אוכלסו. חלק מהתושבים מוצאים עצמם נוסעים לאזורים אחרים כדי להשלים סידורים עד שהכל ייפתח במורשת עצמה.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">קהילה בהתהוות:</span><span class="s2"> למי שמעדיף סביבת שכנים ותיקה ומגובשת – במורשת הכול חדש, וייקח זמן עד שהקהילה תתגבש לגמרי. ייתכן שפחות מסורות מקומיות או פורומים קהילתיים בהשוואה לשכונה ותיקה.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">היצע רב בשוק הנדל”ן:</span><span class="s2"> אם אתם מתכננים למכור במורשת בשנים הקרובות – דעו שיש הרבה תחרות מול דירות דומות, מה שעשוי להקשות על מכירה מהירה ולהפחתת מחיר (מנקודת מבט של מוכר זה חיסרון, אם כי לטובת הקונה הפוטנציאלי זה יתרון) </span><span class="s2">.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">העדר בתים פרטיים:</span><span class="s2"> אם תמיד חלמתם על קוטג’ עם גינה – במורשת האופציה הזאת כמעט לא קיימת. הבניה היא רוויה וצפופה יותר.</span></p>
</li>
</ul>
<p class="p1" dir="rtl"><span class="s2">שכונת אבני חן – יתרונות:</span></p>

<ul>
 	<li>
<p class="p1" dir="rtl"><span class="s1">שכונה מבוססת ושקטה:</span><span class="s2"> הרחובות, המבנים והקהילה וותיקים ומנוסים – יש “ותק” שמשרה ביטחון. אין הפתעות גדולות, אתם יודעים בדיוק למה אתם נכנסים.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">גיוון נכסים – מתאים לכולם:</span><span class="s2"> היצע גדול של סוגי דירות – מדירות קטנות לזוג מבוגר ועד קוטג’ למשפחה גדולה. ניתן לשדרג דיור בתוך השכונה בקלות יחסית (לעבור מדירה לבית וכו’).</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">מוסדות חינוך וקהילה איכותיים:</span><span class="s2"> בתי ספר מצוינים עם מוניטין, תשתית חינוך בלתי-פורמלי (נוער, חוגים) פעילות שנים, ובתי כנסת ומרכזי קהילה פעילים. למשפחה דתית-לאומית, למשל, יש קהילה קיימת להשתלב בה מיד </span><span class="s2">.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">קרבה לפארק ענבה ולטבע:</span><span class="s2"> גישה רגלית לפארק ענבה הגדול – אגם, מדשאות, אמפיתאטרון – בילוי מצוין למשפחות. בנוסף, אתרי טבע כמו גבעת ברפיליה ממש ליד. זהו יתרון באיכות החיים שקשה לכמת.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">מיקום ונגישות במרקם העירוני:</span><span class="s2"> אבני חן קרובה יותר ללב העיר – נסיעה קצרה לקניון, לעירייה, לתחנת רכבת מודיעין מרכז. גם בתוך השכונה עצמה יש כמה מרכזי מסחר נגישים. מי שמעדיף להיות “במרכז העניינים” של מודיעין – המיקום של אבני חן מתאים.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">יציבות ערך הנדל”ן:</span><span class="s2"> הביקוש לשכונה נשאר יציב לאורך השנים. נכסים מבוקשים נמכרים מהר ובמחירים טובים </span> <span class="s2">, כך שהשקעה בנדל”ן באבני חן נחשבת בטוחה עם סיכון נמוך לירידת ערך.</span></p>
</li>
</ul>
<p class="p1" dir="rtl"><span class="s2">שכונת אבני חן – חסרונות:</span></p>

<ul>
 	<li>
<p class="p1" dir="rtl"><span class="s1">נכסים ישנים יותר:</span><span class="s2"> דירות רבות בני 15–20 שנה, עם תכנון ישן יותר – למשל, לעיתים ללא ממ”ד (בבתים הראשונים), מעליות רק בבניינים החדשים, חניות פתוחות ולעיתים מחסור במחסן. ייתכן צורך לבצע שיפוצים בדירות יד שנייה כדי להביאן לסטנדרט עדכני.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">מחירים גבוהים לנכסים ייחודיים:</span><span class="s2"> למרות היציבות, העלויות בשכונה אינן נמוכות – במיוחד בתים צמודי קרקע שהפכו מאוד יקרים (5 מיליון ש”ח ומעלה). גם דירות 4–5 חדרים גדולות בבניינים המבוקשים עשויות לעלות יותר מאשר נכס חדש במורשת בגודל דומה.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">העדר התחדשות וחדשנות:</span><span class="s2"> בשכונה ותיקה, קצב החידושים איטי – אין “ריגושים” של פתיחת מרכז חדש או אירועי השקה כמו בשכונה חדשה. התושבים מקבלים פחות תשומת לב עירונית (שבד”כ הולכת לשכונות החדשות).</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">רחובות צפופים יותר לרכב:</span><span class="s2"> תכנון הרחובות מלפני 20 שנה אומר רחובות צרים יותר, פחות חניות מכלי רכב למשפחה (אז הייתה רק מכונית אחת, היום לכל משפחה 2), מה שלעיתים מורגש בשעות העומס.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">פחות מותאם לאופניים ולהולכי רגל:</span><span class="s2"> המדרכות והמעברים באבני חן תוכננו בדור קודם – אין רשת שבילי אופניים בשכונה, ומעט מאוד שבילים להולכי רגל המופרדים מתנועת כלי רכב (למעט טיילת ענבה בקצוות). למי שמעריך מאוד חיים “ירוקים” בלי רכב – ייתכן שימצא תכנון מודרני כמו במורשת כנוח יותר.</span></p>
</li>
</ul>
<p class="p1" dir="rtl"><span class="s1">כמובן, רשימות אלו אינן ממצות כל פרט, אך הן נותנות תמונה תמציתית של אופי השכונות. לסיכום קצר: </span><span class="s2">מורשת</span><span class="s1"> – חדשנות, דינמיות, צמיחה לצד אתגרי הקמה; </span><span class="s2">אבני חן</span><span class="s1"> – ותק, יציבות, קהילתיות מבוססת לצד מגבלות הגיל.</span></p>

<h2><span class="s1">מסקנות והמלצות: איזו שכונה מתאימה לכם?</span></h2>
<p class="p1" dir="rtl"><span class="s1">לאחר שסקרנו בהרחבה את המאפיינים של מורשת ואבני חן, ננסה לתרגם את הנתונים וההבדלים להמלצות פרקטיות לפי קהלי יעד שונים:</span></p>

<ul>
 	<li>
<p class="p1" dir="rtl"><span class="s1">זוגות צעירים ורוכשי דירה ראשונה:</span><span class="s2"> עבור מי שנכנסים לשוק הדיור במודיעין, לשכונת </span><span class="s1">מורשת</span><span class="s2"> יש הצעה מפתה – דירות חדשות לחלוטין, חלקן עדיין נמכרות מקבלן או מיד ראשונה, במחירים נמוכים במעט מאלה שבשכונות הוותיקות. האוכלוסייה הצעירה והילדים הרבים בשכונה יוצרים סביבה טבעית לצעירים להתחבר ולהקים קהילה. יתרון גדול הוא האפשרות לקנות דירה חדשה עם כל המתקנים המודרניים, מבלי להתעסק בשיפוצים. גם מבחינת השקעה עתידית, סביר שערך הדירות במורשת יעלה עם התבססות השכונה (לאחר תקופת ההתייצבות הנוכחית) – כך שזו כניסה נבונה. זוג צעיר יהנה גם מהקרבה לרכבת 431 (במיוחד אם עובדים מחוץ למודיעין). מנגד, </span><span class="s1">אם</span><span class="s2"> זוג צעיר מעדיף סביבה שקטה יותר ופחות “אתר בנייה”, והוא מוכן לקנות דירה יד שנייה משופצת – אבני חן יכולה להיות אופציה, אך התקציב כנראה יידרש להיות גבוה יותר עבור דירה דומה. לזוגות ללא ילדים ייתכן שהחיים בשכונה ותיקה יהיו מעט רגועים ונעימים, אך רוב הצעירים יימשכו למורשת בשל החדשנות, החברים בני גילם, ואפילו בזכות תוכניות הדיור המוזלות שהיו בה.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">משפרי דיור (משפחות מודיעין המבקשות להתרחב):</span><span class="s2"> קהל זה לעיתים קרובות כבר גר בדירה קטנה בעיר ורוצה לעבור לבית גדול יותר או לדירה מרווחת. עבורם, הבחירה תלויה בצרכים: אם המשפחה חולמת על בית עם חצר, על מרחב גדול ופרטי – </span><span class="s1">שכונת אבני חן</span><span class="s2"> תעמוד בחזית ההמלצות. בשכונה הוותיקה יש כאמור מבחר קוטג’ים, דו-משפחתיים ודירות גן גדולות היכולות להתאים למשפחה שמחפשת שדרוג משמעותי באיכות הדיור. גם קרבת מוסדות החינוך והפנאי שכבר פועלים מזמן מהווה יתרון – ילדים גדולים יותר יכולים מיד להשתלב בבתי ספר מבוססים או בתנועות נוער פעילות. אם המשפחה דתית, הקהילה הדתית-לאומית באבני חן חזקה ובעלת מוסדות (בתי כנסת, סניפי בני עקיבא וכו’) – מה שיהווה שיקול מכריע. לעומת זאת, </span><span class="s1">אם</span><span class="s2"> משפרי הדיור דווקא מעוניינים לשדרג לדירת קומה חדשה וגדולה (נניח מעבר מדירת 3 חד’ לדירת 5 חד’ מפוארת) – מורשת מציעה דירות 5–6 חדרים חדישות, עם מעלית וממ”ד, שיכולות להתאים בלי התעסקות של בית קרקע. משפחות שחשובה להן סביבה של משפחות צעירות אחרות (למשל, עבור ילדיהם הקטנים) – יימשכו אולי גם הן למורשת, שם יפגשו הרבה הורים וילדים באותו מצב. בסופו של דבר, עבור משפרי דיור, </span><span class="s1">אבני חן מומלצת אם היעד הוא בית גדול וקהילה ותיקה</span><span class="s2">, ו</span><span class="s1">מורשת מומלצת אם היעד הוא דירה מודרנית מרווחת וקהילה צעירה בצמיחה</span><span class="s2">.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">משקיעים בנדל”ן:</span><span class="s2"> מי שמחפש נכס במודיעין לצורכי השקעה והשכרה, צריך לשקול פרמטרים של תשואה, סחירות עתידית ושוכרים פוטנציאליים. כאן התמונה מורכבת: מצד אחד, </span><span class="s1">שיעור התשואה</span><span class="s2"> בשתי השכונות דומה יחסית (סביב 2.5%–3% בשנה, כמו במודיעין הכללית, תלוי בסוג הנכס) – לא אזור של תשואות גבוהות במיוחד. במורשת, היצע השכירויות גדול מאוד (הרבה דירות מושכרות על ידי זוכי מחיר למשתכן או משקיעים שקנו על הנייר), ולכן ייתכן שלמשקיע חדש יהיה יותר תחרות למציאת שוכר, מה שעלול ללחוץ את שכר הדירה כלפי מטה. באבני חן ההיצע להשכרה קטן יותר, אך גם הביקוש מעט יותר סלקטיבי (משפחות מבוססות שלרוב קונות ולא שוכרות). </span><span class="s1">משקיע לטווח קצר</span><span class="s2"> שמחפש עליית ערך מהירה אולי יעדיף נכס במורשת – במחיר אטרקטיבי כעת, מתוך ציפייה שכעבור 5–7 שנים, כשהשכונה תהפוך למבוקשת ומלאה, מחירו יעלה משמעותית. במיוחד אם מדובר בדירת 3–4 חדרים שנקנתה במחיר למשתכן – פוטנציאל הרווח בהון גבוה (ואכן רבים מנסים למכור ולממש רווח כזה כבר כעת) </span><span class="s2">. </span><span class="s1">משקיע לטווח ארוך ופרופיל סולידי</span><span class="s2"> עשוי דווקא להעדיף דירה באבני חן – אזור מבוקש שלעולם לא חסרים בו מתעניינים, עם יציבות במחיר וצפי לעלייה מתונה לאורך שנים. שוכרים באבני חן עשויים להיות משפחות מבוססות שמחכות לבית לקנייה, או משלחות רילוקיישן וכד’, לעומת השוכרים במורשת שיהיו כנראה זוגות צעירים וסטנדרט השכירות בהתאם. אפשרות מעניינת נוספת: השקעה </span><span class="s1">בפורום מורשת</span><span class="s2"> – רכישת משרד או חנות במרכז החדש (אם וכאשר יוצעו למכירה), דבר שיכול להניב תשואה יפה מהשכרה לבעלי עסקים, אבל זה כמובן שוק שונה מהשכרה למגורים. בשורה התחתונה, שני הלוקיישנים טובים להשקעה בנדל”ן למגורים, אך יש לזכור שבמורשת מחיר הקנייה עשוי להיות נמוך יותר כרגע והסיכון מעט גבוה יותר (עקב התחרות), ואילו באבני חן המחיר גבוה יותר אך השוק יציב ומוכח.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">תושבים ותיקים/גמלאים:</span><span class="s2"> אמנם לא צוינו במפורש בקהל היעד, אך כדאי להזכיר נקודה זו. עבור זוג מבוגר שמחפש דיור נוח במודיעין – לדוגמה דירה עם מעלית, קרוב לשירותים רפואיים ומרכז מסחרי, ועם סביבה שקטה – לשתי השכונות יש מה להציע. </span><span class="s1">אבני חן</span><span class="s2"> מציעה שקט וקרבה לכל מה שצריך (קניון, פארק לטיול, קהילה מבוססת), אך רבים מהבניינים הישנים בה חסרי מעלית וזה אתגר למבוגר. </span><span class="s1">מורשת</span><span class="s2">, לעומת זאת, כל בנייניה חדשים עם מעליות ונגישות, והמרחק לרכב או לחנות הפארם הקרובה קצר מאוד בשל תכנון נכון. המוני ילדים קטנים במורשת אולי יוצרים סביבה פחות שלווה לפנסיונר, אך מצד שני יש גם לא מעט צעירים שמשכירים שם – ואולי בעתיד ייפתחו במורשת מוסדות שמתאימים גם לאזרחים ותיקים (כגון מרכז קהילתי עם פעילויות יום לגמלאים). ייתכן שאוכלוסייה ותיקה מהמגזר הדתי, למשל, תרגיש יותר בנוח באבני חן בשל מוסדות ותיקים וקהילה דתית מבוססת בה.</span></p>
</li>
</ul>
<p class="p1" dir="rtl"><span class="s2">לסיכום</span><span class="s1">, ההחלטה בין מורשת לאבני חן תלויה בהעדפות האישיות ובצרכים הייחודיים שלכם:</span></p>

<ul>
 	<li>
<p class="p1" dir="rtl"><span class="s1">אם אתם </span><span class="s2">אוהבים חדשנות, רוצים דירה מודרנית ומתכננים את העתיד קדימה</span><span class="s1"> – מורשת מזמינה אתכם להיות בין מייסדי הפרק החדש של מודיעין. תהנו משכונה בצמיחה, תשתיות חדשות ונוצצות, וקהילה צעירה מלאה באנרגיה. רק קחו בחשבון את שלב ההתבססות שעוד נמשך.</span></p>
</li>
 	<li>
<p class="p1" dir="rtl"><span class="s1">אם אתם </span><span class="s2">מעריכים יציבות, סביבת חיים ותיקה ומוכחת, ושואפים לבית עם אופי וגינה</span><span class="s1"> – אבני חן תחבק אתכם עם רחובות ירוקים, שכנים ותיקים וטובים, וכל הנוחות של שכונה שהזמן רק היטיב עמה. תהנו מקהילה מגובשת, פארקים ותיקים וקרבה לכל מה שמוכר ואהוב במודיעין.</span></p>
</li>
</ul>
<p class="p1" dir="rtl"><span class="s1">שתי השכונות הן חלק מפניה היפות של מודיעין, וכל אחת מהן מציעה איכות חיים גבוהה בדרכה. ייתכן שבעוד עשור, ההבדלים ביניהן יצטמצמו עוד יותר – מורשת תהפוך ל”ותיקה” יותר, ואבני חן אולי תתחדש בגל צעיר. עד אז, הבחירה בידיכם בהתאם לסדר העדיפויות שלכם. כך או כך, מודיעין ממשיכה להתפתח ולספק לתושביה הזדמנויות מגורים מגוונות – וזה כשלעצמו סימן לעיר בריאה ותוססת. בהצלחה בבחירת ביתכם הבא!</span></p>
<p dir="rtl">קרדיט תמונה אבני חן: אתר עיריית מודיעין</p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/06/מודיעין-הבית-של-כולנו-32-scaled.png', 'published', '2025-06-29 08:46:04') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
