insert into entity_categories (entity_type, entity_id, category_id) values ('article', 'b2c5d698-3f16-57ec-ba0e-a20abb250127', 'e9ccc079-df4e-519b-9885-8b4eba35de06') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('63f3c9c3-dd09-5eda-b786-696c08c499ad', 'פארק ענבה: ליבו הירוק של מודיעין - כל מה שצריך לדעת על הפארק', 'anabe-park-modiin', '<h1><span class="s1">היסטוריה ופיתוח</span></h1>
<p class="p3" dir="rtl"><span class="s2">פארק ענבה הוא הפארק העירוני המרכזי במודיעין-מכבים-רעות, ומהפארקים החכמים הראשונים בישראל</span><span class="s2">. שמו של הפארק נקבע על שם נחל ענבה הזורם בתוכו בחלקו המזרחי. הפארק נפתח לאוכלוסייה באפריל 2010 </span> <span class="s2">, בתכנון של האדריכל גדעון שריג.</span></p>
<p class="p3" dir="rtl"><span class="s2">מאז הורחב הפארק בשלב ב’ שהגיע עד גשר יהודה המכבי, ובתכניות עתידיות שלב ג’ עתיד לכלול פעילויות נוספות - למשל פארק חי, פינות פיקניק, מתקני אתגר ושבילים מורחבים עד לכביש 1</span><span class="s2">.</span></p>
<p class="p3" dir="rtl"><span class="s2">בראשית דרכו נכנסה אפילו מגבלת כניסה לתושבי העיר בלבד בחגים</span><span class="s2">, אך בשנת 2013 בוטלה המגבלה והפארק שוב פתוח לכלל התושבים</span><span class="s2">. כיום הכניסה לפארק חופשית</span><span class="s2">.</span></p>

<h2><span class="s1">מתקנים ואטרקציות</span></h2>
<p class="p1" dir="rtl"><span class="s1">פארק ענבה מציע אטרקציות לכל המשפחה במרחק נגיעה מהעיר. במרכז הפארק נמצא </span><span class="s2">אגם מלאכותי</span><span class="s1"> גדול (כ־14 דונם) שבו משוטטים מאות דגי קרפיון שחור ואמנון כסוף</span><span class="s1">. בעבר היו בו סירות פדלים וקיאקים, המספקים בילוי משפחתי בסגנון ריאה עירונית</span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">מסביב לאגם פרוס מתחם משוכלל של גן שעשועים - ה”</span><span class="s2">גן ההרפתקאות</span><span class="s1">” - הכולל מגלשת חבלים בגובה כ־8 מטרים, מתקן טיפוס אתגרי שלד, שתי אומגות (אחת מותאמת לילדים קטנים) ותוספת של מבוך חבלים, תוך משטחי גומי סינתטי וצל בדקלים ובצלייה</span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">בפארק ניטע </span><span class="s2">בוסתן עצי ארץ-ישראל</span><span class="s1"> (אלונים, זית, שקד וגפן) סביב פרגולה מרכזית </span><span class="s1">, והושמו בו גם פסלי דינוזאורים וחיות גדולות לשעשוע המבקרים. ברחבי השטח פרוסים </span><span class="s2">ספסלי עץ ובטון</span><span class="s1"> ושולחנות פיקניק מוצלים. בנוסף קיימים מדשאות ירוקות פתוחות רחבות ידיים לפעילויות וכדורגל חובבני</span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">תחזוקת המתקנים נעשית על ידי העירייה (כגון ניקיון חודשי וגזיזת דשא), ונמצאים שירותים ציבוריים ומזרקות מים לשימוש המבקרים.</span></p>

<h2><span class="s1">שבילי הליכה וכושר</span></h2>
<p class="p1" dir="rtl"><span class="s1">לפני פארק ענבה שוכנים שבילים ומסלולים המשמשים להליכה, אופניים ורכיבה:</span></p>
<p class="p1" dir="rtl"><span class="s2">שביל המרכזי</span><span class="s1"> המקיף את האגם - באורך כ־3 ק”מ של שבילי בטון רחבים - ואת </span><span class="s2">שביל אנבה</span><span class="s1"> העובר בעמק הנחל לאורך כ־4.5 ק”מ</span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">לאורך השביל מוצבות פינות ישיבה מוצלות, תאורת שבילים ועצי פרי המשמשים מאגרי מים טבעיים לתחזוקת הצמחייה</span><span class="s1">. לצד גינת הכלבים בפארק הוקם </span><span class="s2">מתחם כושר אתגרי</span><span class="s1"> חדשני לבני נוער (מתקני מתח, אימון TRX, טיפוס חבל וחדר כושר טבעי)</span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">באזור הדרומי של הפארק נמצא </span><span class="s2">אמפיתיאטרון פתוח</span><span class="s1"> לכ־1,000 צופים </span><span class="s1">, שבמהלכי הקיץ משמש להופעות מוזיקה, מחזות וסרטי קולנוע תחת כיפת השמיים. הפארק מואר בלילה ואינו נגיש לרכב פרטי בתוך השטחים (למעט חילוץ), אלא רק הולכי רגל ורוכבים.</span></p>
<p class="p1" dir="rtl"><span class="s1">שעות הפעילות הן בימים א’-ה’ 5:00-22:00, ובסופי שבוע עד 21:00 (בעבר הופעלו במקום אמצעים טכנולוגיים מתקדמים כגון Wi-Fi בפארק החכם).</span></p>

<h2><span class="s1">אירועים ופעילויות מיוחדות</span></h2>
<p class="p1" dir="rtl"><span class="s1">בפארק ענבה מתקיים לאורך השנה מגוון אירועים קהילתיים ופסטיבלים חינמיים.</span></p>
<p class="p1" dir="rtl"><span class="s1">בקיץ 2025, למשל, במסגרת “קיץ מודיעיני” הוקרנו סרטים לילדים על מסך ענק בכל יום שלישי בערב</span><span class="s1">. בימי שישי אחר-הצהריים התקיימו מסיבות </span><span class="s2">מזרקות</span><span class="s1"> עם רחבה רטובה ומוזיקה ערבה</span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">בסופי שבוע נערכו מופעי לילה מיוחדים (“לילות ענבה”): ערבי מחווה ללהקת ABBA, קונצרטים של אמנים ישראלים ועוד</span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">בנוסף התקיים בפארק שני סופי שבוע של “קאמפארק” - לינת אוהלים משפחתית עם הופעות חיות, סדנאות וטיולי עששיות לילדים</span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">מעבר לכך מתקיימים במקום מפגשי כושר (יוגה), אימוני ספורט משפחתיים ואירועי בריאות ובילוי (למשל ‘ספורטיביקידס’).</span></p>
<p class="p1" dir="rtl"><span class="s1">העירייה מפעילה גם פעילויות קבועות בחגים ובחופשות, הכוללות סדנאות יצירה לפעוטות, מחול נשים, ושירותי מזנון ומוזיקה חיה. האירועים הללו נמנים בין המועדפים של התושבים, ומחזקים את מעמד הפארק כמרחב קהילתי חשוב בעיר.</span></p>

<h2><span class="s1">חוויות וביקורות תושבים</span></h2>
<p class="p1" dir="rtl"><span class="s1">תושבי מודיעין וביקורות באינטרנט מתארים את פארק ענבה כמקום בילוי נעים במיוחד למשפחות.</span></p>
<p class="p1" dir="rtl"><span class="s1">באתר למטייל נכתב שהוא “</span><span class="s2">פארק יפהפה</span><span class="s1">” עם “אגם קטן וחמוד, הרבה דשא ומתקני שעשועים לילדים”</span><span class="s1">, שהופך אותו למרחב בילוי אידאלי של מספר שעות. עם זאת, מבקרים מציינים גם חסרונות: לדוגמה, אחד מהם ציין כי בפארק כמעט אין צל טבעי, ולכן “חשוב לציין שכדאי להגיע עם כובעים”</span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">משימות ניקיון ותחזוקת דשא הנעשות בפארק זוכות לשביעות רצון גבוהה, והעירייה אף ערכה סקר תושבים (2020) לבחון את שביעות הרצון מתחזוקת הפארק והתאמת הפעילויות בו</span><span class="s1">.</span></p>
<p class="p1" dir="rtl"><span class="s1">באופן כללי מדווחים המבקרים על תחושה של ניקיון ואבטחה (מצלמות ושומרי קבע), ועל יחס חם מצד העירייה (פתיחת השירותים והפעלות הקיץ).</span></p>
<p class="p1" dir="rtl"><span class="s2">פארק ענבה</span><span class="s1"> נתפס כראיה ירוקה במרכז העיר - אטרקציה המושכת גם מבקרים מהסביבה - וכמרחב מפגש קהילתי שבו מתקיימות פעילויות לכל הגילאים.</span></p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/07/WhatsApp-Image-2025-07-15-at-13.46.55.jpeg', 'published', '2025-07-15 11:34:18') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '63f3c9c3-dd09-5eda-b786-696c08c499ad', 'e9ccc079-df4e-519b-9885-8b4eba35de06') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('53d0f9c5-817e-5832-8773-efa316549243', 'מצב שוק הדיור בשכונת מורשת, מודיעין.', 'moreshet-prices', '<p class="p1" dir="rtl"><span class="s1">שכונת מורשת שבמערב מודיעין היא פרויקט נדל”ן חדש במתכונת עדכנית, המתוכנן על שטח של כ־1,600 דונם וכ־4,300 יחידות דיור </span><span class="s1">. כ־70% מהדירות (כ־3,000 יח”ד) הוצעו במסגרת תוכנית “מחיר למשתכן” בשנים 2017–2020 </span><span class="s1">. מוסדות חינוך, גנים ופארקים כבר נבנו בשכונה, מה שהפך אותה לאטרקטיבית למשפחות. בחודשים האחרונים החלה אכלוס מסביבת היזם דונה, שבונה כ־2,100 דירות בשכונה </span><span class="s1">.</span></p>

<h2><span class="s1">מגמות מחירי הרכישה</span></h2>
<p class="p1" dir="rtl"><span class="s1">במשך שנים ראשונות מאז האכלוס עלו המחירים במורשת בפעם מפתיעה: דירת ארבעה חדרים ממוצעת, שנמכרה בתחילת הדרך ב־1.2–1.25 מיליון ₪, קפצה לערך של כ־2.7 מיליון ₪ עד 2021, ולשיא של כ־3.4 מיליון ₪ ב־2023 </span><span class="s1">. עם זאת, בשנה־שנתיים האחרונות נרשמה מגמה הפוכה. דווח על ירידה של כ־10%–15% במחירי הדירות היד שנייה במורשת </span><span class="s1">, ככל הנראה בעקבות עליית ההיצע מן הזוכים בתוכנית שהתמחור נגמר. עם זאת, בניתוח אחרון של חברת המחקר מדיה נדל”ן נמצא כי המצב עדיין מעורב: המחיר הממוצע של דירת 4 חדרים חדשה עומד כיום על כ־3.2 מיליון ₪ (עלייה של כ־9% לעומת התקופה הקודמת) </span><span class="s1">, ואילו נתוני yad2 מצביעים על יציבות יחסית במחירי יד שנייה (עלייה של כ־2% למחיר המבוקש של דירת 4 חדרים וירידה של כ־6% ב־5 חדרים) </span><span class="s1">. במילים אחרות, למרות התעוררות ההיצע המהיר, “קיימת מודעות להיצע נוסף” ולכן המוכרים אמנם מתגמשים, אך עדיין לא הורידו את המחירים בצורה דרמטית.</span></p>
<p class="p1" dir="rtl"><span class="s1">טבלה 1. מחירי קנייה ממוצעים לפי מספר חדרים במורשת (בערכים משוערים)</span></p>
<p dir="rtl"><img class="alignnone size-medium wp-image-5719" src="https://www.modiin4u.co.il/wp-content/uploads/2025/07/WhatsApp-Image-2025-07-15-at-14.00.17-300x138.jpeg" alt="" width="300" height="138" /></p>
<p class="p1" dir="rtl"><span class="s1">טבלה זו מבוססת על מודעות יד שנייה עדכניות: למשל, דירת 3 חדרים בגודל 80 מ”ר מוצעת כיום ב־2.85 מיליון ₪ </span><span class="s1"> (35.6 אלף ₪/מ”ר), דירת 4 חדרים של 119 מ”ר בכ־3.35 מיליון ₪ </span><span class="s1"> (כ־28.1 אלף ₪/מ”ר) ודירת 5 חדרים של 140 מ”ר בכ־3.8 מיליון ₪ </span><span class="s1"> (כ־27.1 אלף ₪/מ”ר). אלה עומדים בקנה אחד עם מחירי השיא הבלתי נשכחים – אך נושא הסנטימנט מעיד שעתודות ההיצע גורמות לרוכשים להתמקחות.</span></p>

<h2><span class="s1">מחירי השכרה</span></h2>
<p class="p1" dir="rtl"><span class="s1">גם שוק ההשכרה במורשת מתאפיין במחירים גבוהים. מבדיקת מודעות יד2 עולה כי דירת 4 חדרים טיפוסית (כ־90 מ”ר) מוצעת להשכרה בסביבות 4,650 ₪ לחודש </span><span class="s1">, בעוד דירת 3 חדרים (70–85 מ”ר) נעה בין כ־3,980 ל־4,500 ₪ </span> <span class="s1">. בטבלה שלהלן סוכמו הטווחים האופייניים.</span></p>
<p class="p1" dir="rtl"><span class="s1">טבלה 2. שכר דירה חודשי ממוצע לפי מספר חדרים במורשת</span></p>
<p dir="rtl"><img class="alignnone size-medium wp-image-5720" src="https://www.modiin4u.co.il/wp-content/uploads/2025/07/WhatsApp-Image-2025-07-15-at-14.01.52-300x99.jpeg" alt="" width="300" height="99" /></p>
<p class="p1" dir="rtl"><span class="s1">רוב הדירות המוצעות להשכרה הן דירות חדשות יחסית; לדוגמה, אחת המודעות מציעה 3 חדרים בשטח 70 מ”ר ב־3,980 ₪ </span><span class="s1"> (כ־56 ₪/מ”ר). כמו כן קיימות יחידות גן ופנטהאוזים גדולים יותר, הנמכרות גם ב־7–12 אלף ₪ (למשל בית פרטי 550 מ”ר ב־12,000 ₪ </span><span class="s1">), אך אלו נדירים יחסית.</span></p>

<h2><span class="s1">תחושות התושבים</span></h2>
<p class="p1" dir="rtl"><span class="s1">בקהילות מקומיות ובקבוצות פייסבוק של מורשת ניכרת תסכול גובר בקרב התושבים. רבים מציינים כי המחירים הגבוהים והביקוש הכבד מקשים על מציאת דירה. חלק מהזוכים בהגרלות “מחיר למשתכן” אף התלוננו כי גודל הדירות (במיוחד דירות גן ופנטהאוזים) הפך עבורם לבלתי ניתן למימון, מה שהוביל לביטולי עסקאות והחזרת דירות לשוק החופשי </span><span class="s1">. במילים שלהם, ההצעה העצומה של דירות חדשות “מתנפחת” בשוק השכירות, ואילו המתחרים על דירות יד-שנייה נאלצים “להתפשר” במקצת. התחושות בשטח משקפות את הנתונים: בעוד ביקוש עז לדירות קטנות-בינוניות, מציעי הדירות הגדולות מתקשים יותר.</span></p>

<h2><span class="s1">סיכום</span></h2>
<p class="p1" dir="rtl"><span class="s1">לסיכום, שוק הדיור במורשת ממחיש את הדינמיקה המורכבת שהשתלטה על שוק הדיור המקומי: אחרי גל עליות אדיר בעליית הביקושים לדירות חדשות, מתחילת 2024 ועד היום נרשמות סימני תיקון קל במחירים </span><span class="s1">. מחירי הקנייה הגבוהים עדיין עומדים על עשרות אלפי שקלים למ”ר </span> <span class="s1">, והשכרה של דירות 3–4 חדרים זינקה למחירים של קרוב ל־4,500₪–5,000₪ </span> <span class="s1">. יחד עם זאת, הרוכשים והשוכרים במורשת נאלצים להסתגל לתחרות העזה: המחיר העתידי של דירות חדשות ומושכרות ימשיך ככל הנראה להיות גבוה, אך כוחות השוק בעדינות מתאזנים בין ההיצע העצום של זוכים בתוכנית לבין הפוטנציאל הגובר של שוק יד-שנייה ומחירי השכרה.</span></p>
<p class="p1" dir="rtl"><span class="s4">מקורות:</span><span class="s1"> נתונים מדו”ח יד2 וידאטה לגבי מחירי דירות חדשות ומשומשות במודיעין </span> <span class="s1">; נתוני יד2 לגבי הצעות שכר דירה </span> <span class="s1">; דיווח ב-‘גלובס’ ו-‘ביזפורטל’ על מגמות המחירים במורשת </span></p>
<p dir="rtl"></p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/06/IMG-20250529-WA0339.jpg', 'published', '2025-07-15 11:03:18') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
