insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('7d07c1dc-86a7-52bb-be26-2009ed3687fd', 'מודיעין נותרה בחוץ: היכן נעלמה העיר מהגרלת דירה בהנחה האחרונה?', 'modiin-news-213', 'תושבי מודיעין הצעירים שחולמים על דירה בעיר, ודאי עקבו בדריכות אחר פרסומי הגרלת "דירה בהנחה" האחרונה. כשהתוצאות התפרסמו, בלטה היעדרותה של מודיעין מהרשימה הארוכה של יישובים שבהם הוגרלו דירות. מדוע עיר מבוקשת כל כך, שבה יש ביקוש אדיר למגורים, אינה מופיעה בהגרלות האחרונות?
