insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('a9211141-c672-5f46-ac8b-fd94db029e8a', 'צעד נוסף בביטחון העיר: סיירת אופנועים חדשה במודיעין תגיב במהירות לאירועי חירום', 'modiin-news-221', '<div id="chat-history" class="chat-history-scroll-container">
<div id="15c051406e16b7be" class="conversation-container message-actions-hover-boundary ng-star-inserted">
<div class="response-container ng-tns-c2751589068-63 response-container-with-gpi ng-star-inserted response-container-has-multiple-responses">
