insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('40ef60d8-eb4e-5a44-90cd-1e8a65e250b0', '"כמו משפחה": האורח המיוחד שהפתיע באירוע של עולים מצרפת, והתמונה שריגשה את כולם', 'modiin-news-244', '<div id="chat-history" class="chat-history-scroll-container">
