insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('89afc6ef-cb1a-5f87-a246-d37de43e6c36', 'חורף צבעוני במודיעין: 50 אלף פרחים חדשים נשתלים ברחבי העיר', 'modiin-news-319', '<p data-path-to-node="1"><b data-path-to-node="1" data-index-in-node="0">מבצע השתילה הענק יצא לדרך: אגף גנים ונוף החל בחידוש פני העיר עם עשרות אלפי פרחים עונתיים שיקשטו את הכיכרות והשכונות בשלושת השבועות הקרובים. בין הסוגים שנבחרו: פטוניות, לובליה וסלסלי כסף.</b></p>
<p data-path-to-node="2">תושבי מודיעין מכבים רעות הולכים לראות בקרוב הרבה יותר צבע בעיניים. עיריית מודיעין, באמצעות אגף גנים ונוף, החלה בימים אלה במבצע נרחב לשתילת כ-50 אלף פרחים עונתיים. מדובר במהלך שנועד לרענן את חזות העיר ולהכין אותה למראה חורפי ומלבלב בכיכרות, בצירים המרכזיים ובתוך השכונות.</p>

<h3 data-path-to-node="3"><img class="alignnone size-medium wp-image-6392" src="https://www.modiin4u.co.il/wp-content/uploads/2025/12/IMG-20251218-WA0009-225x300.jpg" alt="" width="225" height="300" /></h3>
<h3 data-path-to-node="3">ההכנות הושלמו: שלושה שבועות של שתילה</h3>
<p data-path-to-node="4">לפני תחילת השתילה עצמה, ביצעו צוותי הגינון הכנות תשתית מקיפות ברחבי העיר. העבודות כללו תיחוח של הקרקע, יישור צינורות השקיה והכנת התשתיות המיועדות לקלוט את הכמות האדירה של השתילים החדשים. על פי התכנון, עבודות השתילה יימשכו לאורך שלושת השבועות הקרובים עד להשלמת פריסת הפרחים בכל המוקדים בעיר.</p>

<h3 data-path-to-node="5"><img class="alignnone size-medium wp-image-6391" src="https://www.modiin4u.co.il/wp-content/uploads/2025/12/IMG-20251218-WA0008-225x300.jpg" alt="" width="225" height="300" /></h3>
<h3 data-path-to-node="5">מה נשתל? הכירו את פרחי החורף החדשים</h3>
<p data-path-to-node="6">הבחירה בסוגי הפרחים אינה מקרית. האגף בחר זנים עמידים שמתאימים במיוחד למזג האוויר המקומי בעונת החורף, ומסוגלים להעניק פריחה עשירה וצבעונית לאורך זמן. בין הפרחים הבולטים שתוכלו לזהות בקרוב בכיכרות:</p>

<ul data-path-to-node="7">
 	<li>
<p data-path-to-node="7,0,0"><b data-path-to-node="7,0,0" data-index-in-node="0">פטוניה גדולת פרחים:</b> ידועה בצבעיה העזים ובנוכחות המרשימה שלה.</p>
</li>
 	<li>
<p data-path-to-node="7,1,0"><b data-path-to-node="7,1,0" data-index-in-node="0">לובליה:</b> מוסיפה גוונים כחולים וסגולים עמוקים.</p>
</li>
 	<li>
<p data-path-to-node="7,2,0"><b data-path-to-node="7,2,0" data-index-in-node="0">סלסלי כסף:</b> מעניקים מראה עדין וריחני בלבן.</p>
</li>
 	<li>
<p data-path-to-node="7,3,0"><b data-path-to-node="7,3,0" data-index-in-node="0">כרובית נוי:</b> מוסיפה טקסטורה מיוחדת וגוונים ייחודיים לגינות הציבוריות.</p>
</li>
</ul>
<p data-path-to-node="8">העבודות מתבצעות כחלק מתכנית העבודה השנתית של העירייה לשימור וטיפוח המרחב הציבורי. בקרוב מאוד, עם סיום השתילות, המראות הירוקים של העיר יתחלפו במרבדים צבעוניים שיקבלו את פני הנהגים והולכי הרגל במודיעין.</p>
<p data-path-to-node="10"><img class="alignnone size-medium wp-image-6393" src="https://www.modiin4u.co.il/wp-content/uploads/2025/12/IMG-20251218-WA0000-225x300.jpg" alt="" width="225" height="300" /></p>
<p data-path-to-node="10">מכניסים צבע לעיר. עבודות השתילה הנרחבות של אגף גנים ונוף בכיכרות מודיעין.</p>
<p data-path-to-node="12"><b data-path-to-node="12" data-index-in-node="0">רוצים להישאר מעודכנים בכל מה שקורה בעיר? הצטרפו לאתר "מודיעין בשבילך" וקבלו את כל החדשות ישירות אליכם.</b></p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/12/IMG-20251218-WA0007.jpg', 'published', '2025-12-29 15:36:18') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '89afc6ef-cb1a-5f87-a246-d37de43e6c36', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('127cf056-dc5d-563f-867b-47367f494331', 'הבית של היתומים השקופים במודיעין: המקום שבו ילדים שאיבדו הורה כבר לא לבד', 'modiin-news-320', '<p data-path-to-node="1"> מחבקים את הילדים במודיעין. ראש העיר חיים ביבס עם הדר קס והמשפחות במפגש המרגש במרכז חמניות.</p>
<p data-path-to-node="1"><b data-path-to-node="1" data-index-in-node="0">בימי רביעי המרכז העירוני של עמותת חמניות הופך לעוגן עבור עשרות ילדים שחוו אובדן הורה. בביקור מרגש של ראש העיר חיים ביבס ומייסדת העמותה הדר קס נחשף הכוח של הקהילה במודיעין לתמוך ביתמות האזרחית ולהעניק למשפחות מקום בטוח לעבד את הכאב.</b></p>
<p data-path-to-node="2">יש רגעים בחיים שמשנים הכל. עבור ילדים שאיבדו הורה החיים מתחלקים ללפני ואחרי. במודיעין מכבים רעות פועל כבר שלוש שנים מרכז ייעודי של עמותת חמניות בשיתוף האגף לשירותים חברתיים בעירייה. המרכז הזה מעניק מעטפת רגשית וחברתית לילדים ובני נוער שחוו אובדן הורה בנסיבות שונות ומספק להם בית חם ושייכות.</p>
<p data-path-to-node="3">עמותת חמניות הוקמה בשנת 2018 ומתמקדת בעיקר ביתמות אזרחית. מדובר בילדים שאינם מוכרים כיתומי מערכת הביטחון ולכן לעיתים נותרים ללא מסגרת תמיכה קבועה. במודיעין המרכז פועל מדי יום רביעי ומהווה נקודת מפגש קבועה לעיבוד האובדן בסביבה בטוחה ומכילה.</p>

<h3 data-path-to-node="4">מפגש של גורל משותף וחברויות חדשות</h3>
<p data-path-to-node="5">ביום רביעי האחרון נערך במרכז מפגש מיוחד של הילדים יחד עם הוריהם האלמנים והאלמנות. במהלך הערב ביקרו במקום ראש העיר חיים ביבס ומנהלת אגף השירותים החברתיים מרינה שדה. אליהם הצטרפו מייסדת ומנכ"לית העמותה הדר קס וכן יו"ר נת"ע יודפת אפק ארזי המכהנת כחברת ועד מנהל בחמניות.</p>
<p data-path-to-node="6">המשפחות שיתפו את המבקרים בתהליך שהן עוברות במרכז. עבור רבים מהם המפגש עם אנשים שחוו טרגדיה דומה מאפשר הבנה עמוקה שקשה למצוא במקום אחר. המרכז הפך לעוגן רגשי המאפשר להם להתמודד עם האובדן ולהמשיך קדימה יחד.</p>

<h3 data-path-to-node="7">לא רק הילדים: תמיכה גם להורים</h3>
<p data-path-to-node="8">הפעילות במרכז מחולקת לשניים. בעוד הילדים נהנים מליווי רגשי ופעילויות חווייתיות בהובלת מנהלת המרכז שחר דרור ואשת הטיפול חגית גולשמידט ההורים האלמנים מתכנסים אחת לשבועיים. המפגש של ההורים מאפשר שיתוף ולמידה הדדית ומעניק להם כלים להתמודדות עם גידול הילדים לצד האובדן האישי שלהם.</p>
<p data-path-to-node="9">הפעילות משלבת שיח קבוצתי לצד משחקים וחוויות משותפות שתורמות לתחושת שגרה ושמחה. החיבור הזה מצמצם את תחושת הבדידות ומייצר חברויות וקשרים משמעותיים בין המשפחות בתוך העיר.</p>
<p data-path-to-node="10">עמותת חמניות ועיריית מודיעין מזמינות משפחות נוספות מהעיר שחוו אובדן של הורה להצטרף לפעילות המרכז ולמצוא בו אוזן קשבת וכתף תומכת.</p>
<p data-path-to-node="11"></p>
<p data-path-to-node="13"><b data-path-to-node="13" data-index-in-node="0">רוצים לקבל פרטים נוספים או להצטרף?</b> ניתן למצוא מידע נוסף באתר עמותת חמניות בכתובת: <a class="ng-star-inserted" href="https://www.hamaniot.org/" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahcKEwj-54a4jeORAxUAAAAAHQAAAAAQZQ">https://www.hamaniot.org/</a></p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2025/12/IMG-20251225-WA0001.jpg', 'published', '2025-12-29 15:38:42') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
