insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('4ad6a544-3caf-52a1-8f38-87a294983b15', 'מהפכת הכריכים במודיעין: כריכי השף של רחל ב49₪ בלבד - וזו לא "עוד הנחה"', 'rachel-modiin', '<h1></h1>
<h3><b>כוכבת "מאסטר שף", רחל, במהלך אסטרטגי מפתיע בלב המע"ר: כל כריכי השף המפורסמים שלה יימכרו ב-49 ש"ח בלבד. "לא נגענו במתכון ולא החלפנו ספקים, פשוט החלטנו לחזק את הקשר עם הקהילה במודיעין". כל הפרטים על המהלך שמשנה את כללי המשחק</b></h3>
<span style="font-weight: 400;">כבר חצי שנה שריח הלחם הטרי וחומרי הגלם המוקפדים של </span><b>"רחל בשדרה"</b><span style="font-weight: 400;"> מושכים את תושבי מודיעין ללב השדרה המרכזית במע"ר. מי שעומדת מאחורי המקום, רחל (אותה כולנו זוכרים מהופעתה המרשימה ב"מאסטר שף"), הצליחה בזמן קצר להפוך את המקום למוקד עלייה לרגל עבור חובבי קולינריה שמחפשים אוכל שף מהיר, איכותי וכשר למהדרין.</span>

<span style="font-weight: 400;">עכשיו, רחל מחליטה לשבור את השוק במהלך אסטרטגי חדש שמעורר עניין רב בעיר: </span><b>קמפיין "כריכי שף ב-49 ש"ח"</b><span style="font-weight: 400;">.</span>
<h3><img class="alignnone size-medium wp-image-6709" src="https://www.modiin4u.co.il/wp-content/uploads/2026/03/קממבר-300x200.jpg" alt="" width="300" height="200" /></h3>
<h3><b>"זו לא הנחה - זו החלטה"</b></h3>
<span style="font-weight: 400;">בעוד שיוקר המחיה נוגס בכל חלקה טובה, ב"רחל בשדרה" בחרו ללכת נגד הזרם. לא מדובר במבצע חולף או בהוזלה של רגע, אלא בהחלטה עסקית מושכלת להפוך את מוצר הדגל של המסעדה לנגיש עבור כל תושב בעיר.</span>

<b>רחל מסבירה את המהלך בביטחון:</b><span style="font-weight: 400;"> "החלטנו להנגיש את הכריכים שלנו בלי לשנות שום דבר באיכות. לא שינינו את המתכונים, לא החלפנו ספקים ולא הקטנו את המנות. הלחם נשאר אותו לחם, חומרי הגלם נשארו הפרימיום שהיו, והכשרות היא עדיין בד"ץ בית יוסף המוקפדת. זו פשוט החלטה שלנו לחזק את הקשר עם הקהילה המדהימה שנבנתה כאן במודיעין".</span>

<b>חשוב לדעת:</b><span style="font-weight: 400;"> המהלך כולל את כל כריכי השף המפורסמים בתפריט (למעט כריכי הדג והספיישלים), במחיר אחיד של 49 ש"ח.</span>
<h3></h3>
<h3><img class="alignnone size-medium wp-image-6710" src="https://www.modiin4u.co.il/wp-content/uploads/2026/03/רחוב-בוקאדו-300x200.jpg" alt="" width="300" height="200" /></h3>
<h3><b>הלב הפועם של המע"ר</b></h3>
<span style="font-weight: 400;">"רחל בשדרה" ממוקמת בנקודה האסטרטגית ביותר בעיר, והיא הפכה מזמן לחלק בלתי נפרד מהנוף האורבני של מודיעין. הביקורות המצוינות שקיבל המקום בחצי השנה האחרונה הדגישו שוב ושוב את השילוב בין יצירתיות קולינרית לסטנדרט שירות גבוה. המהלך הנוכחי צפוי להגדיל משמעותית את התנועה למקום ולהפוך את כריך השף לאופציה המובילה עבור ארוחת צהריים או ערב קלילה.</span>
<h3><b>וזה לא הכל: מה מחכה לנו בקיץ?</b></h3>
<span style="font-weight: 400;">הקמפיין הנוכחי הוא רק תחילתה של תנופה חדשה. בשיחה עם רחל, היא חושפת כי לקראת הקיץ הקרוב מתוכננים ב"רחל בשדרה" חידושים נוספים:</span>
<ul>
 	<li style="font-weight: 400;" aria-level="1"><b>תפריטי ערב משודרגים:</b><span style="font-weight: 400;"> לחוויית בילוי לילית בשדרה.</span></li>
 	<li style="font-weight: 400;" aria-level="1"><b>אירועי קונספט ופופ-אפים:</b><span style="font-weight: 400;"> שיתופי פעולה ומנות מיוחדות.</span></li>
 	<li style="font-weight: 400;" aria-level="1"><b>קייטרינג ומגשי אירוח:</b><span style="font-weight: 400;"> הרחבת שירות המשלוחים לאירועים פרטיים ועסקיים, המבוססים על איכות השף של המקום.</span></li>
</ul>
<span style="font-weight: 400;">בין אם אתם בדרך לעבודה, בבילוי משפחתי במע"ר או סתם רעבים למשהו איכותי באמת – עכשיו אין סיבה שלא להתפנק על כריך שף אמיתי.</span>

<span style="font-weight: 400;">📍 </span><b>איפה?</b><span style="font-weight: 400;"> רחל בשדרה, מע"ר מודיעין</span>

<span style="font-weight: 400;">📜 </span><b>כשרות:</b><span style="font-weight: 400;"> בד"ץ בית יוסף</span>

<span style="font-weight: 400;">🚲 </span><b>משלוחים:</b><span style="font-weight: 400;"> זמינים גם דרך אפליקציית Wolt</span>

&nbsp;', null, 'https://www.modiin4u.co.il/wp-content/uploads/2026/03/KARELA-00621-scaled.jpg', 'published', '2026-03-10 15:20:55') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
