insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('6e4fa651-81ba-5133-a37e-1e3d4266fc3f', 'ההזדמנות האחרונה במע"ר הפכה למשתלמת מתמיד: רוכשים דירה ב-My Avenue ומקבלים שובר ענק לניופאן', 'modiin-news-436', '<p class="p1" dir="rtl"></p>
<p class="p3" dir="rtl">פרויקט<span class="s2"> My Avenue </span>בלב המע<span class="s2">"</span>ר של מודיעין מוציא לדרך מבצע יוני מיוחד<span class="s2">: </span>כל מי שיבטיח לעצמו דירה חדשה בתקופה הקרובה<span class="s2">, </span>יקבל שובר בשווי<span class="s2"> 10,000 </span>₪ לרשת<span class="s2"> "</span>ניופאן<span class="s2"> ". </span>הדרך לבית החדש שלכם מעולם לא הייתה מאובזרת יותר<span class="s2">.</span></p>
<p class="p3" dir="rtl">אם תהיתם מתי הגיע הזמן לעשות את הצעד ולהשתדרג לדירת חדשה במיקום הטוב ביותר במודיעין<span class="s2"> – </span>התשובה היא עכשיו<span class="s2">. </span>פרויקט<span class="s2"><a href="https://www.modiin4u.co.il/my-avenue/"> <b>My Avenue</b></a>, </span>שכבש את שדרת דם המכבים והפך לסמל של חוויית מגורים אורבנית ואירופאית<span class="s2">, </span>יוצא במהלך מיוחד לחודש יוני שיעשה לכם סדר בבית החדש<span class="s2"> (</span>ובתקציב<span class="s2">).</span></p>
<p dir="rtl"><img class="alignnone size-medium wp-image-6953" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/מודיעין-מער-300x169.jpg" alt="" width="300" height="169" /></p>
<p class="p3" dir="rtl"><b>העסקה</b><b> </b><b>הכי</b><b> </b><b>חמה</b><b> </b><b>בלב</b><b> </b><b>העיר</b><span class="s2"><b>: My Avenue </b></span><b>הוא</b><b> </b><b>מהפרויקטים</b><b> </b><b>החדשים</b><b> </b><b>האחרונים</b><b> </b><b>שנבנים</b><b> </b><b>כיום</b><b> </b><b>במע</b><span class="s2"><b>"</b></span><b>ר</b><span class="s2"><b>, </b></span><b>ומציע</b> במע<span class="s2">"</span>ר<span class="s2"> (</span>מרכז העסקים הראשי<span class="s2">) </span>של מודיעין<span class="s2">, </span>וכבר נמצא בשלבי בנייה מתקדמים לקראת אכלוס במחצית השנייה של<span class="s2"> 2026. </span>עם שילוב מנצח של פריים<span class="s2">-</span>לוקיישן<span class="s2"> (</span>קו ראשון לשדרה<span class="s2">), </span>תכנון בוטיק מוקפד<span class="s2">, </span>וממ<span class="s2">"</span>ד פרטי בכל דירה<span class="s2">, My Avenue </span>מציע את כל מה שחסר היום לרוכשים שמחפשים ביטחון ואיכות חיים ללא פשרות<span class="s2">.</span></p>
<p class="p3" dir="rtl"><b>הטבת</b><b> </b><b>יוני</b><span class="s2"><b>: 10,000 </b></span><b>₪</b><b> </b><b>מתנה</b><b> </b><b>רכישת</b><b> </b><b>מוצרי</b><b> </b><b>חשמל</b><span class="s2"><b>.</b> </span>בפרויקט יודעים שהמעבר לדירה חדשה הוא משימה גדולה<span class="s2">, </span>ולכן החליטו להקל על הרוכשים ביוני<span class="s2">: </span>כל מי שירכוש דירה בפרויקט במהלך החודש הקרוב<span class="s2">, </span>יקבל שובר בשווי<span class="s2"> 10,000 </span>₪ לרכישת מוצרי חשמל ברשת <b>ניופאן</b><span class="s2">. </span>ממזגן או מקרר חדש במטבח<span class="s2">, </span>דרך מכונת הכביסה מתקדמת ועד למסך הטלוויזיה בסלון<span class="s2"> – </span>הדירה שלכם ב<span class="s2">-My Avenue </span>תהיה מצוידת במיטב המותגים המובילים<span class="s2">.</span></p>
<p class="p3" dir="rtl"><b>למה</b><b> </b><b>דווקא</b><b> </b><b>עכשיו</b><span class="s2"><b>?</b></span></p>

<ul class="ul1">
 	<li class="li4" dir="rtl"><b>עסקת</b><b> </b><b>מימון</b><b> </b><b>נוחה</b><span class="s2"><b>:</b> </span>תשלום של<span class="s2"> 25% </span>בלבד בחתימת החוזה<span class="s2">, </span>והיתרה<span class="s2"> (75%) </span>לקראת האכלוס<span class="s2"> – </span>ללא הצמדה למדד<span class="s2">!</span></li>
 	<li class="li5" dir="rtl"><b>הזדמנות</b><b> </b><b>אחרונה</b><span class="s2"><b>:</b> </span>המלאי בלב המע<span class="s2">"</span>ר הולך ומצטמצם<span class="s2">, </span>ורוב הדירות כבר נחטפו<span class="s2">.</span></li>
 	<li class="li6" dir="rtl"><b>סטנדרט</b><b> </b><b>בוטיק</b><span class="s2"><b>:</b> 7 </span>בניינים אינטימיים בלבד עם מפרט טכני עשיר<span class="s2">, </span>חניה ומחסן לכל דירה<span class="s2">.</span></li>
</ul>
<p class="p3" dir="rtl"><b>לורין</b><b> </b><b>צח</b><span class="s2"><b>, </b></span><b>סמנכ</b><span class="s2"><b>"</b></span><b>לית</b><span class="s2"><b> TEG ISRAEL:</b> "</span>אנחנו רואים היענות שיא בפרויקט<span class="s2">, </span>והחלטנו להעניק לרוכשי יוני ערך מוסף אמיתי<span class="s2">. </span>הדירה ב<span class="s2">-My Avenue </span>היא הבסיס לחיים החדשים שלכם<span class="s2">, </span>ואנחנו שמחים לעזור לכם לאבזר אותה במוצרי החשמל האיכותיים ביותר שיש<span class="s2">."</span></p>
<p class="p3" dir="rtl"><b>אל</b><b> </b><b>תתנו</b><b> </b><b>להזדמנות</b><b> </b><b>לחמוק</b><span class="s2"> – </span>זה הזמן לקבוע פגישה<span class="s2">, </span>לראות את הדמיית ה<span class="s2">-360 </span>המרהיבה של הפרויקט<span class="s2">, </span>ולהבין למה כולם מדברים על<span class="s2"> "</span>הדופק של העיר<span class="s2">".</span></p>
<p class="p7" dir="rtl"><span class="s3"><b>רוצים</b></span><b> </b><span class="s3"><b>לקבל</b></span><b> </b><span class="s3"><b>את</b></span><b> </b><span class="s3"><b>ההטבה</b></span><span class="s4"><b>?</b> [</span><a href="https://www.modiin4u.co.il/my-avenue/"><span class="s5">לחצו</span> <span class="s5">כאן</span> <span class="s5">לתיאום</span> <span class="s5">פגישה</span> <span class="s5">ולהשארת</span> <span class="s5">פרטים</span> <span class="s5">בדף</span> <span class="s5">הנחיתה</span><span class="s6"> – </span><span class="s5">אנחנו</span> <span class="s5">נחזור</span> <span class="s5">אליכם</span> <span class="s5">בהקדם</span><span class="s6">!</span></a><span class="s4">]</span></p>
<p class="p3" dir="rtl"><i>ההטבה</i><i> </i><i>מיועדת</i><i> </i><i>ללקוחות</i><i> </i><i>פרטיים</i><i> </i><i>בלבד</i><span class="s2"><i>, </i></span><i>למימוש</i><i> </i><i>בחנות</i><i> </i><i>ניופאן</i><i> </i><i>אאוטלט</i><i> </i><i>בכפוף</i><i> </i><i>לתקנון</i><i> </i><i>הפרויקט</i><span class="s2"><i>. </i></span><i>לא</i><i> </i><i>כולל</i><i> </i><i>מבצעים</i><span class="s2"><i>, </i></span><i>עודפי</i><i> </i><i>מלאי</i><i> </i><i>או</i><i> </i><i>תצוגות</i><span class="s2"><i>. </i></span><i>ט</i><span class="s2"><i>.</i></span><i>ל</i><span class="s2"><i>.</i></span><i>ח</i><span class="s2"><i>.</i></span></p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/6-scaled.jpg', 'published', '2026-06-03 08:25:27') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '6e4fa651-81ba-5133-a37e-1e3d4266fc3f', '0b7bab49-3199-50e5-a7e2-3ff5d339d311') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('463ec30d-6c77-5d47-9082-d4a6dc7ecd08', 'עורך דין מומלץ במודיעין - ידידיה בלויגרונד שיילחם בשבילכם', 'recommended-injury-lawyer-modiin-yedidya', '<p data-path-to-node="8">כולנו מכירים את תחושת הגאווה המקומית שמלווה אותנו כתושבי מודיעין מכבים רעות. העיר שלנו נקייה, מטופחת, הקהילה כאן תומכת ומחבקת, ואיכות החיים היא מהגבוהות בישראל. אבל החיים, כמו החיים, מזמנים לנו לפעמים גם רגעים פחות נעימים שאינם צפויים מראש. זה יכול להיות אירוע פתאומי כמו תאונת דרכים קשה ומבהילה באחד הבקרים בכביש 443 או ביציאה לכביש 431, זה יכול להתבטא בנפילה מצערת וכואבת בגלל מדרכה שבורה או מפגע תשתיתי בשכונה ותיקה, או חלילה פציעה בלתי צפויה במהלך יום העבודה באזור התעשייה (הפארק הטכנולוגי) או במרכז עינב.</p>
<p data-path-to-node="9">כשמשהו רע כזה קורה, הגוף כואב, הראש עמוס בדאגות, והדבר האחרון שיש לכם כוח אליו הוא להתחיל לנסוע בפקקים המתישים לירושלים או לתל אביב כדי לפגוש איזה עורך דין במגדל משרדים מנוכר. אתם לא צריכים מישהו שלא מכיר את האזור שלנו, לא יודע איפה נמצאים בתי החולים הסמוכים (כמו שמיר-אסף הרופא או קפלן) ולא באמת מבין את הדינמיקה והריאליטי של החיים במודיעין.</p>
<p data-path-to-node="10">מודיעין גדלה והתפתחה בקצב פנומנלי. היא כבר מזמן לא עיר שינה קטנה שצריכה "לייבא" שירותים מקצועיים ומנוכרים מאזור המרכז. יש לנו כאן, ממש מתחת לבית, רופאים מעולים, אדריכלים מוכשרים, יועצי מס מובילים ואנשי מקצוע ברמה הגבוהה ביותר בארץ, שבוחרים באופן מודע להעתיק את הפעילות שלהם לכאן ולהיות חלק בלתי נפרד מהקהילה שלנו. אחד השמות הבולטים והמומלצים ביותר בתקופה האחרונה בעיר הוא עורך הדין ידידיה בלויגרונד. ידידיה זיהה את הצורך הגובר של תושבי העיר בליווי משפטי איכותי ונגיש, פתח סניף מקומי במודיעין, ומאז הוא מלווה תושבים מודיעינים רבים בדרך הבטוחה והנחושה להשגת הפיצוי הכספי המקסימלי שמגיע להם מחברות הביטוח ומהמוסד לביטוח לאומי.</p>

<h3 data-path-to-node="12">מי זה ידידיה בלויגרונד? משרד בוטיק עם עוצמה של פירמה גדולה</h3>
<p data-path-to-node="13">אם יצא לכם לחפש לאחרונה המלצות על <a class="ng-star-inserted" href="https://didilaw.co.il" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahgKEwjkwNDe4uqUAxUAAAAAHQAAAAAQoQI">עורך דין מומלץ במודיעין</a>, סביר להניח שהשם שלו עלה בשיחות בקבוצות הפייסבוק המקומיות או בהמלצות מפה לאוזן בין שכנים. <a class="ng-star-inserted" href="https://didilaw.co.il" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahgKEwjkwNDe4uqUAxUAAAAAHQAAAAAQogI">משרד עורכי דין ידידיה בלויגרונד</a> הוקם בשנת 2012 ומאז ועד היום מנוהל ביד רמה ובאופן אישי על ידי עו"ד ידידיה בלויגרונד. בניגוד לעורכי דין רבים בשוק שמנסים "לעשות הכל מהכל" – לטפל בקניית דירה בבוקר, לערוך צוואה בצהריים ולייצג בגירושין בערב – עו"ד בלויגרונד קיבל החלטה אסטרטגית ברורה מתחילת דרכו המקצועית: להתמחות בתחום ממוקד אחד בלבד – דיני נזיקין, תאונות וביטוח.</p>
<p data-path-to-node="14">כאשר אתם שוכרים את שירותיו של <a class="ng-star-inserted" href="https://didilaw.co.il" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahgKEwjkwNDe4uqUAxUAAAAAHQAAAAAQowI">עורך דין נזיקין מודיעין</a>, אתם לא מחפשים גנרליסט, אלא מומחה ספציפי שמכיר את עולם הנזיקין על בוריו ולעומק המקסימלי. ידידיה בלויגרונד שולט בכל אות קטנה בפוליסות הביטוח המורכבות ביותר, ומכיר מקרוב את הדרך שבה ועדות רפואיות של הביטוח הלאומי וחברות הביטוח מתנהלות בפועל מאחורי הקלעים.</p>
<p data-path-to-node="15">כדי להעניק את השירות הטוב ביותר, המשרד מתפעל כיום שני סניפים פעילים: הסניף המקומי החדש במודיעין ממוקם בלב האזור העסקי והתוסס של העיר – בבניין אילה 360 (שדרות המלאכות 21, קומה 5), ממש מול מתחם יוחננוף ובסמוך לתחנת הרכבת "פאתי מודיעין". המיקום הזה לא נבחר במקרה: הוא נגיש מאוד, מציע חניה בשפע, ומאפשר לכל תושב בעיר להגיע לפגישת עבודה מקצועית או לקבלת <a class="ng-star-inserted" href="https://didilaw.co.il" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahgKEwjkwNDe4uqUAxUAAAAAHQAAAAAQpAI">ייעוץ משפטי מודיעין</a> בצורה מהירה ונוחה, בלי לבזבז ימי עבודה שלמים על נסיעות מחוץ לעיר. לאורך יותר מ-14 שנות פעילות ענפה, המשרד גאה להציג שיעור הצלחה פנומנלי של כ-90% בתיקים המשפטיים שליווה, תוך שהוא חרט על דגלו מתן ליווי אישי, אנושי וצמוד לכל לקוח ולקוח – מהרגע שבו התיק נפתח ועד שהצ''ק מחברת הביטוח מופקד בחשבון הבנק.</p>

<h3 data-path-to-node="17">למה תושבי מודיעין חייבים עורך דין שמכיר את האזור באמת?</h3>
<p data-path-to-node="18">זוהי שאלה קריטית שאנשים שנפגעו בתאונה לא תמיד חושבים עליה בדקות הראשונות, אך יש לה השפעה עצומה על סיכויי ההצלחה של התיק שלכם. עורך דין שיושב במשרד מפואר בתל אביב או ברמת גן אולי יודע לקרוא את ספר החוקים, אבל הוא לא מכיר את המציאות היומיומית בכבישים ובשכונות שלנו. הוא לא תמיד מודע לכך שכביש 443 הוא אחד העורקים המאתגרים והמסוכנים ביותר בארץ, שבו מתרחשות תאונות דרכים קשות ומורכבות מדי שבוע בשבוע. הוא לא מכיר את המבנה הייחודי של הפארק הטכנולוגי במודיעין שבו עובדים עשרות אלפי תושבים ואנשי מקצוע, והוא בטח לא מכיר את המרחבים הציבוריים, הגינות הציבוריות והכיכרות בשכונות השונות בעיר (כמו משואה, כרמים או אבני חן), שבהן ליקויי תאורה זמניים או מדרכות שלא תוקנו בזמן על ידי העירייה עלולים לגרום לפציעות חמורות אצל מבוגרים וילדים כאחד.</p>
<p data-path-to-node="19">עו"ד ידידיה בלויגרונד, באמצעות <a class="ng-star-inserted" href="https://didilaw.co.il" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahgKEwjkwNDe4uqUAxUAAAAAHQAAAAAQpQI">משרד עורכי דין מודיעין</a> שהקים כאן, חי ונושם את האזור. כשהוא בונה עבורכם תיק תביעה בגין נפילה ברחוב או תאונה, הוא יודע בדיוק על איזה מפגע מדובר, הוא מכיר את נהלי הרשות המקומית, והוא יודע אילו ראיות ותיעוד מהשטח צריך לאסוף באופן מיידי. היכרות שטח זו אינה רק עניין של נוחות פיזית עבורכם כשאתם מגיעים לפגישה – היא הכלי העוצמתי ביותר לבניית אסטרטגיה משפטית מנצחת שתוביל להשגת פיצויים גבוהים בהרבה.</p>

<h3 data-path-to-node="21">באילו מצבים תושב מודיעין צריך לפנות לידידיה בלויגרונד?</h3>
<p data-path-to-node="22">תחום דיני הנזיקין הוא רחב ומקיף פגיעות רבות ומגוונות שיכולות לשנות את שגרת החיים ברגע אחד. הנה המצבים המרכזיים שבהם המשרד המקומי מעניק עזרה וייצוג משפטי חסר פשרות:</p>

<h4 data-path-to-node="23">1. תאונות דרכים (בתוך העיר ומחוצה לה)</h4>
<p data-path-to-node="24">אם חלילה נפגעתם כנהגים, כנוסעים או כהולכי רגל בתאונת דרכים בכבישי האזור, אתם זקוקים בדחיפות לליווי של <a class="ng-star-inserted" href="https://didilaw.co.il" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahgKEwjkwNDe4uqUAxUAAAAAHQAAAAAQpgI">עורך דין תאונות דרכים מודיעין</a>. חוק הפיצויים לנפגעי תאונות דרכים (הפלת"ד) מעניק זכויות רבות לנפגעים, אך חברות הביטוח אינן ממהרות לשלם. הן מגיעות לכל תיק כשהן חמושות בצוותים מיומנים של חוקרים פרטיים, רופאים מטעמן ועורכי דין ממולחים, שמטרתם המוצהרת היא אחת: להקטין, לצמצם או לדחות לחלוטין את תביעת הפיצויי שלכם. ייצוג מקצועי ואגרסיבי מהיום הראשון הוא ההגנה היחידה שלכם מול המערכות הללו.</p>

<h4 data-path-to-node="25">2. תאונות עבודה ומחלות מקצוע</h4>
<p data-path-to-node="26">תושבים רבים במודיעין עובדים באזורי התעשייה המקומיים או נוסעים מדי יום למרכזי התעסוקה הגדולים ברחבי גוש דן, לוד ורחובות. אם עברתם תאונה במהלך העבודה, בדרך אליה או בחזרה ממנה, האירוע מוגדר כתאונת עבודה. ניהול תיק כזה הוא מורכב במיוחד מכיוון שהוא דורש התנהלות מקבילה, חכמה ומתואמת: הגשת תביעה לקביעת אחוזי נכות מול המוסד לביטוח לאומי, תביעה פוטנציאלית נגד חברת הביטוח של המעסיק במידה והייתה רשלנות, ומימוש פוליסות פרטיות (כמו אובדן כושר עבודה או ביטוח תאונות אישיות). ללא ליווי של <a class="ng-star-inserted" href="https://didilaw.co.il" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahgKEwjkwNDe4uqUAxUAAAAAHQAAAAAQpwI">עורך דין תאונות עבודה מודיעין</a>, קל מאוד ללכת לאיבוד בבירוקרטיה ולפספס זכויות כספיות ששוות מאות אלפי שקלים.</p>

<h4 data-path-to-node="27">3. תאונות ילדים וקטינים (במוסדות חינוך ובכל מקום אחר)</h4>
<p data-path-to-node="28">מודיעין היא עיר של משפחות וילדים. פציעות של ילדים בגני ילדים, בבתי הספר, בתנועות הנוער או במגרשי המשחקים השכונתיים הן למרבה הצער מחזה נפוץ. הורים רבים אינם מודעים לכך שכל תלמיד במערכת החינוך בישראל מבוטח באופן אוטומטי בפוליסת ביטוח תאונות אישיות תלמידים, המעניקה כיסוי ביטוחי רחב לנזקים ואחוזי נכות <b data-path-to-node="28" data-index-in-node="299">24 שעות ביממה, 365 ימים בשנה</b> – ללא קשר לשאלה אם התאונה קרתה בתוך כותלי בית הספר או במהלך משחק אחה"צ ליד הבית. המשרד מתמחה בהגשת תביעות מורכבות אלו והבטחת עתידם הכלכלי של הילדים.</p>

<h4 data-path-to-node="29">4. רשלנות רשויות מקומיות ומפגעים במרחב הציבורי</h4>
<p data-path-to-node="30">נפילה בשל בור פתוח בכביש, מדרכה בולטת שלא תוקנה, או החלקה על מפגע במרכז מסחרי שכונתי. החוק מטיל על הרשות המקומית ועל בעלי נכסים חובת זהירות קשיחה כלפי העוברים והשבים. אם הוכחה רשלנות בתחזוקה שגרמה לפציעתכם, אתם זכאים לפיצויים משמעותיים בגין כאב וסבל, הפסדי שכר והוצאות רפואיות.</p>

<h3 data-path-to-node="32">המשאב החשוב ביותר בתביעות נזיקין: זמן</h3>
<p data-path-to-node="33">אחת הטעויות הנפוצות והכואבות ביותר שתושבים עושים לאחר פגיעה היא ההשתהות וההמתנה. אנשים שנפגעו נוטים לומר לעצמם: "כרגע נתמקד בלהחלים ולחזור לשגרה, ובנושא המשפטי נטפל כשיהיה לנו זמן ואוויר". זוהי שגיאה אסטרטגית שעלולה לעלות לכם ביוקר רב.</p>
<p data-path-to-node="34">חוקי ההתיישנות והנהלים הפנימיים של חברות הביטוח והביטוח הלאומי מציבים לוחות זמנים נוקשים ביותר. בעוד שתביעה אזרחית רגילה מתיישנת תוך 7 שנים, הרי שפעולות קריטיות רבות חייבות להתבצע בשבועות ובחודשים הראשונים שלאחר האירוע:</p>

<ul data-path-to-node="35">
 	<li>
<p data-path-to-node="35,0,0">איסוף ראיות חמות מזירת האירוע (צילום המפגע, צילום חבלות בזמן אמת).</p>
</li>
 	<li>
<p data-path-to-node="35,1,0">איתור ורישום פרטים של עדי ראייה שהיו במקום לפני שייעלמו או ישכחו את הפרטים.</p>
</li>
 	<li>
<p data-path-to-node="35,2,0">הקפדה על ניסוח מדויק של התלונות הרפואיות בחדרי המיון ובקופות החולים (חברות הביטוח יחפשו כל סתירה קטנה במסמכים כדי לטעון שהפציעה נגרמה ממשהו אחר).</p>
</li>
</ul>
<p data-path-to-node="36">כדי להסיר מכם את החשש וההתלבטות, פגישת הייעוץ הראשונה אצל עו"ד ידידיה בלויגרונד היא לחלוטין <b data-path-to-node="36" data-index-in-node="92">ללא עלות וללא כל התחייבות מצדכם</b>. המשמעות היא שאין לכם שום סיבה מוצדקת לדחות את הבדיקה. אתם מגיעים, מציגים את המקרה, ומקבלים מפת דרכים משפטית מקצועית וברורה לגבי סיכויי התיק שלכם.</p>

<h3 data-path-to-node="38">למה לבחור במשרד בוטיק מקומי ולא בפירמת ענק תל-אביבית?</h3>
<p data-path-to-node="39">רבים חושבים בטעות שכדי לנצח את חברות הביטוח הגדולות צריך לשכור פירמת עורכי דין ענקית מהמרכז, המחזיקה בעשרות עורכי דין. המציאות בשטח מוכיחה בדיוק את ההפך. בפירמות הגדולות, הלקוח הפרטי הופך מהר מאוד לעוד מספר בתוך קובץ מחשב. בפגישה הראשונה אתם אולי פוגשים את השותף הבכיר, אך בפועל מי שמנהל את התיק שלכם, מנסח את המכתבים ומשוחח איתכם בטלפון הוא מתמחה צעיר או עורך דין זוטר שרק סיים את לימודיו ומטפל במאה תיקים במקביל.</p>
<p data-path-to-node="40">ידידיה בלויגרונד מנהל משרד במודל בוטיק. המשמעות עבורכם היא תהומית:</p>

<ul data-path-to-node="41">
 	<li>
<p data-path-to-node="41,0,0"><b data-path-to-node="41,0,0" data-index-in-node="0">טיפול אישי בגובה העיניים:</b> עו"ד בלויגרונד מעורב באופן אישי בכל פרט ופרט בתיק שלכם, בונה את האסטרטגיה ומייצג אתכם בעצמו בוועדות ובבתי המשפט.</p>
</li>
 	<li>
<p data-path-to-node="41,1,0"><b data-path-to-node="41,1,0" data-index-in-node="0">זמינות אמיתית ויחס חם:</b> אתם לא צריכים לעבור מסכת של מזכירות ומנהלות לשכה כדי לקבל תשובה פשוטה על מצב התיק שלכם.</p>
</li>
 	<li>
<p data-path-to-node="41,2,0"><b data-path-to-node="41,2,0" data-index-in-node="0">מחויבות קהילתית עמוקה:</b> היותו של ידידיה חלק מהמרקם החברתי והעסקי של מודיעין מכבים רעות הופכת את התיק שלכם לחשוב לו ברמה האישית. תושב העיר שמגיע אל <a class="ng-star-inserted" href="https://didilaw.co.il/עורך-דין-במודיעין" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahgKEwjkwNDe4uqUAxUAAAAAHQAAAAAQqAI">עורך דין במודיעין</a> לא מדבר עם פונקציה אנונימית במגדל רחוק, אלא עם איש מקצוע שמחויב לשמור על השם הטוב שלו בתוך הקהילה שבה הוא חי ופועל.</p>
</li>
</ul>
<h3 data-path-to-node="43">צרו קשר עוד היום והגנו על הזכויות שלכם</h3>
<p data-path-to-node="44">הגוף שלכם נפגע? אל תתמודדו עם המערכת הבירוקרטית והמשפטית לבדכם, ואל תאפשרו לחברות הביטוח המתוחכמות לחסוך כסף על גבכם ועל חשבון הבריאות והעתיד שלכם.</p>

<ul data-path-to-node="45">
 	<li>
<p data-path-to-node="45,0,0"><b data-path-to-node="45,0,0" data-index-in-node="0">כתובת סניף מודיעין:</b> שדרות המלאכות 21, בניין A, קומה 5 (מתחם אילה 360 – מול יוחננוף, סמוך לתחנת הרכבת "פאתי מודיעין").</p>
</li>
 	<li>
<p data-path-to-node="45,1,0"><b data-path-to-node="45,1,0" data-index-in-node="0">טלפון ישיר למשרד:</b> 02-650-8826</p>
</li>
 	<li>
<p data-path-to-node="45,2,0"><b data-path-to-node="45,2,0" data-index-in-node="0">אתר אינטרנט הרשמי:</b> <a class="ng-star-inserted" href="https://didilaw.co.il" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahgKEwjkwNDe4uqUAxUAAAAAHQAAAAAQqQI">didilaw.co.il</a></p>
</li>
 	<li>
<p data-path-to-node="45,3,0"><b data-path-to-node="45,3,0" data-index-in-node="0">לתיאום פגישה מהירה:</b> <a class="ng-star-inserted" href="https://didilaw.co.il/צור-קשר" target="_blank" rel="noopener" data-hveid="0" data-ved="0CAAQ_4QMahgKEwjkwNDe4uqUAxUAAAAAHQAAAAAQqgI">לתיאום ייעוץ ראשוני ללא עלות</a> לחצו כאן, השאירו פרטים ונחזור אליכם בהקדם.</p>
</li>
</ul>
<p data-path-to-node="46">זכרו, פגישת הייעוץ הראשונית אינה עולה לכם דבר ואינה מחייבת אתכם, אך במקרים רבים של פציעות ותאונות – היא שווה הרבה מאוד כסף ושקט נפשי לעתיד שלכם ושל משפחתכם.</p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/496059454_1262121455919698_6535892135887009426_n.jpg', 'published', '2026-06-03 11:09:22') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
