insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('dd3c2532-e192-521b-82ba-a2fc3c632089', 'הדמעות שלא יבשו: המשפחות השכולות וראש העיר התייחדו בטקס מרגש בעירוני א''', 'modiin-news-457', '<p data-path-to-node="6">"להבטיח שסיפורם יישאר נוכח במקום שבו גדלים הדורות הבאים". במעמד המשפחות השכולות, ראש העיר חיים ביבס וקהילת בית הספר, נערך טקס הסרת הלוט מאנדרטת ההנצחה החדשה בעירוני א'' לזכר ששת הבוגרים, חללי מערכות ישראל.</p>
<p data-path-to-node="7">קהילת בית הספר עירוני א'' במודיעין, יחד עם הנהגת העיר והמשפחות השכולות, התייחדו ביום שלישי האחרון (16.6) בטקס מרגש וכואב במיוחד. במהלך הטקס הוסר הלוט ונחשף אתר ההנצחה הבית-ספרי החדש, המוקדש לזכרם של שישה מבוגרי בית הספר, חללי מערכות ישראל שנפלו בעת שירותם ובמילוי שליחותם למען ביטחון המדינה.</p>
<p data-path-to-node="8">הטקס התקיים במעמד ראש העיר חיים ביבס, מנהל בית הספר ד"ר דביר שלומי, חברים, תלמידים, צוותי ההוראה וקהילת בית הספר, שעמדו לצד המשפחות השכולות ברגעים המצמררים של חשיפת האנדרטה.</p>

<h4 data-path-to-node="9"><img class="alignnone size-medium wp-image-7051" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/IMG-20260618-WA0010-300x225.jpg" alt="" width="300" height="225" /></h4>
<h4 data-path-to-node="9">הבוגרים שאינם: שישה סיפורי חיים שנגדעו</h4>
<p data-path-to-node="10">באנדרטה החדשה מונצחים שישה מתלמידי בית הספר לשעבר, שכל אחד מהם הותיר חותם עמוק בלבבות מכריהם:</p>

<ul data-path-to-node="11">
 	<li>
<p data-path-to-node="11,0,0"><b data-path-to-node="11,0,0" data-index-in-node="0">רב סרן במיל'' מושיקו מקסים רוזנוולד ז"ל</b>, אשר נפל ב-16 בדצמבר 2024. מושיקו בלט כבר מנעוריו בחוש צדק מפותח, אחריות אישית גבוהה ויכולת מנהיגות והובלה. הוא היה מהנדס מצטיין שראה בהנצחת חללי ישראל שליחות עליונה, ושירת כמפקד פלוגה בגדוד הנדסה 7107 בחטיבת הנח"ל.</p>
</li>
 	<li>
<p data-path-to-node="11,1,0"><b data-path-to-node="11,1,0" data-index-in-node="0">רב סמל במיל'' רן יעבץ ז"ל</b>, אשר נפל ב-16 במאי 2024. רן היה עבור רבים סמל מובהק לאהבה ונתינה, תמיד עם חיוך רחב ומילה טובה לכולם. הוא היה בעל אוהב לתמר ואבא מסור לאיתי, נגה, אור ורנה. שירת כלוחם בגדוד סיור 6828 של חטיבת ביסל"ח (828).</p>
</li>
 	<li>
<p data-path-to-node="11,2,0"><b data-path-to-node="11,2,0" data-index-in-node="0">רב סמל אלון קודריאשוב ז"ל</b>, אשר נפל ב-29 במרץ 2024. לוחם סיירת אגוז של עוצבת הקומנדו. כנער, אלון הציב לעצמו מטרות קשוחות ועמד בהן פעם אחר פעם, כולל זכייה בחגורה שחורה בקרטה והגשמת חלומו הגדול לשרת כלוחם ביחידת עילית.</p>
</li>
 	<li>
<p data-path-to-node="11,3,0"><b data-path-to-node="11,3,0" data-index-in-node="0">סמ"ר עמית דוד חבורה ז"ל</b>, אשר נפל ב-24 במאי 2022. עמית היה תלמיד מצטיין, אהוב על חבריו, יצירתי ומוזיקאי מוכשר שהרבה לנגן בפסנתר. הוא שירת כלוחם וכמפקד בחטיבת כפיר ואף תכנן להמשיך לקורס קצינים.</p>
</li>
 	<li>
<p data-path-to-node="11,4,0"><b data-path-to-node="11,4,0" data-index-in-node="0">סמ"ר עמית טל-און ז"ל</b>, אשר נפל ב-18 במאי 2018. עמית בלט כתלמיד מצטיין במדעי המחשב, מתמטיקה ואנגלית, והיה ספורטאי ואיש ספר מעורר השראה. שירת ביחידה הטכנית של חטיבה 401.</p>
</li>
 	<li>
<p data-path-to-node="11,5,0"><b data-path-to-node="11,5,0" data-index-in-node="0">סמ"ר איתי שוורץ ז"ל</b>, אשר נפל ב-16 במרץ 2006. נער רגיש, אידיאליסט ואוהב אדם, שהאמין בכל ליבו בשלום, באחדות ובחמלה, וגילה אחריות עמוקה כלפי החברה והטבע. שירת כחובש קרבי בגדוד 931 של חטיבת הנח"ל.</p>
</li>
</ul>
<h4 data-path-to-node="12"><img class="alignnone size-medium wp-image-7052" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/IMG-20260618-WA0008-300x225.jpg" alt="" width="300" height="225" /></h4>
<h4 data-path-to-node="12">"העבר מעניק משמעות להווה ומצפן לעתיד"</h4>
<p data-path-to-node="13">בית הספר עירוני א'' הצמיח לאורך השנים דורות של בוגרות ובוגרים שבחרו לתרום לחברה ולמדינה באופן פעיל, כאשר שיעורי הגיוס והשירות המשמעותי במוסד הם מהגבוהים ביותר בארץ. האנדרטה הבית-ספרית החדשה משתלבת במסורת העירונית הענפה להנצחת בנותיה ובניה של העיר – בבית יד לבנים, במשעולים, במעלות ובבתי הספר שבהם התחנכו. המטרה היא להבטיח שסיפורם של הנופלים יישאר נוכח וחי במקום שבו גדלים הדורות הבאים, כחלק בלתי נפרד מן הזהות הערכית של העיר.</p>
<p data-path-to-node="14"><b data-path-to-node="14" data-index-in-node="0">ראש העיר, חיים ביבס</b>, נשא דברים כואבים בטקס: "העיר שלנו נפרדה בכאב מחיילות וחיילים אמיצים, ששילמו את המחיר היקר מכל במאבק על קיומה ובטחונה של מדינת ישראל. בני הדור הזה, דור הניצחון, הוכיחו במסירותם כי רוח השירות, הערבות ההדדית והמחויבות למדינת ישראל הן היסוד המרכזי בחוסנה של החברה הישראלית".</p>
<p data-path-to-node="15"><b data-path-to-node="15" data-index-in-node="0">מנהל בית הספר, ד"ר דביר שלומי</b>, הוסיף ואמר: "מתוך הכאב הגדול, אנו מבינים כי ישנם אנשים שאינם חדלים להיות נוכחים. הם ממשיכים לחיות בזיכרון, בערכים שהותירו אחריהם, באהבה שהם עוררו ובחותם שהטביעו על כל מי שפגש אותם. אנו מבקשים להפוך את אתר ההנצחה למקום של בין-דורות, מפגש בין הזיכרון לבין החיים שנמשכים סביבו. מקום שבו העבר מעניק משמעות להווה ומצפן לעתיד".</p>
<p data-path-to-node="16">מערכת "מודיעין בשבילך" מרכינה ראש ומחבקת את המשפחות השכולות. יהי זכרם של הנופלים ברוך.</p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/IMG-20260618-WA0011.jpg', 'published', '2026-06-25 16:30:43') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', 'dd3c2532-e192-521b-82ba-a2fc3c632089', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('330e5469-d33f-51b2-9918-ee0b3e3672e7', 'בחינם לחלוטין ובדיוק בזמן לקיץ: המהלך החדש שישנה את הדרך שלכם לתל אביב בסופ"ש!', 'modiin-news-458', '<p data-path-to-node="6">בשורה אדירה לצעירים, לנוער ולמשפחות במודיעין לקראת החופש הגדול: ראש העיר חיים ביבס הנחה לתגבר את קו 712 הפופולרי הפועל בימי שישי, שבת וחגים. מתי יפורסם הלו"ז החדש ואיך זה ישפיע עליכם? כל הפרטים.</p>
<p data-path-to-node="7">החופש הגדול והקיץ כבר כאן, ועיריית מודיעין מכבים רעות מביאה בשורה משמחת במיוחד לתושבי העיר שנוהגים לבלות בסופי השבוע מחוץ לעיר, ובפרט לחובבי חופי הים וחיי הלילה של תל אביב: מערך ההסעות החינמי "נעים בסופ"ש" זוכה לתגבור משמעותי נוסף.</p>
<p data-path-to-node="8">כחלק מהמהלך המתמשך שמובילה העירייה לשיפור התחבורה והשירות לתושב, במהלך חודש יולי הקרוב יתווספו לא פחות מ<b data-path-to-node="8" data-index-in-node="104">תשע נסיעות נוספות בכל סוף שבוע</b> בקו 712 – הקו הישיר המחבר בין מודיעין מכבים רעות לתל אביב, הפועל ללא תשלום בימי שישי, שבת ובחגים.</p>

<h4 data-path-to-node="9">הביקוש זינק – ראש העיר הנחה לתגבר</h4>
<p data-path-to-node="10">ההחלטה על התגבור הנוכחי לא נולדה יש מאין. בעירייה מקיימים מעקב שוטף ובחינה מדוקדקת של נתוני השימוש בקו, לצד קבלת פניות רבות מהתושבים מהשטח שהצביעו על צורך ממשי בהרחבת השירות. בעקבות נתונים אלו, הנחה ראש העיר, חיים ביבס, את הגורמים המקצועיים ברשות לבצע את ההתאמות הנדרשות ולהגדיל את תדירות הנסיעות באופן מיידי לקראת חודשי הקיץ החמים – תקופה שבה משפחות, בני נוער וצעירים רבים מחפשים פתרונות ניידות יעילים וזולים לבילויים וטיולים.</p>
<p data-path-to-node="11">נזכיר כי רק בחודש אפריל האחרון הובילה העירייה מהלך נרחב לשדרוג השירות, שכלל תגבור של תדירות הקו ושינוי אסטרטגי במסלולו בתוך תל אביב, במטרה להתאים אותו בצורה מדויקת יותר למוקדי העניין של הנוסעים. המהלך הוכיח את עצמו מעל ומעבר: בעקבות השינויים הללו נרשמה עלייה חדה במספר המשתמשים בקו, והביקוש לשירות הלך וגדל – מה שהוביל כעת לצורך בתגבור הנוכחי.</p>

<h4 data-path-to-node="12">מתי יתפרסם הלו"ז המעודכן?</h4>
<p data-path-to-node="13">במחלקת התחבורה הציבורית של עיריית מודיעין מכבים רעות מציינים כי הלו"ז החדש והמעודכן, הכולל את תשע הנסיעות הנוספות, יתפרסם כבר <b data-path-to-node="13" data-index-in-node="126">בימים הקרובים</b>.</p>
<p data-path-to-node="14">התושבים המעוניינים להתעדכן בשעות היציאה המדויקות ובתחנות האיסוף מוזמנים לעקוב אחר הפרסומים הרשמיים באתר "נעים בסופ"ש" ובאתר העירייה.</p>
<p data-path-to-node="15">אנחנו באתר "מודיעין בשבילך" נמשיך לעקוב ולעדכן אתכם בכל שינוי בשטח. נסיעה טובה ובטוחה!</p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/FB_IMG_1776576077180.jpg', 'published', '2026-06-25 16:35:20') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
insert into entity_categories (entity_type, entity_id, category_id) values ('article', '330e5469-d33f-51b2-9918-ee0b3e3672e7', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('1d38338f-cdcc-538f-ae24-ad27b5a8950b', 'חוגגים 30 לעיר: נועה קירל, חנן בן ארי ועדן בן זקן מגיעים למודיעין! לוח האירועים המלא לקיץ 2026', 'modiin-news-459', '<p data-path-to-node="6">חוגגים 30 שנה למודיעין בקיץ שלא תשכחו: מהקרנות מונדיאל חיות ופסטיבלי אלכוהול, ועד להופעות חינמיות של הכוכבים הכי גדולים בישראל קרוב לבית. הצצה ראשונה ללוח האירועים הרשמי.</p>
<p data-path-to-node="7">הקיץ של מודיעין מכבים רעות עומד להיות השנה חם, קצבי ומרגש במיוחד: תוכנית "קיץ מודיעיני" 2026 מגיעה בצעדי ענק, והפעם היא חגיגית מתמיד ועומדת בסימן 30 שנה להקמתה של העיר. התושבים ייהנו מתכנית עשירה, מגוונת ואינטנסיבית של אירועים ופעילויות כמעט מדי יום – והבשורה המשמחת ביותר: <b data-path-to-node="7" data-index-in-node="274">הכל ללא תשלום</b>.</p>
<p data-path-to-node="8">מאחורי המהלך הענק עומד שיתוף פעולה נרחב של אגף תרבות ואירועים, עמותת סחלבים, אגף קהילה, אגף הספורט ומחלקת הבריאות, שחברו יחד כדי לייצר מענה מושלם לכל הקהלים בעיר – מאזרחים ותיקים ועד לפעוטות וילדים. התוכנית המלאה תישלח ישירות לבתי התושבים בתוך מעטפות הארנונה בתחילת חודש יולי, והיא כבר מעודכנת במלואה בלוח האירועים באתר העירייה.</p>
<p data-path-to-node="9">אז כדי שלא תפספסו שום דבר, הנה הטעימות והתאריכים המרכזיים שאתם חייבים לסמן כבר עכשיו ביומנים:</p>

<h4 data-path-to-node="10">נבחרת הכוכבים מגיעה לאמפי ובענבה</h4>
<p data-path-to-node="11">הקיץ הקרוב יארח את השמות הגדולים ביותר במוזיקה הישראלית להופעות ענק בלתי נשכחות:</p>

<ul data-path-to-node="12">
 	<li>
<p data-path-to-node="12,0,0"><b data-path-to-node="12,0,0" data-index-in-node="0">חגיגות ה-30 הרשמיות (30.7):</b> מודיעין מציינת שלושה עשורים בהפקה חגיגית באמפי פארק החולה (בשעה 20:00) עם הופעות ענק של <b data-path-to-node="12,0,0" data-index-in-node="116">עדן בן זקן</b>, וכן <b data-path-to-node="12,0,0" data-index-in-node="132">עילי בוטנר והילדים החדשים</b>.</p>
</li>
 	<li>
<p data-path-to-node="12,1,0"><b data-path-to-node="12,1,0" data-index-in-node="0">חנן בן ארי בענבה (13.8):</b> במסגרת מופעי "ענבה לייב", יגיע חנן בן ארי להרעיד את הפארק בשעה 20:30.</p>
</li>
 	<li>
<p data-path-to-node="12,2,0"><b data-path-to-node="12,2,0" data-index-in-node="0">הפרויקט של רביבו ותזמורת צה"ל (18.8):</b> שילוב נוסטלגי ומקפיץ במיוחד שיערך בפארק ענבה בשעה 20:30.</p>
</li>
 	<li>
<p data-path-to-node="12,3,0"><b data-path-to-node="12,3,0" data-index-in-node="0">מופע הנעילה המטורף:</b> אירועי הקיץ ייחתמו בסטייל באמפי פארק החולה (בשעה 20:00) עם שניים מהאמנים המבוקשים ביותר בישראל – <b data-path-to-node="12,3,0" data-index-in-node="117">עדן חסון ונועה קירל</b>.</p>
</li>
</ul>
<h4 data-path-to-node="13">פסטיבלים, בירה ושידורי מונדיאל</h4>
<p data-path-to-node="14">אם אתם מחפשים בילוי לילי עם חברים, הנה האירועים המיוחדים שצפויים להרקיד את העיר:</p>

<ul data-path-to-node="15">
 	<li>
<p data-path-to-node="15,0,0"><b data-path-to-node="15,0,0" data-index-in-node="0">פסטיבל הבירה (30.6-1.7):</b> יומיים של חגיגה בפארק הדגים הכוללת מתחמי בירה קרירה והופעה חיה של להקת <b data-path-to-node="15,0,0" data-index-in-node="96">מרסדס בנד</b>.</p>
</li>
 	<li>
<p data-path-to-node="15,1,0"><b data-path-to-node="15,1,0" data-index-in-node="0">חוגגים מונדיאל (7.7 ו-9.7):</b> חובבי הכדורגל ייהנו מחוויית צפייה משותפת עם שידורים ישירים של משחקי המונדיאל שיוקרנו על מסכי ענק בפארק המנגלים שבמרכז עינב.</p>
</li>
 	<li>
<p data-path-to-node="15,2,0"><b data-path-to-node="15,2,0" data-index-in-node="0">פסטיבל היין (28.7-30.7):</b> פסטיבל היין המסורתי והאהוב חוזר לשלושה ימים של טעימות ואווירה טובה בפארק ענבה.</p>
</li>
</ul>
<h4 data-path-to-node="16">לו"ז שבועי קבוע: אירועים קרוב לבית</h4>
<p data-path-to-node="17">מעבר לאירועי השיא, לאורך כל חודשי הקיץ יתקיים לו"ז פעילויות קבוע בשכונות ובפארקים:</p>

<ul data-path-to-node="18">
 	<li>
<p data-path-to-node="18,0,0"><b data-path-to-node="18,0,0" data-index-in-node="0">ימי ראשון:</b> "ראשון ספורטיבי" עם יוגה בפארק הדגים (החל מהשעה 18:30), לצד "ראשון קיצי בסחלבים" – הפנינגים חווייתיים לכל המשפחה.</p>
</li>
 	<li>
<p data-path-to-node="18,1,0"><b data-path-to-node="18,1,0" data-index-in-node="0">ימי שלישי:</b> ערבי קולנוע משפחתיים עם סרטי קולנוע מדובבים שיוקרנו בשכונות השונות בעיר.</p>
</li>
 	<li>
<p data-path-to-node="18,2,0"><b data-path-to-node="18,2,0" data-index-in-node="0">ימי רביעי:</b> רכיבת אופניים חווייתית לאור ירח בפארק ענבה.</p>
</li>
 	<li>
<p data-path-to-node="18,3,0"><b data-path-to-node="18,3,0" data-index-in-node="0">ימי שישי:</b> חוגגים את סוף השבוע עם מסיבות מזרקות מרעננות במתחם המזרקות בענבה, ושעות סיפור תיאטרליות על דשא המרכז הרב תחומי.</p>
</li>
 	<li>
<p data-path-to-node="18,4,0"><b data-path-to-node="18,4,0" data-index-in-node="0">מוצאי שבת:</b> לילות הקיץ מתעוררים עם ריקודי עם למתחילים, לצד מופעי מוזיקה אינטימיים במסגרת לילות ענבה בפארק.</p>
</li>
</ul>
<p data-path-to-node="19">בעירייה קוראים לתושבים להתעדכן בפרטים המלאים ובשינויים האפשריים בלוח האירועים הדיגיטלי באתר העירייה, ומאחלים לכל תושבי מודיעין מכבים רעות קיץ בטוח, שמח וחגיגי!</p>
<p data-path-to-node="19"><img class="alignnone size-medium wp-image-7057" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/נועה-קירל-199x300.jpg" alt="" width="199" height="300" /> <img class="alignnone size-medium wp-image-7058" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/עילי-בוטנר-והילדים-החדשים-300x200.jpg" alt="" width="300" height="200" /> <img class="alignnone size-medium wp-image-7059" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/גירפות-300x300.jpg" alt="" width="300" height="300" /> <img class="alignnone size-medium wp-image-7060" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/עדן-חסון-200x300.jpg" alt="" width="200" height="300" /> <img class="alignnone size-medium wp-image-7061" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/עדן-בן-זקן-צילום-דניאל-אלסטר-300x204.jpeg" alt="" width="300" height="204" /> <img class="alignnone size-medium wp-image-7062" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/סיפור-לפני-שבת-לילדים-300x225.jpg" alt="" width="300" height="225" /> <img class="alignnone size-medium wp-image-7063" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/שכונה-בהפתעה-28.7-300x191.jpg" alt="" width="300" height="191" /> <img class="alignnone size-medium wp-image-7064" src="https://www.modiin4u.co.il/wp-content/uploads/2026/06/רוקדים-עם-ילדים-במזרקות-ענבה-002-300x200.jpg" alt="" width="300" height="200" /></p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2026/06/מרסדס-בנד.jpg', 'published', '2026-06-25 16:38:21') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
