insert into entity_categories (entity_type, entity_id, category_id) values ('article', '1193583a-8f7f-5570-8beb-797b65743ca2', '283e1d4d-6442-5ab4-8b69-6092432c8219') on conflict do nothing;
insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('ce9960d6-01a1-5e2d-b8ec-30a8c0773473', 'בשורה לרוכבים: אירוע "מודיעין רוכבת 2026" חוזר ובגדול עם מסלולים לכל המשפחה', 'modiin-news-496', '<p id="p-rc_787c71904647c139-27" data-path-to-node="1"><span data-path-to-node="1,0">תושבי מודיעין יכולים להתחיל להכין את האופניים והקסדות לקראת אחד מאירועי הספורט המרכזיים של השנה</span><span data-path-to-node="1,2">. אירוע "מודיעין רוכבת 2026" יתקיים ביום שישי, 2 באוקטובר 2026, וההרשמה אליו כבר נפתחה באתר העירייה</span><span data-path-to-node="1,4">. האירוע, בהובלת אגף הספורט בעיריית מודיעין מכבים רעות, מציע שילוב מושלם של ספורט, מוזיקה, מופעים והפנינג משפחתי לכל הגילאים</span><span data-path-to-node="1,6">.</span></p>
<p data-path-to-node="2"></p>
<p id="p-rc_787c71904647c139-28" data-path-to-node="2"><span data-path-to-node="2,0"><img class="alignnone size-medium wp-image-7179" src="https://www.modiin4u.co.il/wp-content/uploads/2026/08/מודיעין-רוכבת-צילום-תאוצה-נמרוד-הנגבי-300x200.jpeg" alt="" width="300" height="200" />ההזנקה לאירוע תצא מהספורטק העירוני שבשדרות מנחם בגין, כאשר השנה יוצעו שלושה מסלולים שונים כדי להתאים בדיוק לרמת הניסיון של כל משתתף</span><span data-path-to-node="2,2">:</span></p>

<ul data-path-to-node="3">
 	<li>
<p id="p-rc_787c71904647c139-29" data-path-to-node="3,0,0"><span data-path-to-node="3,0,0,0"><b data-path-to-node="3,0,0,0" data-index-in-node="0">מסלול מתקדם (12 ק"מ):</b> משלב קטעי כביש ושביל טבע אתגרי עבור רוכבים מנוסים יותר</span><span data-path-to-node="3,0,0,2">.</span></p>
</li>
 	<li>
<p id="p-rc_787c71904647c139-30" data-path-to-node="3,1,0"><span data-path-to-node="3,1,0,0"><b data-path-to-node="3,1,0,0" data-index-in-node="0">מסלול משפחות (6 ק"מ):</b> עובר בשילוב של כביש ושבילי טבע קלילים, מתאים למשפחות ולחובבי רכיבה</span><span data-path-to-node="3,1,0,2">.</span></p>
</li>
 	<li>
<p id="p-rc_787c71904647c139-31" data-path-to-node="3,2,0"><span data-path-to-node="3,2,0,0"><b data-path-to-node="3,2,0,0" data-index-in-node="0">מסלול קצר ונגיש (3 ק"מ):</b> מבוסס על כביש בלבד, ומושלם עבור רוכבים צעירים, מתחילים או כל מי שמחפש חוויה רגועה</span><span data-path-to-node="3,2,0,2">.</span></p>
</li>
</ul>
<p data-path-to-node="4">עם חציית קו הסיום, יקבלו הרוכבים מדליה מיוחדת ויוכלו להמשיך לחגוג במתחם הפאמפטרק הצמוד, שם ייהנו מהתנסות חופשית בליווי מדריכים מקצועיים.</p>
<p data-path-to-node="5"><img class="alignnone size-medium wp-image-7180" src="https://www.modiin4u.co.il/wp-content/uploads/2026/08/מודיעין-רוכבת-צילום-תאוצה-נמרוד-הנגבי-2-300x200.jpeg" alt="" width="300" height="200" /></p>
<p data-path-to-node="5">ההשתתפות באירוע מחייבת רכישת כרטיסים מראש באתר העירייה עד לתאריך 29.9.2026 בשעה 12:00 בצהריים. העלויות נגישות במיוחד לכל כיס: כרטיס בודד בעלות של 20 שקלים וכרטיס משפחתי המכסה עד ארבע נפשות במחיר של 60 שקלים בלבד. בנוסף, מי שאין ברשותו ציוד פרטי יוכל ליהנות מפתרון מושלם ולהזמין מראש אופניים וקסדה בהשאלה בעלות של 70 שקלים.</p>
<p data-path-to-node="6">באגף הספורט קוראים לכל תושבי העיר להקדים ולהירשם באתר העירייה, להצטרף לחגיגה המוטורית-ירוקה ולקחת חלק ביום ספורטיבי מהנה לכל המשפחה.</p>', null, 'https://www.modiin4u.co.il/wp-content/uploads/2026/08/מודיעין-רוכבת-צילום-תאוצה-נמרוד-הנגבי-1.jpeg', 'published', '2026-08-25 11:42:48') on conflict (id) do update set title = excluded.title, body = excluded.body, excerpt = excluded.excerpt, featured_image = excluded.featured_image, updated_at = now();
