insert into articles (id, title, slug, body, excerpt, featured_image, status, published_at) values ('58573e78-8115-5f26-a370-8f11cd30d7d8', 'שביל הגבעות הדרומיות - טיול קסום בטבע ליד מודיעין', 'southern-hills-trail', 'כשהשגרה לוחצת והנפש זקוקה לאוויר פתוח, אין כמו טיול בשביל הגבעות הדרומיות של מודיעין. במרחק דקות מהעיר מחכה לכם טבע קסום עם נופים פתוחים, פריחות עונתיות, אתרים היסטוריים ואוויר צלול.

